SET @uid = (SELECT `id` FROM `users` WHERE `email` = 'whitevelvetelf@gmail.com' LIMIT 1);

-- 80/20 Endurance — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = '8020endurance.com' OR LOWER(`name`) = LOWER('80/20 Endurance'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT '80/20 Endurance', NULL, 'https://www.8020endurance.com', NULL, NULL, '80/20 Endurance — тренувальні плани з бігу, тріатлону й велоспорту за принципом «80% легко, 20% важко» від Метта Фіцджеральда. Членство Team 80/20 включає AI-тренера Mind of Matt, що аналізує ваші реальні дані.', '80/20 Endurance offers running, triathlon and cycling plans built on Matt Fitzgerald''s 80% easy, 20% hard principle. The Team 80/20 membership includes Mind of Matt, an AI coach that reads your real training data.', '80/20 Endurance побудовано на однойменних книгах Метта Фіцджеральда: дослідження показують, що елітні спортсмени на витривалість приблизно 80% часу тренуються з низькою інтенсивністю і 20% — з високою. Більшість самостійних атлетів занадто напружуються в легкі дні й несуть утому в ключові тренування; плани 80/20 це виправляють. Доступні плани з бігу, тріатлону й велоспорту для різних дистанцій, рівнів і метрик інтенсивності. Членство Team 80/20 відкриває всі плани, а AI-тренер Mind of Matt, навчений на всіх працях Фіцджеральда, читає ваші тренувальні дані, підбирає план, відповідає на запитання й щопонеділка робить огляд тижня. Є калькулятор зон і навчальні матеріали.', '80/20 Endurance is based on Matt Fitzgerald''s best-selling books: research shows elite endurance athletes train about 80% at low intensity and 20% at high intensity. Most self-coached athletes go too hard on easy days and carry fatigue into key sessions; 80/20 plans fix that. Plans cover running, triathlon and cycling for different distances, levels and intensity metrics. The Team 80/20 membership unlocks every plan, and the Mind of Matt AI coach, trained on Fitzgerald''s complete body of work, reads your training data, picks a plan, answers questions and delivers a training review every Monday. There is also a zone calculator and learning resources.', 'Плани з бігу, тріатлону й велоспорту
Принцип 80% легко / 20% важко
AI-тренер Mind of Matt на ваших даних
Щотижневий огляд тренувань
Калькулятор зон інтенсивності
TrainingPeaks Premium у тарифі Gold', 'Running, triathlon and cycling plans
80% easy / 20% hard principle
Mind of Matt AI coach on your data
Weekly training review
Intensity zone calculator
TrainingPeaks Premium on Gold', 'Бігуни, тріатлоністи й велосипедисти-аматори, які тренуються самостійно.', 'Self-coached recreational runners, triathletes and cyclists.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = '8020endurance.com' OR LOWER(`name`) = LOWER('80/20 Endurance')) ORDER BY `id` LIMIT 1);
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE @pid IS NOT NULL AND c.`slug` = 'sports' LIMIT 1;
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE @pid IS NOT NULL AND c.`slug` = 'sports' AND s.`name` = 'Масовий фітнес і тренування' LIMIT 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'short_description', 'en', '80/20 Endurance offers running, triathlon and cycling plans built on Matt Fitzgerald''s 80% easy, 20% hard principle. The Team 80/20 membership includes Mind of Matt, an AI coach that reads your real training data.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', '80/20 Endurance is based on Matt Fitzgerald''s best-selling books: research shows elite endurance athletes train about 80% at low intensity and 20% at high intensity. Most self-coached athletes go too hard on easy days and carry fatigue into key sessions; 80/20 plans fix that. Plans cover running, triathlon and cycling for different distances, levels and intensity metrics. The Team 80/20 membership unlocks every plan, and the Mind of Matt AI coach, trained on Fitzgerald''s complete body of work, reads your training data, picks a plan, answers questions and delivers a training review every Monday. There is also a zone calculator and learning resources.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'main_features', 'en', 'Running, triathlon and cycling plans
80% easy / 20% hard principle
Mind of Matt AI coach on your data
Weekly training review
Intensity zone calculator
TrainingPeaks Premium on Gold', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'target_audience', 'en', 'Self-coached recreational runners, triathletes and cyclists.', 'manual' FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `plan_name_en`, `price`, `period`, `description`, `description_en`) SELECT @pid, 'Team 80/20 Gold', 'Team 80/20 Gold', 16.58, 'month', 'При оплаті за рік; усі плани, TrainingPeaks Premium, Mind of Matt, підтримка тренера; 30 днів гарантії повернення', 'Billed annually; every plan, TrainingPeaks Premium, Mind of Matt, coach email support; 30-day money-back guarantee' FROM DUAL WHERE @new = 1;
SET @plan = IF(@new = 1, (SELECT `id` FROM `pricing_plans` WHERE `product_id` = @pid AND `plan_name` = 'Team 80/20 Gold' ORDER BY `id` DESC LIMIT 1), NULL);
INSERT IGNORE INTO `pricing_plan_translations` (`plan_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @plan, 'plan_name', 'en', 'Team 80/20 Gold', 'manual' FROM DUAL WHERE @plan IS NOT NULL;
INSERT IGNORE INTO `pricing_plan_translations` (`plan_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @plan, 'description', 'en', 'Billed annually; every plan, TrainingPeaks Premium, Mind of Matt, coach email support; 30-day money-back guarantee', 'manual' FROM DUAL WHERE @plan IS NOT NULL;

-- AllTrails — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'alltrails.com' OR LOWER(`name`) = LOWER('AllTrails'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'AllTrails', NULL, 'https://www.alltrails.com', NULL, NULL, 'AllTrails — застосунок для походів, велосипеда й бігу з гідами, картами, фото й відгуками для понад 500 000 стежок: живе відстеження, офлайн-карти, конструктор власних маршрутів і планування поїздок. Є офлайн-режим.', 'AllTrails is an app for hiking, biking and running with guides, maps, photos and reviews for 500,000+ trails: live tracking, offline maps, a custom route builder and trip planning.', 'AllTrails допомагає знайти наступну пригоду на природі. Каталог містить кураторські гіди, карти, фотографії та відгуки для понад 500 000 стежок по всьому світу, а пошук працює за містом, парком чи назвою стежки. Можна переглядати популярні національні парки й міста для прогулянок. Під час активності живе відстеження не дасть пропустити поворот, а після — можна переглянути підсумок і поділитися ним. Офлайн-карти для стежок і парків дозволяють орієнтуватися навіть без зв''язку. Конструктор маршрутів допомагає створити чи відредагувати ідеальний маршрут, а функція поїздок — спланувати подорож. Розширені можливості доступні в платній підписці.', 'AllTrails helps you find your next outdoor adventure. The catalog holds curated guides, maps, photos and reviews for 500,000+ trails worldwide, searchable by city, park or trail name. You can browse popular national parks and cities. During an activity, live tracking keeps you from missing a turn, and afterwards you can relive and share a recap. Offline maps for trails and parks let you navigate without service. The route builder helps you create or edit the perfect trail, and trips help you plan a journey. Advanced features come with a paid subscription.', '500 000+ стежок із гідами й відгуками
Живе відстеження маршруту
Офлайн-карти
Конструктор власних маршрутів
Планування поїздок', '500,000+ trails with guides and reviews
Live route tracking
Offline maps
Custom route builder
Trip planning', 'Туристи, бігуни й велосипедисти, які шукають і планують маршрути на природі.', 'Hikers, runners and cyclists who find and plan outdoor routes.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'alltrails.com' OR LOWER(`name`) = LOWER('AllTrails')) ORDER BY `id` LIMIT 1);
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE @pid IS NOT NULL AND c.`slug` = 'sports' LIMIT 1;
