INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'AllTrails helps you find your next outdoor adventure. The catalog holds curated guides, maps, photos and reviews for 500,000+ trails worldwide, searchable by city, park or trail name. You can browse popular national parks and cities. During an activity, live tracking keeps you from missing a turn, and afterwards you can relive and share a recap. Offline maps for trails and parks let you navigate without service. The route builder helps you create or edit the perfect trail, and trips help you plan a journey. Advanced features come with a paid subscription.', 'manual' FROM DUAL WHERE @new = 1;
