SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'alomoves.com' OR LOWER(`name`) = LOWER('Alo Moves'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Alo Moves', NULL, 'https://www.alomoves.com', NULL, NULL, 'Alo Moves (ALO Wellness Club) — онлайн-студія йоги, фітнесу й медитації: тисячі відеозанять від інструкторів — йога, HIIT, барре, пілатес — з чіткою шкалою складності від вступного до просунутого рівня.', 'Alo Moves (ALO Wellness Club) is an online yoga, fitness and meditation studio: thousands of video classes from instructors — yoga, HIIT, barre, Pilates — with a clear difficulty scale from introductory to advanced.', 'Alo Moves, нині ALO Wellness Club, — це домашня онлайн-студія від бренду Alo. У ній тисячі відеоуроків йоги, фітнесу та медитації від досвідчених інструкторів: йога різних стилів, HIIT, барре, пілатес та інші формати. Щоб легко підібрати заняття, усі серії мають позначки складності та інтенсивності. Вступні класи розраховані на тих, хто ніколи не займався: вони повільні, коротші й детально пояснюють кожну позу. Початковий рівень допомагає вибудувати регулярну практику, помірний — додає складніші варіації, а далі йдуть просунуті програми. Окремий гід пояснює, як обрати серію під свій рівень і мету.', 'Alo Moves, now ALO Wellness Club, is an at-home online studio from the Alo brand. It offers thousands of yoga, fitness and meditation video classes from experienced instructors: various yoga styles, HIIT, barre, Pilates and other formats. To make choosing easy, every series is tagged by difficulty and intensity. Introductory classes are for people who have never practiced: they are slower, shorter and break down each pose in detail. Beginner classes help build a regular practice, moderate ones add harder variations, followed by advanced programs. A dedicated guide explains how to pick a series for your level and goal.', 'Тисячі відеозанять йоги, фітнесу й медитації
HIIT, барре, пілатес та різні стилі йоги
Шкала складності й інтенсивності для кожної серії
Вступні класи для тих, хто ніколи не займався
Гід із вибору програми під свій рівень', 'Thousands of yoga, fitness and meditation videos
HIIT, barre, Pilates and many yoga styles
Difficulty and intensity scale for every series
Introductory classes for complete beginners
Guide to choosing a program for your level', 'Люди будь-якого рівня, які хочуть займатися йогою, пілатесом чи фітнесом удома за відеоуроками.', 'People of any level who want to do yoga, Pilates or fitness at home with video classes.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
