-- ASICS Runkeeper — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'runkeeper.com' OR LOWER(`name`) = LOWER('ASICS Runkeeper'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'ASICS Runkeeper', NULL, 'https://runkeeper.com', NULL, NULL, 'ASICS Runkeeper — застосунок для бігу, який працює як тренер: допомагає поставити мету, тренуватися за гнучкими планами й аудіотренуваннями з коучами та відстежувати прогрес від першої пробіжки до забігу.', 'ASICS Runkeeper is a running app that works like a coach: it helps you set a goal, train with flexible plans and guided audio workouts from coaches, and track progress from your first run to race day.', 'ASICS Runkeeper — застосунок і спільнота бігунів від ASICS. Він підходить і тим, хто тільки починає бігати, і тим, у кого вже багато кілометрів за плечима. Як справжній тренер, застосунок допомагає поставити мету, тренуватися під неї та відстежувати прогрес. Гнучкі тренувальні плани підлаштовуються під ваш графік і поточний рівень, а аудіотренування з тренерами на кшталт «I Am A Runner» або «Tiny Wins» ведуть вас протягом пробіжки. Розширена аналітика показує, як змінюються результати. Окремі розділи присвячені тренуванням, підготовці до забігів і блогу з порадами, а спільнота допомагає не втрачати мотивацію.', 'ASICS Runkeeper is a running app and community from ASICS. It suits both people just starting to run and those with many miles behind them. Like a real coach, the app helps you set a goal, train for it and track your progress. Flexible training plans adapt to your schedule and current level, and guided audio workouts with coaches, such as I Am A Runner or Tiny Wins, lead you through a run. Advanced insights show how your results change. Separate sections cover training, race preparation and a blog with tips, and the community helps you stay motivated.', 'Відстеження пробіжок і прогресу
Гнучкі тренувальні плани під ваш графік
Аудіотренування з тренерами
Підготовка до забігів
Аналітика результатів
Спільнота бігунів', 'Run and progress tracking
Flexible plans that fit your schedule
Guided audio workouts with coaches
Race preparation
Performance insights
Runner community', 'Бігуни-аматори — від новачків до тих, хто готується до забігу.', 'Recreational runners, from beginners to those preparing for a race.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
