-- ATHLEAN-X — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'athleanx.com' OR LOWER(`name`) = LOWER('ATHLEAN-X'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'ATHLEAN-X', NULL, 'https://athleanx.com', NULL, NULL, 'ATHLEAN-X — науково обґрунтовані тренувальні програми фізіотерапевта й тренера Джеффа Кавальєре для чоловіків і жінок удома чи в залі, статті й відео про тренування, спортивні добавки, еспандери й одяг.', 'ATHLEAN-X offers science-based training programs by physical therapist and coach Jeff Cavaliere for men and women at home or in the gym, plus training articles and videos, supplements, resistance bands and apparel.', 'ATHLEAN-X пропонує науково обґрунтовані програми та добавки, які допомагають виглядати, рухатися й почуватися як атлет — удома чи в залі. Засновник Джефф Кавальєре — фізіотерапевт і тренер, тому програми поєднують силову підготовку з увагою до правильної техніки та здоров''я суглобів. Каталог програм розрахований на різні цілі й рівні, а доступ до них відкривається в особистому порталі. На сайті є безліч безплатних статей і відео для чоловіків і жінок, історії результатів, розділ коучингу та живі заходи. Окремо продаються передтренувальні комплекси, протеїн, добавки для відновлення, набори для чоловіків і жінок, еспандери Elast-X, спорядження й одяг.', 'ATHLEAN-X offers science-backed programs and supplements that help you look, move and feel like an athlete — at home or in the gym. Founder Jeff Cavaliere is a physical therapist and coach, so the programs combine strength training with attention to proper technique and joint health. The program catalog covers different goals and levels, accessed through a personal portal. The site has plenty of free articles and videos for men and women, results stories, a coaching section and live events. It also sells pre-workout, protein, recovery supplements, men''s and women''s stacks, Elast-X resistance bands, gear and apparel.', 'Науково обґрунтовані програми тренувань
Для дому й залу
Безплатні статті й відео
Коучинг і живі заходи
Спортивні добавки й еспандери', 'Science-based training programs
For home and gym
Free articles and videos
Coaching and live events
Supplements and resistance bands', 'Чоловіки й жінки, які хочуть тренуватися як атлети вдома чи в залі.', 'Men and women who want to train like athletes at home or in the gym.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
