SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'avironactive.com' OR LOWER(`name`) = LOWER('Aviron'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Aviron', NULL, 'https://www.avironactive.com', NULL, NULL, 'Aviron — інтерактивні гребні тренажери, велотренажери, бігові доріжки й тренажер для пресу з вбудованими іграми: гонки, сценічні маршрути, програми та стрімінг роблять кардіо на все тіло цікавішим. Є 30 днів на пробу.', 'Aviron makes interactive rowers, bikes, treadmills and a core trainer with built-in games: races, scenic routes, guided programs and streaming make full-body cardio more engaging.', 'Aviron поєднує кардіотренажери з ігровою психологією. У лінійці — гребні тренажери Strong Series і Strong Go (сумісний з iPad), велотренажери Fit Bike і безшумний Fit Bike S, бігові доріжки Justice, Podium і Summit з нахилом до 42%, а також ігровий тренажер для пресу ABS Hero. Кожне тренування мотивує через змагання: гонки з іншими, сценічні маршрути, керовані програми й розважальний стрімінг, щоб людина не кидала заняття. Тренажери мають вбудований екран з іграми й класами. Обладнання можна оплатити з HSA/FSA у США, на нього діє 20-річна гарантія та 30-денний пробний період без ризику. Тренажери підходять для всієї родини.', 'Aviron combines cardio machines with game psychology. The lineup includes the Strong Series and iPad-compatible Strong Go rowers, the Fit Bike and silent Fit Bike S, the Justice, Podium and Summit treadmills with up to 42% incline, and the gamified ABS Hero core trainer. Every workout motivates through competition: races against others, scenic routes, guided programs and streaming entertainment keep people coming back. Machines have a built-in screen with games and classes. Equipment is HSA/FSA eligible in the US and comes with a 20-year warranty and a 30-day risk-free trial. The machines suit the whole family.', 'Гребні, вело- й бігові тренажери з іграми
Гонки, сценічні маршрути й програми
Стрімінг розваг під час тренування
Ігровий тренажер для пресу ABS Hero
30-денний пробний період', 'Rowers, bikes and treadmills with games
Races, scenic routes and programs
Streaming entertainment while training
Gamified ABS Hero core trainer
30-day risk-free trial', 'Люди, яким бракує мотивації для кардіо вдома і які хочуть тренуватися в ігровому форматі.', 'People who lack motivation for cardio at home and want to train in a game format.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
