INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Bikemap', NULL, 'https://www.bikemap.net', NULL, NULL, 'Bikemap — велика колекція велосипедних маршрутів, планувальник маршрутів і застосунок-велокомп''ютер: знаходьте маршрути спільноти для шосе, MTB чи міста, створюйте власні та відкривайте нові веломісця.', 'Bikemap is a large collection of cycling routes, a route planner and a bike computer app: find community routes for road, MTB or city riding, create your own and discover new cycling destinations.', 'Bikemap допомагає знайти ідеальний маршрут для велосипеда та спланувати власний. У колекції — маршрути від спільноти з різних країн із фільтрами для шосейного, гірського та міського велосипеда, з довжиною та набором висоти. Планувальник маршрутів дозволяє створювати власні веломаршрути й треки, а мобільний застосунок працює як велокомп''ютер із навігацією під час поїздки. На сайті можна відкривати найкрасивіші велонапрямки й ділитися своїми маршрутами з іншими. Преміум-функції розширюють можливості навігації та планування, а в магазині є аксесуари для велосипедистів. Сервіс підходить як для щоденних поїздок містом, так і для довгих велоподорожей.', 'Bikemap helps you find the perfect cycling route and plan your own. The collection includes community routes from many countries with filters for road, mountain and city bikes, plus length and elevation gain. The route planner lets you create your own bike routes and trails, and the mobile app works as a bike computer with navigation while you ride. On the website you can discover stunning cycling destinations and share your routes with others. Premium features extend navigation and planning, and the shop sells accessories for cyclists. It suits both daily city rides and long cycling tours.', 'Колекція маршрутів від спільноти
Фільтри для шосе, MTB і міста
Планувальник маршрутів
Застосунок-велокомп''ютер із навігацією
Преміум-функції', 'Community route collection
Filters for road, MTB and city
Route planner
Bike computer app with navigation
Premium features', 'Велосипедисти, які шукають маршрути або прокладають власні.', 'Cyclists looking for routes or planning their own.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
