-- BodBot — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'bodbot.com' OR LOWER(`name`) = LOWER('BodBot'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'BodBot', NULL, 'https://www.bodbot.com', NULL, NULL, 'BodBot — цифровий персональний тренер і дієтолог з AI: безплатні персональні плани тренувань і харчування під будь-яку фітнес-, спортивну чи оздоровчу мету, покрокові вказівки вдома або в залі, адаптація з кожним повторенням.', 'BodBot is an AI digital personal trainer and nutritionist: free personalized training and nutrition plans for any fitness, athletic or health goal, step-by-step guidance at home or in the gym and adaptation with every rep.', 'BodBot — цифровий персональний тренер, дієтолог і коуч, який складає персоналізовані плани тренувань і харчування для досягнення будь-якої фітнес-, спортивної чи оздоровчої мети. AI-тренування дають покрокові вказівки вдома або в залі. Шаблонних планів тут немає: кожне тренування, вправа, підхід і повторення налаштовуються під ваші цілі, тіло й прогрес — від загального рівня способу життя й біометрії до сьогоднішніх рухових патернів. Застосунок адаптується з кожним повторенням, тож план змінюється разом із вами. Розділи сайту охоплюють тренування, харчування, дані та результати. Персональні плани можна отримати безплатно.', 'BodBot is a digital personal trainer, nutritionist and coach that builds personalized training and nutrition plans for any fitness, athletic or health goal. AI workouts provide step-by-step guidance at home or in the gym. There are no cookie-cutter plans: every workout, exercise, set and rep is tailored to your goals, body and progress — from the macro level of lifestyle and biometrics to the micro level of today''s movement patterns. The app adapts with every rep, so the plan changes with you. The site covers training, nutrition, data and results. Personalized plans are available for free.', 'AI-тренування з покроковими вказівками
Персональний план харчування
Адаптація з кожним повторенням
Для дому й залу
Безплатні персональні плани', 'AI workouts with step-by-step guidance
Personal nutrition plan
Adaptation with every rep
For home and gym
Free personalized plans', 'Люди, які хочуть персональний план тренувань і харчування без живого тренера.', 'People who want a personal training and nutrition plan without a human trainer.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
