SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'bodi.com' OR LOWER(`name`) = LOWER('BODi'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'BODi', NULL, 'https://www.bodi.com', NULL, NULL, 'BODi (раніше Beachbody) — стрімінгова платформа фітнес-програм, як-от P90X, із планами харчування та спортивними добавками. Підписка відкриває тренування для дому, програми харчування й живі заняття, а в магазині є протеїн і добавки.', 'BODi (formerly Beachbody) is a streaming platform for fitness programs such as P90X, with nutrition plans and sports supplements. A subscription unlocks at-home workouts, nutrition programs and live classes.', 'BODi — це нова назва Beachbody, відомого розробника домашніх фітнес-програм на кшталт P90X. Платформа поєднує стрімінг тренувань, плани харчування й спортивне харчування. За підпискою BODi користувач отримує доступ до фітнес-планів, бібліотеки тренувань для занять удома та програм харчування. Окремо в магазині продаються протеїнові коктейлі Shakeology, добавки для відновлення, гідратації та енергії, а також обладнання для домашніх тренувань. Підписку можна оформити помісячно або на рік; на час акцій річний доступ дешевшає. Платформа розрахована і на новачків, і на тих, хто вже має досвід домашніх програм, а програми харчування допомагають поєднати тренування з режимом.', 'BODi is the new name of Beachbody, the maker of well-known home fitness programs such as P90X. The platform combines workout streaming, nutrition plans and sports nutrition. A BODi subscription gives access to fitness plans, a library of at-home workouts and nutrition programs. The store separately sells Shakeology shakes, recovery, hydration and energy supplements, and home workout equipment. You can subscribe monthly or annually; during promotions annual access is discounted. The platform suits both beginners and people with home-program experience, and the nutrition programs help pair workouts with an eating routine.', 'Стрімінг домашніх фітнес-програм, зокрема P90X
Плани харчування під цілі
Магазин добавок і спортивного харчування
Обладнання для тренувань удома
Помісячна або річна підписка', 'Streaming of home fitness programs, including P90X
Goal-based nutrition plans
Supplements and sports nutrition store
Home workout equipment
Monthly or annual subscription', 'Люди, які тренуються вдома за структурованими програмами й хочуть поєднати тренування з планом харчування.', 'People who work out at home with structured programs and want to pair training with a nutrition plan.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
