-- C25K — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'c25k.com' OR LOWER(`name`) = LOWER('C25K'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'C25K', NULL, 'https://c25k.com', NULL, NULL, 'C25K (Couch to 5K) — програма, яка за 9 тижнів допомагає майже будь-кому перейти від дивана до бігу на 5 км або 30 хвилин без зупинки: м''який старт із чергуванням ходьби й бігу та поступовим збільшенням навантаження.', 'C25K (Couch to 5K) is a 9-week program that takes almost anyone from the couch to running 5 km or 30 minutes non-stop: a gentle start alternating walking and running with a gradual increase in load.', 'Couch to 5K — відома програма, створена, щоб за дев''ять тижнів привести практично будь-яку людину від сидячого способу життя до бігу на 5 кілометрів або 30 хвилин. Її секрет — м''яке введення в рух: спочатку ви чергуєте ходьбу та біг на короткі відрізки, а потім поступово збільшуєте частку бігу. Такий підхід зменшує ризик перевантажень і допомагає не кинути на півдорозі. На сайті розповідають історії людей, які завдяки C25K кинули курити, схудли, а згодом пробігли марафони та ультрамарафони. Програма підходить новачкам, людям після перерви та всім, хто хоче сформувати звичку бігати. Такий формат підходить і тим, хто повертається до бігу після тривалої перерви.', 'Couch to 5K is a well-known program designed to take just about anyone from a sedentary lifestyle to running 5 kilometres or 30 minutes in nine weeks. Its secret is a gentle introduction to movement: at first you alternate walking and running short distances, then gradually increase the running portion. This approach reduces the risk of overload and helps you avoid quitting halfway. The site shares stories of people who quit smoking, lost weight and later ran marathons and ultramarathons thanks to C25K. The program suits beginners, people returning after a break and anyone who wants to build a running habit. This format also suits people returning to running after a long break.', '9-тижнева програма до 5 км
Чергування ходьби й бігу
Поступове збільшення навантаження
Для повних новачків
Історії успіху', '9-week program to 5K
Alternating walking and running
Gradual load increase
For complete beginners
Success stories', 'Люди без досвіду бігу, які хочуть почати бігати з нуля.', 'People with no running experience who want to start from scratch.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
