INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'short_description', 'en', 'C25K (Couch to 5K) is a 9-week program that takes almost anyone from the couch to running 5 km or 30 minutes non-stop: a gentle start alternating walking and running with a gradual increase in load.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Couch to 5K is a well-known program designed to take just about anyone from a sedentary lifestyle to running 5 kilometres or 30 minutes in nine weeks. Its secret is a gentle introduction to movement: at first you alternate walking and running short distances, then gradually increase the running portion. This approach reduces the risk of overload and helps you avoid quitting halfway. The site shares stories of people who quit smoking, lost weight and later ran marathons and ultramarathons thanks to C25K. The program suits beginners, people returning after a break and anyone who wants to build a running habit. This format also suits people returning to running after a long break.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'main_features', 'en', '9-week program to 5K
Alternating walking and running
Gradual load increase
For complete beginners
Success stories', 'manual' FROM DUAL WHERE @new = 1;
