SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'calisteniapp.com' OR LOWER(`name`) = LOWER('Calisteniapp'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Calisteniapp', NULL, 'https://calisteniapp.com', NULL, NULL, 'Calisteniapp — застосунок калістеніки для всіх рівнів і цілей: понад 450 безплатних тренувань без обладнання, програми на силу, гіпертрофію, з обтяженням, статику й силові елементи, кільця, витривалість і вихід сили.', 'Calisteniapp is a calisthenics app for all levels and goals: 450+ free no-equipment workouts, programs for strength, hypertrophy, weighted work, statics and power moves, rings, endurance and the muscle-up.', 'Calisteniapp — повноцінний застосунок для тренувань із власною вагою вдома чи на вулиці. Він підлаштовується під ваші цілі й рівень — від базових вправ для новачків до складних елементів стрит-воркауту. Тренування розділено за напрямами: сила, гіпертрофія, вправи з обтяженням, статика й силові елементи, кільця, витривалість, а також окремі програми для освоєння виходу сили. Почати можна безплатно — доступно понад 450 тренувань без обладнання, — а далі набирати м''язи, ставати сильнішим і прогресувати. Застосунок доступний на Google Play і App Store, на сайті є блог, журнал змін і служба підтримки.', 'Calisteniapp is a complete bodyweight training app for home or outdoors. It adapts to your goals and level — from beginner bodyweight routines to advanced street workouts. Workouts are organized by focus: strength, hypertrophy, weighted training, statics and power moves, rings, endurance, plus dedicated programs for learning the muscle-up. You can start for free with 450+ no-equipment workouts, then build muscle, get stronger and keep progressing. The app is available on Google Play and the App Store, and the site has a blog, a changelog and support.', '450+ безплатних тренувань
Програми на силу й гіпертрофію
Статика, силові елементи й кільця
Освоєння виходу сили
Від новачка до просунутого рівня', '450+ free workouts
Strength and hypertrophy programs
Statics, power moves and rings
Muscle-up programs
Beginner to advanced', 'Любителі калістеніки та воркауту, які тренуються вдома чи на майданчику.', 'Calisthenics and street workout enthusiasts training at home or outdoors.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
