-- CalTopo — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'caltopo.com' OR LOWER(`name`) = LOWER('CalTopo'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'CalTopo', NULL, 'https://caltopo.com', NULL, NULL, 'CalTopo — програма для планування пригод і картографування бекколу: спільне створення карт, обмін геолокацією, офлайн-режим, дані в реальному часі, шари карт, друк і запис треків для окремих людей і команд.', 'CalTopo is adventure planning and backcountry mapping software: collaborative map building, location sharing, offline use, real-time data, map layers, printing and track recording for individuals and teams.', 'CalTopo — сервіс картографування, що допомагає планувати пригоди від глибокого бекколу до найближчого парку. Можна досліджувати місцевість, планувати маршрути, ділитися картами й брати їх із собою на мобільний пристрій. Доступні дані в реальному часі, різні шари карт під ваші потреби, друк карт і запис треків. Для команд CalTopo пропонує спільну ГІС-картографію: кілька людей можуть одночасно будувати карту, а функція обміну геолокацією допомагає бачити одне одного на місцевості. Офлайн-режим дозволяє користуватися картами без зв''язку. Є окремі тарифи для окремих користувачів і груп, блог і довідка.', 'CalTopo is a mapping service that helps you plan adventures from deep backcountry to your backyard. You can research terrain, plan routes, share maps and take them with you on a mobile device. It offers real-time data, map layers to suit your needs, map printing and track recording. For teams CalTopo provides collaborative GIS mapping: several people can build a map at once, and location sharing helps you see each other in the field. Offline mode lets you use maps without service. There are plans for individuals and groups, a blog and help.', 'Планування маршрутів
Шари карт і дані в реальному часі
Спільне картографування для команд
Обмін геолокацією
Офлайн-режим
Друк карт і запис треків', 'Route planning
Map layers and real-time data
Collaborative team mapping
Location sharing
Offline mode
Map printing and track recording', 'Туристи, лижники-фрірайдери, рятувальні команди й організатори походів.', 'Hikers, backcountry skiers, rescue teams and trip organizers.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
