SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'joincarbon.com' OR LOWER(`name`) = LOWER('Carbon'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Carbon', NULL, 'https://www.joincarbon.com', NULL, NULL, 'Carbon — розумний дієтичний коуч для iOS та Android від експертів із харчування: персональний план макронутрієнтів, простий облік їжі та щотижневе коригування плану під ваш прогрес для схуднення чи набору м''язів.', 'Carbon is a smart diet coach for iOS and Android built by nutrition experts: a personalized macro plan, easy food tracking and weekly plan adjustments based on your progress for fat loss or muscle gain.', 'Carbon — застосунок для коучингу з харчування, створений фахівцями з нутриціології. Принцип простий, науковий і стійкий: ви ставите мету — привести себе у форму, схуднути чи набрати м''язи, — а застосунок складає персональний план макронутрієнтів. Облік їжі зроблено максимально зручним, а щотижня Carbon динамічно коригує план, ґрунтуючись на ваших реальних результатах, як це робив би особистий дієтолог. За словами розробників, це макро-коучинг за частку вартості індивідуальних консультацій. Підписка доступна помісячно, на півроку або на рік, її можна змінити або скасувати будь-коли. На сайті також є блог, магазин і безплатний гід для підписників розсилки.', 'Carbon is a nutrition coaching app created by nutrition experts. The principle is simple, scientific and sustainable: you set a goal — get fit, lose weight or build muscle — and the app builds a personalized macro plan. Food tracking is designed to be as easy as possible, and every week Carbon dynamically adjusts your plan based on your real results, as a personal dietitian would. The developers describe it as macro coaching for a fraction of the price of one-on-one coaching. Subscriptions are monthly, six-monthly or yearly and can be changed or canceled anytime. The site also has a blog, a shop and a free guide for newsletter subscribers.', 'Персональний план макронутрієнтів
Простий облік їжі
Щотижневе коригування плану
Цілі: схуднення, форма, м''язи
Гнучка підписка', 'Personalized macro plan
Easy food tracking
Weekly plan adjustments
Goals: fat loss, fitness, muscle
Flexible subscription', 'Ті, хто тренується й хоче контролювати харчування для схуднення чи набору маси.', 'People who train and want to control nutrition for fat loss or muscle gain.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
