-- Charity Miles — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'charitymiles.org' OR LOWER(`name`) = LOWER('Charity Miles'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Charity Miles', NULL, 'https://charitymiles.org', NULL, NULL, 'Charity Miles — застосунок, у якому кожна пройдена чи пробігла миля збирає гроші й увагу для обраної благодійної організації; рішення для благодійних фондів, корпоративних спонсорів і програм залучення працівників.', 'Charity Miles is an app where every mile you walk or run raises money and awareness for a charity you choose, with solutions for charities, corporate sponsors and employee engagement programs.', 'Charity Miles допомагає людям, благодійним організаціям і компаніям впливати на світ із кожним кроком. Окремі користувачі можуть просто ходити, бігати чи займатися протягом дня й збирати кошти та увагу для своєї улюбленої благодійної організації, отримуючи додатковий стимул рухатися. Благодійні організації отримують новий спосіб залучати прихильників, а компанії — інструмент для підвищення добробуту працівників і програм корпоративної соціальної відповідальності. Бренди з місією можуть ставати спонсорами й об''єднувати учасників навколо спільних цінностей. На сайті пояснено, як це працює, є розділи для учасників, працедавців, спонсорів і фондів, а також блог.', 'Charity Miles helps people, charities and companies make an impact with every step. Individuals can simply walk, run or work out through the day and raise money and awareness for their favorite charity, getting an extra reason to move. Charities get a new way to engage supporters, and companies get a tool to improve employee well-being and corporate social responsibility programs. Mission-driven brands can become sponsors and engage members around shared values. The site explains how it works and has sections for members, employers, sponsors and charities, plus a blog.', 'Збір коштів для благодійності за кілометри
Підтримка ходьби, бігу й тренувань
Рішення для благодійних організацій
Програми залучення працівників
Корпоративне спонсорство', 'Raise money for charity by the mile
Supports walking, running and workouts
Solutions for charities
Employee engagement programs
Corporate sponsorship', 'Люди, яких мотивує допомога іншим, благодійні фонди та компанії.', 'People motivated by helping others, charities and companies.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
