SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'clmbr.com' OR LOWER(`name`) = LOWER('CLMBR'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'CLMBR', NULL, 'https://clmbr.com', NULL, NULL, 'CLMBR — підключений вертикальний тренажер-скелелаз для дому й комерційних залів: низькоударне кардіо й силове тренування всього тіла за менший час, із членством, інструкторами та спільнотою. Є версії для дому та залів.', 'CLMBR is a connected vertical climbing machine for homes and commercial gyms: low-impact, full-body cardio and strength in less time, with a membership, instructors and a community.', 'CLMBR — вертикальний тренажер, що імітує скелелазіння. Рух задіює руки, ноги й сідниці одночасно, тож окремі дні для різних груп м''язів стають одним тренуванням. Навантаження низькоударне, тому тренажер підходить людям різного віку й рівня та придатний для тривалого використання. Компанія посилається на дослідження, згідно з якими під час вертикального лазіння пульс і споживання кисню вищі, ніж під час бігу на доріжці чи веслування, а за 30 хвилин можна спалити до 600 калорій. CLMBR пропонується для дому та в комерційному виконанні для залів і студій. Членство відкриває заняття з інструкторами, рівні та спільноту користувачів.', 'CLMBR is a vertical machine that mimics climbing. The movement works arms, legs and glutes at once, so separate arm and leg days become one workout. The load is low-impact, so the machine suits people of different ages and levels and can be used for life. The company cites research showing higher heart rate and oxygen consumption during vertical climbing than during treadmill running or rowing, and up to 600 calories burned in a 30-minute session. CLMBR comes in home and commercial versions for gyms and studios. The membership unlocks instructor-led classes, levels and a user community.', 'Вертикальне лазіння на все тіло
Низькоударне кардіо й силове навантаження
Членство з інструкторами й рівнями
Версії для дому та комерційних залів
Компактний формат', 'Full-body vertical climbing
Low-impact cardio and strength
Membership with instructors and levels
Home and commercial versions
Compact footprint', 'Люди, які хочуть ефективне кардіо без ударного навантаження вдома, а також зали й студії.', 'People who want effective low-impact cardio at home, as well as gyms and studios.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
