SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'coopah.com' OR LOWER(`name`) = LOWER('Coopah'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Coopah', NULL, 'https://www.coopah.com', NULL, NULL, 'Coopah — застосунок персонального бігового коучингу від фахівців: тренування під вашу мету коригують живі тренери, сесії надходять на годинник, є силові вправи та відстеження прогресу; тиждень безплатно.', 'Coopah is a personalized run coaching app led by performance specialists: training for your goal is adjusted by human coaches, sessions sync to your watch, plus strength work and progress tracking; one week free.', 'Coopah — біговий застосунок, у якому плани складають і коригують справжні тренери, а не лише алгоритм. Ви ставите мету, отримуєте персональну програму, а тренери стежать за прогресом і підлаштовують навантаження. Серед тренерів — Ейліш Макколган, чемпіонка Ігор Співдружності на 10 000 м, Джеймс Ті, тренер збірної Великої Британії, та Емма Пауелл, фізіотерапевтка й легкоатлетка. Тренування автоматично синхронізуються з вашим пристроєм, прогрес наочно видно в застосунку, а силові вправи й вправи на загальну фізичну підготовку допомагають бігати без травм. Перший тиждень коучингу безплатний, скасувати можна будь-коли.', 'Coopah is a running app where plans are built and adjusted by real coaches, not just an algorithm. You set a goal, get a personal program, and coaches follow your progress and adjust the load. The coaches include Eilish McColgan, Commonwealth Games 10,000m champion, James Thie, a GB team coach, and Emma Powell, a physiotherapist and international athlete. Workouts sync automatically to your device, progress is clearly tracked in the app, and strength and conditioning work helps you run injury-free. The first week of coaching is free and you can cancel anytime.', 'Персональний план під мету
Коригування тренерами-фахівцями
Синхронізація сесій із годинником
Силова підготовка для бігунів
Відстеження прогресу
Тиждень безплатно', 'Personal plan for your goal
Adjustments by specialist coaches
Session sync to your watch
Strength work for runners
Progress tracking
One week free', 'Бігуни будь-якого рівня, які хочуть тренуватися за планом від професійних тренерів.', 'Runners of any level who want to train with a plan from professional coaches.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
