-- Crimpd — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'crimpd.com' OR LOWER(`name`) = LOWER('Crimpd'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Crimpd', NULL, 'https://www.crimpd.com', NULL, NULL, 'Crimpd — застосунок для тренувань зі скелелазіння: структуровані тренування від Тома Рендалла й Оллі Торра на витривалість, силу пальців і потужність, таймер для фінгерборду, журнал і аналітика навантаження.', 'Crimpd is a climbing training app: structured workouts by Tom Randall and Ollie Torr for endurance, finger strength and power, a timer built for hangboarding, plus a log and workload analytics.', 'Crimpd допомагає скелелазам тренуватися розумніше, а не важче. Тренування розробили відомі скелелази й тренери Том Рендалл та Оллі Торр, і всі вони орієнтовані саме на лазіння: витривалість, силова витривалість, сила й потужність, загальна фізична підготовка й мобільність. Інтерактивні тренування ведуть крок за кроком, а вбудований таймер створено спеціально для вправ на фінгерборді та інтервальних кругів. Після тренування Crimpd автоматично рахує навантаження, а графіки показують прогрес. Безплатна версія включає понад 75 тренувань, журнал і аналітику; Crimpd+ відкриває понад 200 тренувань із прогресіями, власні тренувальні плани та шаблони навичок.', 'Crimpd helps climbers train smarter, not harder. Workouts are designed by world-class climbers and coaches Tom Randall and Ollie Torr and are all climbing-centric: endurance, power endurance, strength and power, conditioning and mobility. Interactive workouts guide you step by step, and the built-in timer is designed specifically for hangboarding and interval circuits. After a session Crimpd automatically calculates the workload, and charts show your progress. The free version includes 75+ workouts, a log book and analytics; Crimpd+ unlocks 200+ workouts with progressions, custom training plans and skill templates.', 'Тренування від Тома Рендалла й Оллі Торра
Витривалість, сила пальців, потужність
Таймер для фінгерборду й інтервалів
Автоматичний розрахунок навантаження
Власні тренувальні плани в Crimpd+', 'Workouts by Tom Randall and Ollie Torr
Endurance, finger strength and power
Timer for hangboarding and intervals
Automatic workload calculation
Custom training plans in Crimpd+', 'Скелелази й боулдеристи, які тренуються самостійно й хочуть структуру та аналітику.', 'Climbers and boulderers who train on their own and want structure and analytics.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
