-- DECADE — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'decade.golf' OR LOWER(`name`) = LOWER('DECADE'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'DECADE', NULL, 'https://decade.golf', NULL, NULL, 'DECADE — система менеджменту поля в гольфі від Скотта Фосетта: стратегія на основі відсотків, коли атакувати флажок, а коли ні, застосунок зі статистикою DECADE5, курси Breaking 90 і книжки ярдажу для 40 000+ полів.', 'DECADE is a golf course management system by Scott Fawcett: percentage-based strategy on when to attack flags, an app with DECADE5 stats, Breaking 90 courses and yardage books for 40,000+ courses.', 'DECADE — перевірена на турі система менеджменту поля, яка допомагає прибрати здогадки й реалізувати свій потенціал на рахунку. Її розробив Скотт Фосетт: система пояснює відсотки — коли варто йти на флажок, а коли ні, — і допомагає ухвалювати розумніші рішення вже за кілька днів. Системою користуються і тур-професіонали, і звичайні гольфісти. Тариф DECADE Breaking 90 включає окремий застосунок для iOS та Android, курс, що вчить стабільно ламати 90, швидке введення статистики DECADE5 і одну персональну книжку ярдажу на місяць із бази понад 40 000 полів. Тариф Foundations дає повний застосунок і курс. Підписки — на пів року або рік, на святкових акціях діють знижки.', 'DECADE is a tour-proven course management system that eliminates guesswork and helps you score up to your potential. Developed by Scott Fawcett, it explains the percentages — when to go for flags and when not to — and helps you make smarter decisions within days. Tour professionals and everyday golfers alike use it. The DECADE Breaking 90 plan includes a dedicated iOS and Android app, a course that teaches you to break 90 consistently, quick DECADE5 stats entry and one custom yardage book per month from a database of 40,000+ courses. The Foundations plan provides the full app and course. Subscriptions are six-monthly or annual, with holiday discounts.', 'Стратегія менеджменту поля
Відсотки для вибору цілі
Курс Breaking 90
Статистика DECADE5
Книжки ярдажу для 40 000+ полів
Застосунок для iOS та Android', 'Course management strategy
Percentages for target choice
Breaking 90 course
