SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'downdogapp.com' OR LOWER(`name`) = LOWER('Down Dog'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Down Dog', NULL, 'https://www.downdogapp.com', NULL, NULL, 'Down Dog генерує нове заняття йогою, пілатесом, HIIT, пренатальною йогою чи медитацією щоразу: ви обираєте тривалість, рівень, фокус, голос інструктора й музику, а застосунок складає унікальну послідовність.', 'Down Dog generates a new yoga, Pilates, HIIT, prenatal yoga or meditation session every time: you choose the length, level, focus, teacher voice and music, and the app builds a unique sequence.', 'Down Dog — застосунок для домашньої практики, який не має фіксованих відеоуроків: кожне заняття генерується в момент запуску. Користувач обирає тривалість, рівень, фокус, голос викладача й музику, а Down Dog складає нову послідовність вправ із новими підказками, тож практика не повторюється. Доступні йога, пілатес, HIIT, пренатальна йога, медитація та інші напрями. Рівні — від повного новачка до просунутого, темп можна сповільнити, а обсяг пояснень регулювати. Заняття можна завантажити для офлайн-доступу та транслювати на телевізор. Застосунок працює на iOS, Android і у вебі; частину підписок команда роздає безплатно студентам, викладачам і тим, хто цього потребує.', 'Down Dog is a home-practice app with no fixed video lessons: every session is generated when you press play. You choose the length, level, focus, teacher voice and music, and Down Dog creates a new sequence with new cues, so your practice never repeats. It covers yoga, Pilates, HIIT, prenatal yoga, meditation and more. Levels range from complete beginner to advanced, you can slow the pace and control how much explanation you hear. Sessions can be downloaded for offline use and cast to a TV. The app runs on iOS, Android and the web, and the team gives free memberships to students, teachers and people in need.', 'Нове заняття, згенероване під ваші налаштування
Йога, пілатес, HIIT, пренатальна йога, медитація
Вибір тривалості, рівня, фокусу, голосу й музики
Офлайн-режим і трансляція на ТБ
iOS, Android і веб', 'A new session generated for your settings
Yoga, Pilates, HIIT, prenatal yoga, meditation
Choose length, level, focus, voice and music
Offline mode and TV casting
iOS, Android and web', 'Ті, хто хоче регулярно займатися йогою чи фітнесом удома без повторення одних і тих самих відео.', 'People who want to practice yoga or fitness at home regularly without repeating the same videos.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
