INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Echelon', NULL, 'https://echelonfit.com', NULL, NULL, 'Echelon — домашні смарт-тренажери (бігові доріжки, велотренажери, еліптичні, гребні, степ-тренажери, реформери для пілатесу) з членством, що відкриває студійні тренування з інструкторами на екрані. Є розстрочка.', 'Echelon makes smart home equipment (treadmills, bikes, ellipticals, rowers, stair climbers, Pilates reformers) with a membership that unlocks studio-quality instructor-led workouts on screen.', 'Echelon продає підключене кардіо- та силове обладнання для дому й членство з тренуваннями студійного рівня. У каталозі — розумні бігові доріжки серії Stride з автоматичним складанням і сенсорними екранами, велотренажери, еліптичні й гребні тренажери, степ-тренажери, реформери для пілатесу, силове обладнання й засоби для відновлення. Членство дає доступ до занять з інструкторами, які можна виконувати на будь-якому з тренажерів. Компанія пропонує безплатну демонстрацію, консультацію експерта, розстрочку без відсотків до 36 місяців і 30-денне повернення без зайвих питань. Є окремий напрям для комерційних клієнтів.', 'Echelon sells connected cardio and strength equipment for the home along with a membership for studio-quality workouts. The catalog includes Stride smart treadmills with auto-fold and touchscreens, bikes, ellipticals and rowers, stair climbers, Pilates reformers, strength gear and recovery tools. The membership gives access to instructor-led classes you can take on any of the machines. The company offers a free demo, expert consultation, 0% APR financing for up to 36 months and a 30-day no-hassle return. There is a separate offering for commercial customers.', 'Розумні бігові доріжки, вело-, гребні й еліптичні тренажери
Реформери для пілатесу й силове обладнання
Членство зі студійними тренуваннями
Безплатна демонстрація та консультація
30-денне повернення', 'Smart treadmills, bikes, rowers and ellipticals
Pilates reformers and strength gear
Membership with studio workouts
Free demo and consultation
30-day returns', 'Люди, які облаштовують домашній зал і хочуть тренування з інструкторами на кардіотренажерах.', 'People setting up a home gym who want instructor-led workouts on cardio machines.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
