-- Equilab — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'equilab.horse' OR LOWER(`name`) = LOWER('Equilab'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Equilab', NULL, 'https://www.equilab.horse', NULL, NULL, 'Equilab — застосунок для вершників: відстежує алюри, дистанцію, швидкість і перепади висоти на кожній їзді, допомагає планувати тренування коня й бачити прогрес, а також ділиться геолокацією з близькими для безпеки.', 'Equilab is an app for equestrians: it tracks gaits, distance, speed and elevation on every ride, helps plan your horse''s training and see progress, and shares your live location with contacts for safety.', 'Equilab допомагає вершникам і коням тренуватися безпечніше, щасливіше та здоровіше. Застосунок записує кожну їзду й показує детальну інформацію: алюри, дистанцію, швидкість і зміни висоти. Можна вести графік тренувань коня, переглядати прогрес з часом і робити кожне заняття ефективнішим. Для безпеки Equilab ділиться вашим місцезнаходженням у реальному часі з обраними контактами, що особливо корисно на прогулянках. Розділ стежок допомагає знаходити маршрути, а спільнота дозволяє спілкуватися з вершниками з усього світу. Базові функції доступні безплатно, а преміум-підписка відкриває всі можливості; на акціях річна підписка дешевшає.', 'Equilab helps riders and horses be safer, happier and healthier. The app records every ride and shows detailed information: gaits, distance, speed and elevation changes. You can manage your horse''s training schedule, see progress over time and make every session count. For safety, Equilab shares your live location with chosen contacts, which is especially useful on trail rides. A trails section helps you find routes, and the community lets you connect with riders worldwide. Basic features are free, and the premium subscription unlocks everything; annual plans are discounted during promotions.', 'Відстеження алюрів, швидкості й дистанції
Графік тренувань коня
Прогрес у часі
Живе відстеження геолокації для безпеки
Маршрути для прогулянок', 'Gait, speed and distance tracking
Horse training schedule
Progress over time
Live location sharing for safety
Trail ride routes', 'Вершники та власники коней, які хочуть стежити за тренуваннями й безпекою.', 'Riders and horse owners who want to track training and stay safe.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
