SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'eversports.com' OR LOWER(`name`) = LOWER('Eversports'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Eversports', NULL, 'https://www.eversports.com', NULL, NULL, 'Eversports — платформа для бронювання йоги, пілатесу, фітнесу, тенісу, танців, боксу та інших занять у вашому місті: абонементи чи разові візити; також ПЗ для власників закладів і корпоративні програми.', 'Eversports is a platform for booking yoga, Pilates, fitness, tennis, dance, boxing and more in your city with memberships or drop-ins, plus software for venue owners and corporate programs.', 'Eversports допомагає знаходити й бронювати спортивні заняття тоді й так, як вам зручно. На платформі можна відкривати нові класи, тренерів і заклади поруч: йогу, реформер-пілатес, пілатес, фітнес, теніс, танці, бокс, барре та інші види. Ви обираєте зручний продукт — членство, разовий візит або щось посередині — і залишаєтеся гнучкими. Спільнота дозволяє знайомитися з іншими любителями спорту, бо займатися разом веселіше. Для HR-відділів є корпоративна програма Eversports Corporate, що дає працівникам доступ до спорту, а власники закладів можуть використовувати Eversports для розвитку бізнесу. Платформа працює в кількох європейських країнах.', 'Eversports helps you find and book sports activities whenever and however suits you. On the platform you can discover new classes, trainers and venues nearby: yoga, reformer Pilates, Pilates, fitness, tennis, dance, boxing, barre and more. You choose the product that fits — a membership, a drop-in or something in between — and stay flexible. The community lets you connect with other sports enthusiasts, because it is more fun together. HR teams can use Eversports Corporate to give employees access to sport, and venue owners can use Eversports to grow their business. The platform operates in several European countries.', 'Бронювання занять у місті
Йога, пілатес, теніс, бокс, танці
Абонементи й разові візити
Спільнота любителів спорту
