SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'joinfightcamp.com' OR LOWER(`name`) = LOWER('FightCamp'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'FightCamp', NULL, 'https://joinfightcamp.com', NULL, NULL, 'FightCamp — тренування з боксу й кікбоксингу вдома з реальними тренерами та трекерами ударів: структуровані програми, метрики в реальному часі й вимірюваний прогрес, а також формат FightCamp для залів.', 'FightCamp offers at-home boxing and kickboxing training with real coaches and punch trackers: structured programs, live metrics and measurable progress, plus a FightCamp format for gyms.', 'FightCamp поєднує традиційну підготовку єдиноборств із сучасними технологіями. Система дозволяє займатися боксом і кікбоксингом удома: заняття ведуть справжні тренери, програми мають чітку структуру, а трекери фіксують удари й показують метрики під час раунду. Завдяки цьому прогрес можна виміряти, а не лише відчути. Філософія FightCamp — дисципліна замість мотивації, завершувати кожен раунд і ставати трохи кращим, ніж учора; тренування розвивають не тільки м''язи, а й витримку та контроль під тиском. Окрім домашнього варіанта, компанія пропонує FightCamp для залів. Почати можна з першого раунду на сайті.', 'FightCamp unites authentic martial arts training with modern technology. The system lets you train boxing and kickboxing at home: classes are led by real coaches, programs are clearly structured, and trackers count punches and show metrics during each round. That way progress can be measured, not just felt. FightCamp''s philosophy is discipline over motivation, finishing every round and being a little better than yesterday; workouts build not only muscle but also grit and control under pressure. Besides the home version, the company offers FightCamp for gyms. You can start your first round on the website.', 'Бокс і кікбоксинг удома
Справжні тренери
Трекінг ударів і метрики в реальному часі
Структуровані програми
Версія для залів', 'Boxing and kickboxing at home
Real coaches
Punch tracking and live metrics
Structured programs
Version for gyms', 'Люди, які хочуть тренуватися боксом і кікбоксингом удома з вимірюваним прогресом.', 'People who want to train boxing and kickboxing at home with measurable progress.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
