INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'FightCamp unites authentic martial arts training with modern technology. The system lets you train boxing and kickboxing at home: classes are led by real coaches, programs are clearly structured, and trackers count punches and show metrics during each round. That way progress can be measured, not just felt. FightCamp''s philosophy is discipline over motivation, finishing every round and being a little better than yesterday; workouts build not only muscle but also grit and control under pressure. Besides the home version, the company offers FightCamp for gyms. You can start your first round on the website.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'main_features', 'en', 'Boxing and kickboxing at home
Real coaches
Punch tracking and live metrics
Structured programs
Version for gyms', 'manual' FROM DUAL WHERE @new = 1;
