-- Fiit — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'fiit.tv' OR LOWER(`name`) = LOWER('Fiit'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Fiit', NULL, 'https://fiit.tv', NULL, NULL, 'Fiit — фітнес-застосунок із тисячами занять у 7 дисциплінах (сила, кардіо, відновлення, велотренажер, бігова доріжка, гребля, ейрбайк) і 40+ планами тренувань; трекінг повторень і калорій, команди та челенджі.', 'Fiit is a fitness app with thousands of classes across 7 disciplines (strength, cardio, recovery, bike, tread, row, airbike) and 40+ training plans, with rep and calorie tracking, teams and challenges.', 'Fiit — застосунок для «гібридного» фітнесу вдома, у залі та в дорозі. Бібліотека містить тисячі занять у семи дисциплінах і двадцяти форматах: силові з власною вагою, гантелями й гирями, кардіо, HIIT, йога, пілатес, барре, мобільність, а також тренування на велотренажері, біговій доріжці, гребному тренажері й ейрбайку. Нові класи з''являються щотижня. Понад 40 тренувальних планів розраховані на будь-який рівень і мету — від 10-хвилинних розминок до 12-тижневих програм. Застосунок рахує повторення й калорії, дозволяє створювати команди, приєднуватися до челенджів і тренуватися з друзями чи колегами. Безлімітна підписка тепер включає журнали Men''s Health і Women''s Health.', 'Fiit is an app for hybrid fitness at home, in the gym and on the go. Its library holds thousands of classes across seven disciplines and twenty formats: bodyweight, dumbbell and kettlebell strength, cardio, HIIT, yoga, Pilates, barre, mobility, plus bike, treadmill, rower and airbike sessions. New classes arrive every week. More than 40 training plans cover every level and goal — from 10-minute movers to 12-week programs. The app tracks reps and calories, lets you build teams, join challenges and train with friends or colleagues. The unlimited membership now includes Men''s Health and Women''s Health magazines.', 'Тисячі занять у 7 дисциплінах
40+ тренувальних планів
Тренування на кардіотренажерах
Трекінг повторень і калорій
Команди та челенджі
Нові класи щотижня', 'Thousands of classes in 7 disciplines
40+ training plans
Cardio machine workouts
Rep and calorie tracking
Teams and challenges
New classes every week', 'Люди, які тренуються вдома чи в залі й хочуть різноманітні заняття з тренерами та структурні плани.', 'People who train at home or in the gym and want varied trainer-led classes and structured plans.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
