-- Fitify — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'fitifyapps.com' OR LOWER(`name`) = LOWER('Fitify'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Fitify', NULL, 'https://fitifyapps.com', NULL, NULL, 'Fitify — набір фітнес-застосунків для Android та iOS, а також універсальний Fitify Workouts & Plans: тренування з гирею, TRX, фітболом, BOSU, еспандером, роликом або з власною вагою з голосовим тренером і HD-відео.', 'Fitify is a set of fitness apps for Android and iOS, plus the all-in-one Fitify Workouts & Plans: kettlebell, TRX, Swiss ball, BOSU, resistance band, foam roller or bodyweight workouts with a voice coach and HD video.', 'Fitify Apps — розробник фітнес-застосунків для тренувань будь-де та будь-коли. Окремі застосунки присвячені конкретному інвентарю: гирі, TRX, фітболу, BOSU, гумовим еспандерам, масажному ролику та медболу, а також вправам із власною вагою для пресу, ніг, верхньої частини тіла, кардіо, HIIT, розминки й розтяжки. Новий універсальний застосунок Fitify Workouts & Plans збирає все в одному місці. Користувач обирає частину тіла й тривалість, а далі виконує вправи за HD-відео з голосовими підказками тренера. Вбудований календар зберігає історію тренувань і нагадує про заняття, а конструктор дозволяє зібрати власне тренування з вибором вправ, тривалості та пауз.', 'Fitify Apps builds fitness apps for working out anywhere, anytime. Separate apps focus on specific equipment: kettlebell, TRX, Swiss ball, BOSU, resistance bands, foam roller and medicine ball, plus bodyweight exercises for abs, legs, upper body, cardio, HIIT, warm-up and stretching. The new all-in-one Fitify Workouts & Plans app brings everything together. You choose a body part and duration, then follow HD video exercises with voice coach instructions. A built-in calendar keeps your workout history and sends reminders, and a workout builder lets you create your own session with chosen exercises, duration and rest intervals.', 'Тренування з гирею, TRX, фітболом, роликом та іншим інвентарем
Вправи з власною вагою за частинами тіла
HD-відео з голосовим тренером
Календар і нагадування
Конструктор власних тренувань', 'Kettlebell, TRX, Swiss ball, roller and other equipment workouts
Bodyweight exercises by body part
HD video with a voice coach
Calendar and reminders
Custom workout builder', 'Люди, які тренуються вдома чи в залі з простим інвентарем або без нього й хочуть голосового тренера.', 'People who train at home or in the gym with simple equipment or none and want a voice coach.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
