SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'fitnessblender.com' OR LOWER(`name`) = LOWER('Fitness Blender'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Fitness Blender', NULL, 'https://www.fitnessblender.com', NULL, NULL, 'Fitness Blender — сотні професійних повноформатних відеотренувань удома, прогресивні програми, плани харчування, корисні рецепти, медитації та експертні статті; можна безплатно, денним доступом або за підпискою.', 'Fitness Blender offers hundreds of professional full-length at-home workout videos, progressive programs, meal plans, healthy recipes, meditations and expert articles, for free, with a day pass or by subscription.', 'Fitness Blender пропонує цілісний підхід до самопочуття тіла й розуму. На сайті сотні повноформатних відеотренувань для дому — силові, кардіо, HIIT, пілатес, розтяжка та інші, — а також власні тренування, які можна зібрати й відстежувати. Прогресивні програми ведуть до мети тижнями, наприклад 10-денні челенджі серії Trainer Series з поєднанням сили, потужності, кардіо й HIIT. Окремо є плани харчування, корисні рецепти, відео для відновлення й медитації та статті від експертів. Безплатна реєстрація дає змогу створювати й відстежувати тренування та отримувати підтримку спільноти; програми доступні з денним пропуском або за підпискою.', 'Fitness Blender takes a whole body and mind approach to feeling great. The site has hundreds of full-length at-home workout videos — strength, cardio, HIIT, Pilates, stretching and more — plus custom workouts you can build and track. Progressive programs guide you toward a goal over weeks, such as 10-day Trainer Series challenges mixing strength, power, cardio and HIIT. There are also meal plans, healthy recipes, recovery and meditation videos, and expert articles. Free sign-up lets you build and track workouts and get community support; programs are available with a day pass or by subscription.', 'Сотні відеотренувань для дому
Прогресивні програми й челенджі
Конструктор власних тренувань
Плани харчування й рецепти
Медитації та статті експертів
Безплатна реєстрація', 'Hundreds of at-home workout videos
Progressive programs and challenges
Custom workout builder
Meal plans and recipes
Meditations and expert articles
Free sign-up', 'Люди, які тренуються вдома й хочуть поєднати тренування з харчуванням і відновленням.', 'People who work out at home and want to combine training with nutrition and recovery.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
