SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'fitonapp.com' OR LOWER(`name`) = LOWER('FitOn'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'FitOn', NULL, 'https://fitonapp.com', NULL, NULL, 'FitOn — цифрова платформа фітнесу й добробуту з безплатними заняттями на вимогу: кардіо, йога, силові, пілатес, тонізування з тренерами, зокрема відомими, персональні плани, медитації та харчування. Є версія для компаній.', 'FitOn is a digital fitness and wellness platform with free on-demand classes: cardio, yoga, strength, Pilates and toning with trainers, including celebrities, plus personalized plans, meditation and nutrition.', 'FitOn — платформа, що поєднує тренування, медитацію й харчування. Зареєструватися можна безплатно й отримати доступ до занять на вимогу: кардіо, йога, силові, пілатес, тонізування та інші формати. Більшість тренувань не потребує обладнання, а займатися можна на будь-якому екрані. Серед тренерів є знаменитості, а соціальні функції дозволяють тренуватися разом із друзями. Персональні плани допомагають рухатися до мети, а медитації та розділ про харчування доповнюють фітнес. На сайті є гіди про здорове харчування, сон, зниження стресу й гідратацію. Окремо FitOn пропонує рішення для роботодавців, страхових планів, брокерів і фітнес-закладів.', 'FitOn is a platform that combines workouts, meditation and nutrition. You can sign up for free and get access to on-demand classes: cardio, yoga, strength, Pilates, toning and more. Most workouts need no equipment, and you can train on any screen. Trainers include celebrities, and social features let you work out with friends. Personalized plans help you move toward your goal, while meditations and a nutrition section complement the fitness side. The site has guides on healthy eating, sleep, stress reduction and hydration. FitOn also offers solutions for employers, health plans, brokers and fitness facilities.', 'Безплатні тренування на вимогу
Кардіо, йога, силові, пілатес
Персональні плани
Медитації та харчування
Соціальні функції
Рішення для роботодавців і страхових планів', 'Free on-demand workouts
Cardio, yoga, strength, Pilates
Personalized plans
Meditation and nutrition
Social features
Solutions for employers and health plans', 'Люди, які хочуть займатися вдома без обладнання, а також компанії та страхові плани.', 'People who want to work out at home without equipment, as well as employers and health plans.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
