SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'fuelin.com' OR LOWER(`name`) = LOWER('Fuelin'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Fuelin', NULL, 'https://www.fuelin.com', NULL, NULL, 'Fuelin — застосунок адаптивного спортивного харчування: щоденний план харчування й підживлення під ваші тренування й старти, AI-облік їжі, розумні рекомендації страв, 100+ рецептів і коучинг для бігу, вело, залу.', 'Fuelin is an adaptive sports nutrition app: a daily nutrition and fueling plan for your training and races, AI food logging, smart meal recommendations, 100+ recipes and coaching for running, cycling and the gym.', 'Fuelin знімає здогадки з питання, як і скільки їсти під час тренувань. Застосунок складає персональний, адаптивний план харчування й підживлення на кожен день з урахуванням вашого тренувального тижня та стартів — для бігу, велоспорту, плавання, тенісу, футболу, залу чи досягнення бажаної ваги. AI-облік їжі спрощує записи, розумні рекомендації підказують страви, а понад 100 рецептів прив''язані до ваших тренувань. Є приватна спільнота атлетів і можливість працювати з тренерами-нутриціологами. У США передплатники отримують бонуси від партнерів на кшталт Maurten і Momentous. Підписку можна оформити на рік або на місяць і скасувати будь-коли.', 'Fuelin takes the guesswork out of how and how much to eat around training. The app builds a personalized, adaptive daily nutrition and fueling plan based on your training week and races — for running, cycling, swimming, tennis, football, the gym or reaching your ideal weight. AI food logging makes tracking easy, smart recommendations suggest meals, and 100+ recipes are timed to your training. There is a private athlete community and the option to work with nutrition coaches. In the US, subscribers get partner benefits from brands like Maurten and Momentous. Plans are yearly or monthly and can be canceled anytime.', 'Адаптивний план харчування під тренування
Підживлення на тренуваннях і стартах
AI-облік їжі
Розумні рекомендації страв
100+ рецептів
Спільнота атлетів', 'Adaptive nutrition plan for training
Fueling for workouts and races
AI food logging
Smart meal recommendations
100+ recipes
Athlete community', 'Бігуни, велосипедисти, тріатлоністи та інші атлети-аматори, які хочуть правильно харчуватися під навантаження.', 'Runners, cyclists, triathletes and other amateur athletes who want to fuel their training properly.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
