SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'fulgaz.com' OR LOWER(`name`) = LOWER('FulGaz'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'FulGaz', NULL, 'https://fulgaz.com', NULL, NULL, 'FulGaz — застосунок для велотренувань у приміщенні на відео реальних доріг: 2000+ маршрутів із 60+ країн, точне керування станком і симуляція рельєфу, тренувальні плани та події для велосипедистів і тріатлоністів.', 'FulGaz is an indoor cycling app built on real road videos: 2,000+ rides from 60+ countries, precise trainer control and terrain simulation, training plans and events for cyclists and triathletes.', 'FulGaz прагне зробити тренування в приміщенні максимально реалістичними. Замість віртуальної графіки — понад 2000 відео реальних маршрутів із понад 60 країн, знятих звичайними велосипедистами. Завдяки точному керуванню станком і симуляції рельєфу дорога відчувається так само, як виглядає. Тренуватися можна за власною тренувальною платформою через інтеграції або за планами FulGaz, а також брати участь у реальних подіях разом з іншими. Є окремі сценарії для велосипедистів і тріатлоністів та добірки маршрутів. Повний доступ безплатний 14 днів без картки, далі — помісячна підписка з паузою або річна з безплатним акаунтом для члена родини.', 'FulGaz aims to make indoor training as realistic as possible. Instead of virtual graphics there are 2,000+ real-world ride videos from 60+ countries, filmed by real cyclists. Precise trainer control and terrain simulation make the road feel as real as it looks. You can train with your own training platform via integrations or with FulGaz plans, and join real events with others. There are dedicated flows for cyclists and triathletes and curated ride collections. Full access is free for 14 days with no card, then a monthly plan you can pause or an annual plan that includes a free account for a family member.', '2000+ відео реальних маршрутів із 60+ країн
Точне керування станком і симуляція рельєфу
