SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'gentlerstories.com/gentlerstreak' OR LOWER(`name`) = LOWER('Gentler Streak'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Gentler Streak', NULL, 'https://gentlerstories.com/gentlerstreak', NULL, NULL, 'Gentler Streak — трекер тренувань для iPhone та Apple Watch, що ставить добробут на перше місце: підлаштовує щоденні цілі під те, як почувається тіло, і рахує серії так, що відпочинок їх не обриває. Без тиску.', 'Gentler Streak is a workout tracker for iPhone and Apple Watch that puts well-being first: it adapts daily goals to how your body feels and counts streaks so that rest never breaks them.', 'Gentler Streak — застосунок для відстеження активності, який допомагає вибудувати фітнес-рутину надовго. Він зустрічає вас там, де ви є сьогодні: щоденні цілі змінюються відповідно до того, як почувається ваше тіло, а прості практичні поради підтримують мотивацію. Застосунок не карає за пропуски й не тисне почуттям провини — серії винагороджують регулярність, а не ідеальність, тож перерва на відпочинок не означає, що все треба починати спочатку. Головний фокус — особистий прогрес і рух на довгі роки, а не загальні цілі. Gentler Streak отримав нагороду Apple Design Awards і звання застосунку року для Apple Watch.', 'Gentler Streak is an activity tracking app that helps you build a fitness routine that lasts. It meets you where you are each day: daily goals adapt to how your body actually feels, and simple, practical guidance keeps you motivated. The app does not punish missed days or rely on guilt — streaks reward consistency over perfection, so taking a break never means starting over. The focus is on personal progress and moving for years, not generic goals. Gentler Streak won an Apple Design Award and was named Apple Watch App of the Year.', 'Щоденні цілі за самопочуттям
Серії, які не обриває відпочинок
Практичні поради без тиску
Фокус на регулярності й особистому прогресі
Підтримка Apple Watch', 'Daily goals based on how you feel
Streaks that rest doesn''t break
Practical guidance without pressure
Focus on consistency and personal progress
Apple Watch support', 'Люди, які хочуть регулярно рухатися без перетренованості й почуття провини.', 'People who want to stay active regularly without overtraining or guilt.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
