SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'golfgamebook.com' OR LOWER(`name`) = LOWER('Golf GameBook'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Golf GameBook', NULL, 'https://www.golfgamebook.com', NULL, NULL, 'Golf GameBook — застосунок-скоркарта для гольфу з понад 20 форматами гри, живими таблицями результатів, GPS-далекоміром, статистикою, турнірами, іграми у стилі Райдер-кубка, гандикапом і менеджером подій для клубів.', 'Golf GameBook is a golf scorecard app with 20+ game formats, live leaderboards, a GPS rangefinder, stats, tournaments, Ryder Cup-style games, handicap and an event manager for clubs.', 'Golf GameBook робить гольф цікавішим на полі й поза ним. Застосунок веде рахунок у понад 20 ігрових форматах, а друзі можуть стежити за кожною грою через живі таблиці результатів. Є GPS-далекомір, статистика, створення турнірів, ігри «червоні проти синіх» у стилі Райдер-кубка, друзі, челенджі та власний гандикап GGB. Для гольф-клубів доступні менеджер турнірів і керування подіями, а для гравців — пропозиції клубів і магазин. Базова версія безплатна, а Gold-членство відкриває далекомір, усі формати, групи й турніри; річна підписка коштує 59,99 EUR з 14-денним пробним періодом. Застосунок доступний кількома мовами.', 'Golf GameBook makes golf more fun on and off the course. The app keeps score in 20+ game formats, and friends can follow every game via live leaderboards. There is a GPS rangefinder, statistics, tournament creation, Reds vs Blues Ryder Cup-style games, friends, challenges and its own GGB Handicap. Golf clubs get a tournament manager and event management, and golfers get club deals and a shop. The basic version is free, and Gold membership unlocks the rangefinder, all formats, groups and tournaments; the annual plan costs 59.99 EUR with a 14-day free trial. The app is available in several languages.', 'Скоркарта на 20+ форматів
Живі таблиці результатів
