SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'golfpadgps.com' OR LOWER(`name`) = LOWER('Golf Pad'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Golf Pad', NULL, 'https://golfpadgps.com', NULL, NULL, 'Golf Pad — безплатний GPS-далекомір для гольфу з відстеженням ударів і ключок, статистикою, картами та підрахунком очок; преміум-версія, гандикап USGA, автоматичні сенсори Golf Pad TAGS і керування турнірами.', 'Golf Pad is a free golf GPS rangefinder with shot and club tracking, statistics, maps and scorekeeping; premium features, USGA handicap, Golf Pad TAGS automatic sensors and tournament management.', 'Golf Pad — застосунок-далекомір для гольфістів, у якому безплатно доступні відстеження ударів і ключок, статистика, точні відстані, карти полів і підрахунок очок. Він допомагає зрозуміти свою гру: як далеко ви б''єте кожною ключкою, де втрачаєте удари і як змінюються результати. Раундами можна ділитися з друзями. Преміум-версія додає розширені функції та переваги, а через застосунок можна вести офіційний USGA Handicap Index. Для автоматичного відстеження ударів компанія продає сенсори Golf Pad TAGS, які кріпляться на ключки, і кнопку Golf Pad Click для керування однією кнопкою. Окремий сервіс Golf Pad Events допомагає організовувати турніри й події.', 'Golf Pad is a rangefinder app for golfers with free shot and club tracking, statistics, accurate distances, course maps and scorekeeping. It helps you understand your game: how far you hit each club, where you lose strokes and how results change. Rounds can be shared with friends. The premium version adds extra features and perks, and the app can manage an official USGA Handicap Index. For automatic shot tracking the company sells Golf Pad TAGS sensors that attach to clubs, plus the Golf Pad Click one-button control. A separate Golf Pad Events service helps run tournaments and events.', 'Безплатний GPS-далекомір
Відстеження ударів і ключок
Статистика й підрахунок очок
Сенсори Golf Pad TAGS для автотрекінгу
