SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'golflogix.com' OR LOWER(`name`) = LOWER('GolfLogix'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'GolfLogix', NULL, 'https://www.golflogix.com', NULL, NULL, 'GolfLogix — GPS-застосунок для гольфу з 3D-видами лунок і VR-прольотами, детальними картами нахилів грінів, точними відстанями на 40 000+ полях, статистикою, гандикапом і синхронізацією з Apple Watch.', 'GolfLogix is a golf GPS app with 3D hole views and VR flyovers, detailed green slope maps, accurate distances on 40,000+ courses, stats, handicap and Apple Watch sync.', 'GolfLogix допомагає ухвалювати розумніші рішення на кожному ударі. Застосунок показує точні GPS-відстані на понад 40 000 полях, а 3D-види дозволяють «пройти» лунку ще до того, як ви вийшли на ті: побачити цілі, кожну перешкоду й прийти зі справжнім планом гри. Прольоти в реальному часі з вашими реальними дистанціями ключок допомагають візуалізувати удар. Детальні карти грінів показують нахили для читання паттів. Також застосунок веде рахунок, статистику й гандикап і синхронізується з Apple Watch та іншими носимими пристроями. Базова версія доступна безплатно, а преміум відкриває повні функції; також продаються лазерний далекомір і книжки грінів.', 'GolfLogix helps you make smarter decisions on every shot. The app shows accurate GPS distances on 40,000+ courses, and 3D views let you walk the hole before you tee off: see targets, spot every hazard and arrive with a real game plan. Real-time flyovers using your actual club distances help you visualize the shot. Detailed green maps show slopes for reading putts. The app also tracks scores, stats and handicap and syncs with Apple Watch and other wearables. The basic version is free and premium unlocks full features; a laser rangefinder and green books are also sold.', 'Точні GPS-відстані на 40 000+ полях
