SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'golfshot.com' OR LOWER(`name`) = LOWER('Golfshot'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Golfshot', NULL, 'https://golfshot.com', NULL, NULL, 'Golfshot — застосунок для гольфу з GPS-відстанями, підрахунком очок і статистикою, автоматичним відстеженням ударів через Apple Watch, аналізом свінгу Swing ID, AR-режимом Golfscape і авто-Strokes Gained.', 'Golfshot is a golf app with GPS distances, scoring and statistics, automatic shot tracking via Apple Watch, Swing ID swing analysis, the Golfscape AR mode and auto Strokes Gained.', 'Golfshot — застосунок для гольфістів, що поєднує навігацію полем, рахунок і аналітику. Він показує GPS-відстані на полях по всьому світу та карти грінів, веде рахунок і статистику, розраховує Handicap Index. Автоматичне відстеження ударів працює лише з Apple Watch або на Android, а після раунду можна переглянути проліт над полем із вашими ударами. Функція Swing ID аналізує свінг, зокрема на тренувальному рейнджі, а автоматичний Strokes Gained показує, де ви виграєте й втрачаєте удари. Також є AR-режим Golfscape, голосовий асистент, навчальні програми Golfplan, бронювання ті-таймів і керування турнірами. Розширені функції доступні в Pro.', 'Golfshot is a golf app that combines course navigation, scoring and analytics. It shows GPS distances on courses worldwide and green maps, keeps scores and stats, and calculates your Handicap Index. Automatic shot tracking works with just an Apple Watch or on Android, and after the round you can review a flyover with your shots. Swing ID analyzes your swing, including at the range, and auto Strokes Gained shows where you gain and lose shots. There is also the Golfscape AR mode, a voice assistant, Golfplan instruction, tee time booking and tournament management. Advanced features come with Pro.', 'GPS-відстані та карти грінів
Рахунок, статистика й гандикап
Автотрекінг ударів через годинник
Аналіз свінгу Swing ID
Авто-Strokes Gained
AR-режим і голосовий асистент', 'GPS distances and green maps
Scoring, stats and handicap
Automatic shot tracking with a watch
Swing ID swing analysis
Auto Strokes Gained
AR mode and voice assistant', 'Гольфісти, які хочуть детальну статистику та аналіз гри без додаткових сенсорів.', 'Golfers who want detailed stats and game analysis without extra sensors.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
