SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'gowod.app' OR LOWER(`name`) = LOWER('GOWOD'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'GOWOD', NULL, 'https://www.gowod.app', NULL, NULL, 'GOWOD — застосунок мобільності й розтяжки для будь-якого спорту: безплатна оцінка мобільності, персональні протоколи за вашим результатом і видами спорту (CrossFit, HYROX, біг, боулдеринг), 300+ відео.', 'GOWOD is a mobility and stretching app for every sport: a free mobility assessment and personalized protocols based on your score and sports (CrossFit, HYROX, running, bouldering), plus 300+ videos.', 'GOWOD виходить з того, що якість руху визначає результат, а мобільність часто недооцінюють. Застосунок пропонує безплатно оцінити мобільність, щоб побачити сильні й слабкі сторони, а потім складає персональні протоколи розтяжки з урахуванням вашого результату та улюблених видів спорту — CrossFit, HYROX, бігу, боулдерингу та інших. Безплатна версія включає оцінку, понад 300 відео з вправами, персональні, класичні та базові комплекси, активаційні й відновлювальні протоколи, а також відстеження прогресу. Преміум для відданих атлетів відкриває додаткові можливості й має 7-денний безплатний пробний період. Застосунок доступний кількома мовами.', 'GOWOD starts from the idea that movement quality defines performance, yet mobility is often overlooked. The app offers a free mobility assessment to reveal strengths and weaknesses, then builds personalized stretching protocols based on your score and favorite sports — CrossFit, HYROX, running, bouldering and more. The free version includes the assessment, 300+ exercise videos, personalized, classic and essential flows, activation and recovery protocols, and progress tracking. Premium for committed athletes unlocks more features and has a 7-day free trial. The app is available in several languages.', 'Безплатна оцінка мобільності
Персональні протоколи під ваш вид спорту
300+ відео вправ
Активаційні й відновлювальні протоколи
Відстеження прогресу', 'Free mobility assessment
Personalized protocols for your sport
300+ exercise videos
Activation and recovery protocols
Progress tracking', 'Атлети CrossFit, HYROX, бігуни, скелелази та всі, хто хоче рухатися вільніше й знизити ризик травм.', 'CrossFit and HYROX athletes, runners, climbers and anyone who wants to move more freely and reduce injury risk.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
