-- Gymaholic — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'gymaholic.co' OR LOWER(`name`) = LOWER('Gymaholic'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Gymaholic', NULL, 'https://www.gymaholic.co', NULL, NULL, 'Gymaholic — фітнес-застосунок із AI-планами тренувань і харчування, що підлаштовуються під графік: облік калорій за фото, тренування вдома чи в залі, плани для чоловіків і жінок, калістеніка, HIIT, біг і статті.', 'Gymaholic is a fitness app with AI-built workout and nutrition plans that adapt to your schedule: photo calorie tracking, workouts at home or in the gym, plans for men and women, calisthenics, HIIT, running and articles.', 'Gymaholic допомагає тренуватися регулярно завдяки планам тренувань і харчування, які створює AI та підлаштовує під ваш розклад. Калорії можна рахувати за фото страви, а керовані тренування виконувати вдома чи в залі. На сайті доступна велика бібліотека готових планів для чоловіків і жінок: калістеніка, силові й на масу, схуднення, HIIT, гібридні тренування, з гантелями, гирею чи еспандером, біг і програми для людей старшого віку — від новачків до просунутих. Плани мають чітку тривалість, наприклад чотиритижневий план на силу й м''язи чи 21-денна гібридна програма. Також є статті про здоров''я, фітнес і спосіб життя та мотиваційні матеріали.', 'Gymaholic helps you train consistently with AI-built workout and nutrition plans that adapt to your schedule. You can track calories by snapping a photo of your meal and follow guided workouts at home or in the gym. The site offers a large library of ready-made plans for men and women: calisthenics, strength and muscle, fat loss, HIIT, hybrid training, dumbbell, kettlebell or resistance band plans, running and programs for seniors — from beginner to advanced. Plans have clear durations, such as a 4-week strength and muscle plan or a 21-day hybrid program. There are also health, fitness and lifestyle articles and motivational content.', 'AI-плани тренувань і харчування
Облік калорій за фото
Тренування вдома й у залі
Бібліотека готових планів
Плани для чоловіків і жінок
Статті й мотивація', 'AI workout and nutrition plans
Photo calorie tracking
Home and gym workouts
Library of ready-made plans
Plans for men and women
Articles and motivation', 'Люди, які хочуть тренуватися й харчуватися за планом і бути послідовними.', 'People who want to train and eat to a plan and stay consistent.', 'mobile,web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
