-- GymStreak — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'gymstreak.com' OR LOWER(`name`) = LOWER('GymStreak'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'GymStreak', NULL, 'https://www.gymstreak.com', NULL, NULL, 'GymStreak — AI-персональний тренер для iPhone, Apple Watch та Android: після короткої розмови про мету, графік і обладнання складає план на тиждень, записує кожен підхід і рахує серію тижнів без пропусків.', 'GymStreak is an AI personal trainer for iPhone, Apple Watch and Android: after a short chat about your goal, schedule and equipment it builds a weekly plan, logs every set and counts a streak of weeks.', 'GymStreak відрізняється від звичайних журналів тренувань тим, що не залишає вас із порожнім списком. Після короткого діалогу про мету, кількість днів для тренувань, доступний час і обладнання AI складає план на тиждень, який легко виконувати. Під час тренування застосунок записує кожен підхід, а прогрес зберігається тиждень за тижнем. Мотивує тижнева серія: вона рахує тижні, а не дні — якщо ви виконали задану кількість тренувань, серія зростає, а дні відпочинку її не обривають. На сайті є довідник вправ, корисні інструменти, розділ про харчування та блог. Завантаження безплатне, розширені можливості — у преміум-підписці в застосунку.', 'GymStreak differs from typical workout logs in that it doesn''t leave you with an empty list. After a short chat about your goal, the days you can train, how long you have and your equipment, the AI builds a weekly plan you can follow. During a workout the app logs every set, and progress is stored week after week. A weekly streak keeps you motivated: it counts weeks, not days — hit the workout goal you set and the streak grows, while rest days never break it. The site also has an exercise directory, tools, a nutrition section and a blog. The app is free to download, with a premium subscription in the app.', 'План на тиждень за метою й обладнанням
Запис кожного підходу
Тижнева серія, яку не обривають дні відпочинку
Підтримка Apple Watch
Довідник вправ і інструменти', 'Weekly plan based on goal and equipment
Every set logged
Weekly streak that rest days don''t break
Apple Watch support
Exercise directory and tools', 'Ті, хто ходить у зал і хоче готовий план та мотивацію не пропускати тренування.', 'Gym-goers who want a ready-made plan and motivation not to skip workouts.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
