SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hole19golf.com' OR LOWER(`name`) = LOWER('Hole19'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Hole19', NULL, 'https://www.hole19golf.com', NULL, NULL, 'Hole19 — застосунок для гольфу: GPS-далекомір і точна навігація полем, підрахунок очок, аналітика гри, калькулятор гандикапу, понад 42 000 полів і окремий застосунок CORE Golf для тренувань на драйвінг-рейнджі.', 'Hole19 is a golf app: a GPS rangefinder and precise course navigation, scorekeeping, game insights, a handicap calculator, 42,000+ courses and a separate CORE Golf app for driving range practice.', 'Hole19 допомагає гольфістам грати краще. Основний застосунок відстежує рахунок, показує GPS-відстані на полі з високою точністю й дає аналітику продуктивності, щоб бачити сильні й слабкі сторони гри. Каталог містить понад 42 000 полів, тож перед поїздкою чи новим полем можна заздалегідь підготуватися. Для тренувань є окремий застосунок CORE Golf: він дає завдання на драйвінг-рейнджі, щоб кожен м''яч мав мету й допомагав готуватися до гри. На сайті також доступні калькулятор гандикапу та розділ The 19th Hole з новинами, оглядами спорядження й порадами для гольфістів. Застосунки підходять гравцям різного рівня — від новачків до тих, хто бореться за кожен удар.', 'Hole19 helps golfers play their best. The main app tracks scores, shows precise GPS distances on the course and gives performance insights so you can see strengths and weaknesses. The catalog includes more than 42,000 courses, so you can prepare before a golf trip or a new course. For practice there is the separate CORE Golf app: it gives you tasks at the driving range so every ball has a purpose and prepares you for the course. The site also offers a handicap calculator and The 19th Hole hub with news, equipment reviews and tips for golfers. The apps suit golfers of all levels, from beginners to those fighting for every stroke.', 'GPS-далекомір на полі
Підрахунок очок і статистика
Понад 42 000 полів
Застосунок CORE Golf для рейнджу
Калькулятор гандикапу', 'GPS rangefinder on the course
Scorekeeping and stats
42,000+ courses
CORE Golf app for the range
Handicap calculator', 'Гольфісти-аматори, які хочуть відстежувати гру та тренуватися на рейнджі з метою.', 'Amateur golfers who want to track their game and practice at the range with purpose.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
