SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'holodia.com' OR LOWER(`name`) = LOWER('HOLOFIT'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'HOLOFIT', NULL, 'https://www.holodia.com', NULL, NULL, 'HOLOFIT від Holodia — VR-фітнес для гребного тренажера, велотренажера чи еліптичного: понад 15 віртуальних світів, 6 режимів тренувань, змагання й спільнота, а також вправи без обладнання; сумісний із Meta Quest.', 'HOLOFIT by Holodia is VR fitness for your rower, bike or elliptical: 15+ virtual worlds, 6 workout modes, competition and community, plus no-equipment exercises; compatible with Meta Quest.', 'HOLOFIT робить тренування на кардіотренажерах цікавими завдяки віртуальній реальності. Застосунок працює з будь-яким гребним тренажером, а також із будь-яким велотренажером чи еліптичним тренажером за умови додавання датчика каденсу. Надягнувши гарнітуру Meta Quest, ви веслуєте, їдете чи біжите у віртуальних світах, змагаєтеся з іншими учасниками й спілкуєтеся зі спільнотою. Понад 15 світів і 6 режимів тренувань, а також регулярні оновлення контенту допомагають не нудьгувати. Є й вправи без обладнання — віртуальні лижі та бокс з власною вагою. HOLOFIT пропонує рішення і для домашніх користувачів, і для клубів; доступний безплатний пробний період.', 'HOLOFIT makes cardio machine workouts fun with virtual reality. It works with any rowing machine and with any bike or elliptical once a cadence sensor is added. With a Meta Quest headset you row, ride or run through virtual worlds, compete with others and connect with the community. Over 15 worlds, 6 workout modes and regular content updates keep things from getting boring. There are also no-equipment exercises — virtual skiing and bodyweight boxing. HOLOFIT offers solutions for home users and clubs, and a free trial is available.', 'VR-тренування на гребному, вело- й еліптичному тренажерах
15+ віртуальних світів
6 режимів тренувань
Змагання й спільнота
Вправи без обладнання
Сумісність із Meta Quest', 'VR workouts on rowers, bikes and ellipticals
15+ virtual worlds
6 workout modes
Competition and community
No-equipment exercises
Meta Quest compatible', 'Власники кардіотренажерів і VR-гарнітур, а також фітнес-клуби.', 'Owners of cardio machines and VR headsets, as well as fitness clubs.', 'desktop', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
