INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'HWPO', NULL, 'https://www.hwpotraining.com', NULL, NULL, 'HWPO — тренувальний застосунок від п''ятиразового чемпіона CrossFit Games Мета Фрейзера: структуровані програми з тренерами, чіткий план на кожен день, поступове зростання сили; 12 програм безплатно 14 днів.', 'HWPO is a training app from five-time CrossFit Games champion Mat Fraser: structured coach-led programs, a clear plan every day and progressive strength gains; 12 programs free for 14 days.', 'HWPO (Hard Work Pays Off) — система тренувань, яку створив п''ятиразовий чемпіон CrossFit Games Мет Фрейзер. Застосунок дає структуровані тренування з тренерами та чіткий план на кожен день, тож не доводиться гадати, що робити. Головні принципи — регулярність і наполеглива праця: план легко виконувати тиждень за тижнем, а прогресивне навантаження під керівництвом тренерів допомагає ставати сильнішим у залі й у повсякденному житті. Програми допомагають покращити загальну форму й самопочуття. Доступ All Access відкриває 12 програм, які можна безплатно спробувати протягом 14 днів і скасувати будь-коли. Також є програми для залів-афіліатів і мерч.', 'HWPO (Hard Work Pays Off) is a training system created by five-time CrossFit Games champion Mat Fraser. The app provides structured, coach-led training and a clear plan for every day, so there is no guesswork. The core principles are consistency and hard work: the plan is easy to stick to week after week, and progressive coach-led training helps you get stronger in the gym and in everyday life. Programs also improve overall fitness and well-being. All Access unlocks 12 programs that you can try free for 14 days and cancel anytime. There are also affiliate gym programs and merch.', 'Програми від Мета Фрейзера
