-- Hydrow — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hydrow.com' OR LOWER(`name`) = LOWER('Hydrow'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Hydrow', NULL, 'https://hydrow.com', NULL, NULL, 'Hydrow — гребні тренажери Arc і Wave та силова платформа LYQUID з ізокінетичним опором: занурювальні тренування веслуванням на все тіло й силові заняття за підпискою на контент Hydrow для дому з сезонними знижками.', 'Hydrow makes the Arc and Wave rowing machines and the LYQUID strength platform with isokinetic resistance: immersive full-body rowing workouts and strength sessions with a Hydrow content membership.', 'Hydrow розвиває підхід «плавна сила»: на думку компанії, справжня сила — це потужність, а не об''єм. Лінійка складається з трьох моделей. Arc — флагманський гребний тренажер із максимальним зануренням, що навантажує все тіло. Wave — компактніший гребний тренажер із невеликою площею та п''ятьма кольорами. LYQUID — окрема силова платформа з ізокінетичним опором, що підлаштовується під зусилля в кожен момент руху. Веслування розвиває силу й витривалість і створює відчуття, ніби ви на воді, а силові тренування на LYQUID дають нове відчуття роботи з вагою. До тренажерів пропонується членство з тренуваннями, а сезонні акції знижують вартість обладнання.', 'Hydrow follows a philosophy of fluid strength: in the company''s view, true strength is about power rather than bulk. The lineup has three models. Arc is the flagship rower with the most immersive experience and full-body force. Wave is a sleeker rower with a small footprint, available in five colors. LYQUID is a freestanding strength platform with isokinetic resistance that meets your effort at every moment of the movement. Rowing builds strength and endurance and feels like being on the water, while LYQUID offers a new way to lift. A workout membership accompanies the machines, and seasonal promotions reduce equipment prices.', 'Гребні тренажери Arc і Wave
Силова платформа LYQUID з ізокінетичним опором
Тренування на все тіло з ефектом занурення
Членство з контентом для тренувань
Компактні моделі для дому', 'Arc and Wave rowing machines
LYQUID strength platform with isokinetic resistance
Immersive full-body workouts
Membership with workout content
Compact models for home', 'Люди, які хочуть займатися веслуванням і силовими тренуваннями вдома на обладнанні з інтерактивним контентом.', 'People who want to row and strength train at home on equipment with interactive content.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
