SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'ifit.com' OR LOWER(`name`) = LOWER('iFIT'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'iFIT', NULL, 'https://www.ifit.com', NULL, NULL, 'iFIT — застосунок і членство для тренувань на тренажерах NordicTrack, ProForm та інших: понад 10 000 занять, тренування за пульсом ActivePulse, автоадаптація SmartAdjust і AI-тренер для цілей і прогресу.', 'iFIT is an app and membership for training on NordicTrack, ProForm and other machines: 10,000+ workouts, ActivePulse heart-rate training, SmartAdjust auto-tailoring and an AI coach for goals and progress.', 'iFIT — фітнес-платформа від виробника тренажерів NordicTrack, ProForm і Freemotion. Застосунок пропонує кардіо, силові, HIIT і відновлення з тренерами наживо або на вимогу, а також занурювальні маршрути від Евересту до Кіото. Під час тренування сумісний тренажер автоматично змінює нахил, швидкість і опір слідом за тренером. Членство iFIT Train за 15 USD на місяць працює з телефоном чи планшетом і відкриває понад 10 000 тренувань, тренування за пульсом ActivePulse, автоматичне налаштування складності SmartAdjust і AI-тренера, який допомагає ставити й відстежувати цілі. Є інтеграції зі Strava, Garmin і Apple Health; для тренажерів з екраном доступне членство iFIT Pro.', 'iFIT is the fitness platform from the maker of NordicTrack, ProForm and Freemotion equipment. The app offers cardio, strength, HIIT and recovery with trainers live or on demand, plus immersive routes from Everest to Kyoto. During a workout a compatible machine automatically follows the trainer''s incline, speed and resistance. The iFIT Train membership at 15 USD per month works on a phone or tablet and unlocks 10,000+ workouts, ActivePulse heart-rate training, SmartAdjust difficulty tailoring and an AI coach that helps set and track goals. It integrates with Strava, Garmin and Apple Health; iFIT Pro is available for machines with screens.', '10 000+ тренувань із тренерами
Автокерування тренажером за тренером
Тренування за пульсом ActivePulse
SmartAdjust під рівень підготовки
AI-тренер для цілей
Інтеграції зі Strava, Garmin, Apple Health', '10,000+ trainer-led workouts
Machine auto-control following the trainer
ActivePulse heart-rate training
SmartAdjust for your fitness level
AI coach for goals
Strava, Garmin and Apple Health integrations', 'Власники тренажерів NordicTrack, ProForm та інших iFIT-сумісних, а також ті, хто тренується з телефона.', 'Owners of NordicTrack, ProForm and other iFIT-enabled machines, and people training from a phone.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
