SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'joggo.run' OR LOWER(`name`) = LOWER('Joggo'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Joggo', NULL, 'https://joggo.run', NULL, NULL, 'Joggo — застосунок із персональним біговим планом для схуднення й здоров''я: короткий квіз про цілі й спосіб життя, оціночна пробіжка, план від тренерів-професіоналів і відстеження прогресу з досягненнями.', 'Joggo is an app with a personalized running plan for weight loss and health: a short quiz about goals and lifestyle, an assessment run, a plan by elite coaches and progress tracking with milestones.', 'Joggo допомагає прийти у форму у своєму темпі — пробіжка за пробіжкою. Спочатку ви проходите короткий квіз про цілі та спосіб життя, і сервіс складає індивідуальний біговий план, створений професійними тренерами. Після входу в застосунок потрібно виконати оціночну пробіжку, щоб план відповідав вашому фізичному рівню; одразу після цього план стає доступним. Далі застосунок відстежує прогрес, відзначає досягнення й підтримує на кожному кроці. Joggo розрахований і на новачків, і на досвідчених бігунів: він підлаштовується під ваш рівень і допомагає дійти до мети. На сайті також є історії користувачів і блог.', 'Joggo helps you get in shape on your own terms — one run at a time. First you take a short quiz about your goals and lifestyle, and the service builds a custom running plan created by elite coaches. After logging into the app you complete an assessment run so the plan matches your physical level; the plan is available right after that. The app then tracks progress, celebrates milestones and supports you every step of the way. Joggo is designed for beginners and experienced runners alike, adapting to your level and helping you reach your goal. The site also has user stories and a blog.', 'Квіз про цілі й спосіб життя
Персональний біговий план від тренерів
Оціночна пробіжка
Відстеження прогресу й досягнень
Для новачків і досвідчених', 'Quiz about goals and lifestyle
Personal running plan by coaches
Assessment run
Progress and milestone tracking
For beginners and experienced runners', 'Люди, які хочуть почати бігати або схуднути за допомогою бігу.', 'People who want to start running or lose weight through running.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
