INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'JRNY', NULL, 'https://www.jrny.com', NULL, NULL, 'JRNY — адаптивне фітнес-членство від BowFlex: персоналізовані кардіо, силові й загальні тренування, що оцінюють ваш рівень і самопочуття та підлаштовуються з кожним заняттям; одна підписка до шести користувачів.', 'JRNY is an adaptive fitness membership from BowFlex: personalized cardio, strength and whole-body workouts that assess your level and how you feel and adapt with every session; one subscription for up to six users.', 'JRNY — цифрова фітнес-платформа, що переосмислює персональні тренування. Адаптивне членство пропонує персоналізовані кардіо, силові та комплексні тренування, які змінюються разом із вами. Система вчиться з кожним заняттям: оцінює рівень підготовки й рекомендує тренування з урахуванням можливостей, вільного часу, самопочуття та інших факторів. На вибір тисячі варіантів тренувань, а займатися можна з сумісних пристроїв iOS та Android і на сумісних тренажерах. Одна підписка розрахована до шести користувачів. На сайті описано способи доступу, функції, сумісні продукти, ціни й відповіді на часті запитання. Підписка коштує від 11,99 USD на місяць або 99 USD на рік.', 'JRNY is a digital fitness platform that redefines personal training. The adaptive membership offers personalized cardio, strength and whole-body workouts that evolve as you do. It learns with each use by assessing your fitness level and recommending workouts based on your abilities, available time, how you are feeling and more. There are thousands of workout possibilities, and you can train from compatible iOS and Android devices and on compatible equipment. One subscription covers up to six users. The site explains ways to access it, features, compatible products, pricing and FAQs. Subscriptions start at 11.99 USD per month or 99 USD per year.', 'Адаптивні кардіо й силові тренування
Оцінка рівня з кожним заняттям
Рекомендації за часом і самопочуттям
До шести користувачів
Сумісні тренажери й iOS/Android', 'Adaptive cardio and strength workouts
Level assessment with every session
Recommendations by time and mood
Up to six users
Compatible equipment and iOS/Android', 'Власники сумісних тренажерів і родини, які тренуються вдома.', 'Owners of compatible equipment and families training at home.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
