-- KAYA — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'kayaclimb.com' OR LOWER(`name`) = LOWER('KAYA'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'KAYA', NULL, 'https://kayaclimb.com', NULL, NULL, 'KAYA — застосунок для скелелазів: GPS-гайдбуки від місцевих авторів з офлайн-навігацією до скель, понад мільйон бета-відео, журнал пролазів і сесій, 300 тис. скельних маршрутів і 200 залів та спільнота.', 'KAYA is an app for climbers: GPS guidebooks by local authors with offline navigation to the crag, over a million beta videos, an ascent and session log, 300k outdoor climbs and 200 gyms, plus a community.', 'KAYA допомагає знаходити боулдери й маршрути поруч і швидко діставатися до них. Гайдбуки пишуть місцеві скелелази, а GPS-навігація працює офлайн: перевірені автором парковки, стежки, мітки й топо скорочують підхід і залишають більше часу на лазіння. Бібліотека з понад мільйона бета-відео, створена спільнотою, впорядкована за маршрутами, районами й біометрією скелелазів, щоб знайти рішення, яке підходить саме вам. Застосунок дозволяє вести журнал пролазів, будувати піраміду складності й переглядати минулі сесії. У KAYA понад 300 тисяч маршрутів на скелях і 200 залів; можна знаходити друзів і партнерів. Є розділи для організацій, залів і брендів.', 'KAYA helps you find boulders and climbs nearby and get to them quickly. Guidebooks are written by local climbers, and GPS navigation works offline: author-verified parking, trails, pins and topos shorten the approach and leave more time for climbing. The community-built library of over a million beta videos is organized by climbs, areas and climber biometrics so you can find beta that fits you. The app lets you log ascents, build your grade pyramid and review past sessions. KAYA hosts 300k+ outdoor climbs and 200 gyms, and you can find friends and partners. There are sections for climbing organizations, gyms and brands.', 'GPS-гайдбуки з офлайн-картами
1 млн+ бета-відео
Журнал пролазів і сесій
300 тис. маршрутів і 200 залів
Пошук партнерів для лазіння', 'GPS guidebooks with offline maps
1M+ beta videos
Ascent and session log
300k climbs and 200 gyms
Find climbing partners', 'Скелелази й боулдеристи, які лазять на скелях і в залах.', 'Climbers and boulderers who climb outdoors and in gyms.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
