INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'KAYA helps you find boulders and climbs nearby and get to them quickly. Guidebooks are written by local climbers, and GPS navigation works offline: author-verified parking, trails, pins and topos shorten the approach and leave more time for climbing. The community-built library of over a million beta videos is organized by climbs, areas and climber biometrics so you can find beta that fits you. The app lets you log ascents, build your grade pyramid and review past sessions. KAYA hosts 300k+ outdoor climbs and 200 gyms, and you can find friends and partners. There are sections for climbing organizations, gyms and brands.', 'manual' FROM DUAL WHERE @new = 1;
