-- Kickoff — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'trainwithkickoff.com' OR LOWER(`name`) = LOWER('Kickoff'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Kickoff', NULL, 'https://www.trainwithkickoff.com', NULL, NULL, 'Kickoff — персональні тренування й коучинг із харчування, які покриває страховка в США: тренер із подвійною сертифікацією дієтолога й персонального тренера, щотижневі відеодзвінки та щоденні повідомлення.', 'Kickoff offers personal training and nutrition coaching covered by US insurance: a coach dual-certified as a registered dietitian and personal trainer, weekly video calls and daily texts.', 'Kickoff поєднує фітнес і харчування в одному коучингу. Кожен тренер має подвійну сертифікацію — зареєстрований дієтолог і персональний тренер, — тож програма вправ і харчування узгоджена між собою. Сервіс працює з більшістю страхових компаній у США, зокрема Aetna, Anthem, BlueCross BlueShield, Cigna й United Healthcare, і більшість клієнтів нічого не доплачують. Спочатку ви проходите квіз і отримуєте тренера, далі — щотижневі відеодзвінки, щоденні повідомлення та покрокові інструкції в застосунку. Контрактів і штрафів за скасування немає. Для порівняння компанія вказує, що очне заняття з дієтологом або тренером коштує від 100 USD.', 'Kickoff combines fitness and nutrition in one coaching program. Every coach is dual-certified as a registered dietitian and a personal trainer, so the exercise and nutrition plans fit together. The service works with most US insurers, including Aetna, Anthem, BlueCross BlueShield, Cigna and United Healthcare, and most clients pay nothing out of pocket. You start with a quiz and get matched with a coach, then have weekly video calls, daily texts and step-by-step guidance in the app. There are no contracts or cancellation fees. For comparison, the company notes that an in-person dietitian or trainer session costs 100 USD or more.', 'Тренер-дієтолог із подвійною сертифікацією
Покриття більшістю страховок у США
Щотижневі відеодзвінки
Щоденні повідомлення й підтримка
Поєднання вправ і харчування
Без контрактів', 'Dual-certified dietitian-trainer coach
Covered by most US insurance
Weekly video calls
Daily texts and support
Integrated exercise and nutrition
No contracts', 'Жителі США зі страховкою, які хочуть персонального тренера й дієтолога онлайн.', 'US residents with insurance who want an online personal trainer and dietitian.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
