-- Kinomap — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'kinomap.com' OR LOWER(`name`) = LOWER('Kinomap'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Kinomap', NULL, 'https://www.kinomap.com', NULL, NULL, 'Kinomap — інтерактивний застосунок для тренувань на велотренажері, біговій доріжці та гребному тренажері: понад 40 000 відео реальних маршрутів з усього світу, щоб тренуватися вдома, ніби на вулиці. Без монотонності.', 'Kinomap is an interactive app for indoor cycling, treadmill running and rowing: 40,000+ real-world route videos from around the world, so you can train at home as if you were outdoors.', 'Kinomap переосмислює тренування в приміщенні: замість монотонних хвилин на тренажері ви «їдете», «біжите» чи «веслуєте» реальними маршрутами. Бібліотека містить понад 40 000 відео з реальних трас у різних країнах, тож один і той самий маршрут можна ніколи не повторювати. Застосунок підходить і новачкам, і досвідченим спортсменам. Щоб почати, достатньо завантажити його на смартфон чи планшет, підключити велотренажер, бігову доріжку або гребний тренажер і обрати відео. Для пристроїв без Google Play передбачено окремий APK. На сайті є розділи з сумісним обладнанням, інструкціями для старту й тарифами.', 'Kinomap reimagines indoor training: instead of monotonous minutes on a machine you ride, run or row real routes. The library holds 40,000+ real-life videos from tracks in many countries, so you may never repeat the same route. The app suits both beginners and experienced athletes. To start, install it on a smartphone or tablet, connect your bike, treadmill or rower and pick a video. A separate APK is available for devices without Google Play. The site lists compatible equipment, getting-started guides and pricing.', '40 000+ відео реальних маршрутів
Велотренажер, бігова доріжка й гребний тренажер
Підключення обладнання через смартфон чи планшет
Підходить новачкам і спортсменам
APK для пристроїв без Google Play', '40,000+ real-world route videos
Bike, treadmill and rower support
Connect equipment via phone or tablet
Suits beginners and athletes
APK for devices without Google Play', 'Люди, які тренуються на кардіотренажерах удома й хочуть різноманітні маршрути замість монотонності.', 'People training on cardio machines at home who want varied routes instead of monotony.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
