-- Lattice Training — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'latticetraining.com' OR LOWER(`name`) = LOWER('Lattice Training'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Lattice Training', NULL, 'https://latticetraining.com', NULL, NULL, 'Lattice Training — персональні плани тренувань зі скелелазіння на основі даних: під ваші сильні й слабкі сторони, умови та графік, від плану в застосунку, що адаптується, до індивідуального коучингу. Є 14 днів безплатно.', 'Lattice Training offers data-driven personalized climbing training plans built around your strengths, weaknesses, facilities and schedule, from an adaptive in-app plan to one-on-one coaching.', 'Lattice Training складає плани для скелелазів — від аматорів до атлетів світового рівня. Кожен план враховує сильні й слабкі сторони, доступні умови для тренувань, вільний час і цілі, тож він ніколи не буває шаблонним. Методика спирається на дані й оцінювання, а клієнти мають доступ до тренерів із досвідом роботи з професіоналами. Найпопулярніший варіант — LatticePlan: план у застосунку, згенерований алгоритмом, що адаптується, коли ви записуєте тренування; він підходить для всіх дисциплін і фокусується на загальній продуктивності. Для глибшої роботи є персональні плани від тренера та індивідуальний коучинг. Також доступні освітні матеріали й магазин.', 'Lattice Training builds plans for climbers, from everyday climbers to world-class athletes. Each plan considers your strengths and weaknesses, available facilities, time and goals, so it is never one-size-fits-all. The methodology relies on data and assessments, and clients get access to coaches who have worked with professionals. The most popular option is LatticePlan: an algorithmically generated in-app plan that adapts as you log sessions; it works for all disciplines and focuses on overall performance. For deeper work there are coach-written custom plans and one-on-one coaching. Educational content and a shop are also available.', 'Персональні плани для скелелазів
Адаптивний LatticePlan у застосунку
Оцінювання на основі даних
Індивідуальний коучинг
Плани на продуктивність або гнучкість', 'Personalized plans for climbers
Adaptive LatticePlan in the app
Data-driven assessments
One-on-one coaching
Performance or flexibility focus', 'Скелелази всіх рівнів, які хочуть прогресувати за персональним планом.', 'Climbers of all levels who want to progress with a personal plan.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
