-- Les Mills+ — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'lesmills.com' OR LOWER(`name`) = LOWER('Les Mills+'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Les Mills+', NULL, 'https://www.lesmills.com', NULL, NULL, 'Застосунок LES MILLS+ — понад 2500 онлайн-тренувань від Les Mills для дому й залу: силові, бокс і бойові мистецтва, танці, сайкл, кардіо та HIIT, практики «тіло й розум». Програми поєднують науковий підхід, музику та рух.', 'The LES MILLS+ app offers 2,500+ online Les Mills workouts for home and the gym: strength, boxing and martial arts, dance, cycle, cardio and HIIT, plus mind-body practices. The programs combine a science-based approach with music and movement.', 'Les Mills — бренд групових тренувань, що поєднує науку, музику й рух. Через застосунок LES MILLS+ можна займатися вдома або в дорозі: у бібліотеці понад 2500 онлайн-тренувань, які доступні будь-коли. Тренування згруповано за напрямами — силові, бокс і бойові мистецтва, практики «тіло й розум», скульптурування, танці, сайкл, кругові тренування в стилі HYROX, кардіо та HIIT, а також окремі програми для людей старшого віку. Окрім застосунку, Les Mills пропонує пошук групових занять у фітнес-клубах поруч, навчання для майбутніх інструкторів і рішення для клубів. Для нових користувачів LES MILLS+ передбачено безплатний пробний період.', 'Les Mills is a group-fitness brand that combines science, music and movement. With the LES MILLS+ app you can train at home or on the go: the library holds 2,500+ online workouts available anytime. Workouts are grouped by type — strength, boxing and martial arts, mind-body, sculpt, dance, cycle, HYROX-style circuits, cardio and HIIT, plus dedicated programs for older adults. Beyond the app, Les Mills helps you find group classes at nearby clubs, trains future instructors and offers solutions for clubs. New LES MILLS+ users get a free trial.', 'Понад 2500 онлайн-тренувань
Силові, бокс, танці, сайкл, HIIT і йога-практики
Тренування під музику від інструкторів Les Mills
Пошук групових занять у клубах поруч
Програми для різного віку
Безплатний пробний період', '2,500+ online workouts
Strength, boxing, dance, cycle, HIIT and mind-body
Music-driven workouts from Les Mills instructors
Find group classes at nearby clubs
Programs for different ages
Free trial', 'Люди, які хочуть займатися фітнесом удома чи в залі за готовими тренуваннями під музику, а також фітнес-клуби та інструктори.', 'People who want to work out at home or in the gym with ready-made music-driven workouts, plus fitness clubs and instructors.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
