-- Liftosaur — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'liftosaur.com' OR LOWER(`name`) = LOWER('Liftosaur'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Liftosaur', NULL, 'https://www.liftosaur.com', NULL, NULL, 'Liftosaur — безплатний планувальник і трекер силових тренувань для iOS, Android і вебу: 50+ готових програм (GZCLP, 5/3/1, PPL) або власні програми мовою Liftoscript з автоматичною прогресією навантаження.', 'Liftosaur is a free strength workout planner and tracker for iOS, Android and web: 50+ built-in programs (GZCLP, 5/3/1, PPL) or your own programs in Liftoscript with automatic progressive overload.', 'Liftosaur поєднує гнучкість таблиці з зручністю трекера тренувань. Можна обрати перевірену програму — GZCLP, 5/3/1, PPL та ще понад 50 вбудованих — або написати власну простим текстом мовою Liftoscript. У ній задаються вправи за тижнями й днями, підходи та правила прогресивного навантаження, а за допомогою скриптів можна будувати складні схеми: міо-повторення, дроп-сети, зміну ваги, повторень, RPE чи таймера відпочинку. Під час тренування застосунок показує розминкові й робочі підходи та автоматично розраховує наступну вагу. Доступний як застосунок для iOS і Android і як веб-редактор; є документація й блог.', 'Liftosaur combines the flexibility of a spreadsheet with the convenience of a workout tracker. You can pick a proven program — GZCLP, 5/3/1, PPL and 50+ other built-in routines — or write your own in plain text with Liftoscript. It lets you specify exercises by week and day, sets and progressive overload rules, and scripts let you build advanced schemes: myo-reps, drop sets, changes to weight, reps, RPE or rest timer. During a workout the app shows warm-up and working sets and calculates the next weight automatically. It is available as an iOS and Android app and as a web editor, with docs and a blog.', '50+ готових програм (GZCLP, 5/3/1, PPL)
Власні програми мовою Liftoscript
Автоматична прогресія навантаження
