INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Liftosaur combines the flexibility of a spreadsheet with the convenience of a workout tracker. You can pick a proven program — GZCLP, 5/3/1, PPL and 50+ other built-in routines — or write your own in plain text with Liftoscript. It lets you specify exercises by week and day, sets and progressive overload rules, and scripts let you build advanced schemes: myo-reps, drop sets, changes to weight, reps, RPE or rest timer. During a workout the app shows warm-up and working sets and calculates the next weight automatically. It is available as an iOS and Android app and as a web editor, with docs and a blog.', 'manual' FROM DUAL WHERE @new = 1;
