SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'litesport.com' OR LOWER(`name`) = LOWER('Litesport'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Litesport', NULL, 'https://litesport.com', NULL, NULL, 'Litesport (раніше Liteboxer) — VR-фітнес для Meta Quest: бокс у ритмі музики, силові з гантелями та тренування на все тіло з реальними тренерами, які «переносяться» до вас додому; є безплатний пробний період.', 'Litesport (formerly Liteboxer) is VR fitness for Meta Quest: beat-based boxing, dumbbell strength and total-body workouts with real trainers who are transported into your home; a free trial is available.', 'Litesport — фітнес-застосунок у віртуальній реальності для гарнітур Meta Quest 3, Quest 3S та інших. Коли починається тренування, персональний тренер ніби з''являється у вашій кімнаті. Доступні три напрями: бокс із ударами в ритмі музики, що розвиває м''язи й реакцію; силові тренування з гантелями, де сертифіковані тренери стежать за технікою; та тренування на все тіло у форматі буткемпу з інтерактивними елементами, ухилами й нахилами. Заняття розраховані на будь-який рівень і допомагають урізноманітнити режим. Спільнота мотивує займатися регулярно, а для старту передбачено безплатний пробний період.', 'Litesport is a virtual reality fitness app for Meta Quest 3, Quest 3S and other headsets. When a workout starts, your personal trainer appears to be in your room. There are three formats: boxing with beat-based punches that builds muscle and mental acuity; strength training with dumbbells where certified trainers focus on form; and bootcamp-style total-body workouts with interactive elements, dodges and weaves. Workouts suit every level and help keep your routine fresh. The community keeps you training regularly, and there is a free trial to start.', 'VR-тренування для Meta Quest
Бокс у ритмі музики
Силові з гантелями й контролем техніки
Буткемп на все тіло
Реальні тренери
Безплатний пробний період', 'VR workouts for Meta Quest
Beat-based boxing
Dumbbell strength with form focus
Total-body bootcamp
Real trainers
Free trial', 'Власники VR-гарнітур Meta Quest, які хочуть займатися фітнесом удома в незвичному форматі.', 'Meta Quest owners who want to work out at home in an unusual format.', 'desktop', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
