INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Litesport is a virtual reality fitness app for Meta Quest 3, Quest 3S and other headsets. When a workout starts, your personal trainer appears to be in your room. There are three formats: boxing with beat-based punches that builds muscle and mental acuity; strength training with dumbbells where certified trainers focus on form; and bootcamp-style total-body workouts with interactive elements, dodges and weaves. Workouts suit every level and help keep your routine fresh. The community keeps you training regularly, and there is a free trial to start.', 'manual' FROM DUAL WHERE @new = 1;
