-- Madbarz — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'madbarz.com' OR LOWER(`name`) = LOWER('Madbarz'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Madbarz', NULL, 'https://www.madbarz.com', NULL, NULL, 'Madbarz — застосунок тренувань із власною вагою будь-де й будь-коли: плани для всіх рівнів, відстеження задіяних груп м''язів, графіки калорій, часу й повторень, налаштування під схуднення чи набір м''язів.', 'Madbarz is a bodyweight workout app for training anytime, anywhere: plans for all levels, tracking of activated muscle groups, graphs of calories, time and reps, and customization for fat loss or muscle gain.', 'Madbarz — застосунок для тих, хто хоче змінити тіло за допомогою тренувань із власною вагою. Тренування короткі, тож займатися можна будь-де й будь-коли. Кожне завершене заняття перетворюється на наочну статистику прогресу. Окрім планів для різних рівнів підготовки, застосунок показує, які групи м''язів ви вже тренували, щоб не пропускати жодну. Спалені калорії, час тренувань, повторення й регулярність відображаються на графіках і мотивують рухатися до мети. Програми налаштовуються під ваші потреби, рівень і цілі — схуднення чи набір м''язової маси. Спільнота Madbarz допомагає не втрачати мотивацію.', 'Madbarz is an app for people who want to transform their body with bodyweight training. Workouts are short, so you can train anytime, anywhere. Every completed session turns into clear progress insights. In addition to plans for all fitness levels, the app shows which muscle groups you have trained so you never neglect one. Calories burned, workout times, repetitions and consistency are shown on graphs that motivate you toward your goal. Programs can be tailored to your needs, level and goals — fat loss or muscle gain. The Madbarz community helps you stay motivated.', 'Тренування з власною вагою
Плани для всіх рівнів
Відстеження груп м''язів
Графіки калорій, часу й повторень
Налаштування під схуднення чи масу', 'Bodyweight workouts
Plans for all levels
Muscle group tracking
Graphs of calories, time and reps
Customization for fat loss or muscle', 'Люди, які тренуються вдома чи на вулиці без обладнання.', 'People training at home or outdoors without equipment.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
