-- MadMuscles — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'madmuscles.com' OR LOWER(`name`) = LOWER('MadMuscles'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'MadMuscles', NULL, 'https://madmuscles.com', NULL, NULL, 'MadMuscles — застосунок тренувань і харчування, який складає програму під ваші цілі, вік і рівень підготовки: понад 200 вправ, план харчування з урахуванням уподобань і обмежень, система формування звичок.', 'MadMuscles is a workout and nutrition app that builds a program for your goals, age and fitness level: 200+ exercises, a meal plan that respects your preferences and restrictions, and a habit-building system.', 'MadMuscles — мобільний застосунок, що робить регулярні тренування доступнішими. Після короткого опитування він підбирає структуровану програму з урахуванням мети, віку та рівня підготовки. У базі понад 200 вправ на різні групи м''язів, а програма поєднує статичні й динамічні вправи. Окремо застосунок пропонує план харчування на основі цілі та базового обміну речовин: його можна налаштувати під смакові вподобання й обмеження, при цьому жодні продукти не забороняються повністю. Система формування звичок допомагає не лише змінювати фігуру, а й закріплювати корисні рутини та тримати мотивацію. Розробники зазначають, що результат щодо схуднення не гарантується.', 'MadMuscles is a mobile app that makes regular workouts more accessible. After a short quiz it picks a structured program based on your goal, age and fitness level. The database contains 200+ exercises for different muscle groups, and programs combine static and dynamic movements. The app also offers a meal plan based on your goal and basal metabolic rate; it can be adjusted to taste preferences and restrictions, with no foods fully off-limits. A habit-building system helps you not only change your physique but also build healthy routines and stay motivated. The developers note that weight-loss results are not guaranteed.', 'Персональна програма під мету, вік і рівень
Понад 200 вправ для різних груп м''язів
План харчування з урахуванням обмежень
Система формування звичок
Служба підтримки в застосунку', 'Personal program for goal, age and level
200+ exercises for different muscle groups
Meal plan that respects restrictions
Habit-building system
In-app support', 'Люди, які хочуть тренуватися вдома чи в залі за готовою програмою та стежити за харчуванням.', 'People who want to train at home or in the gym with a ready-made program and keep an eye on nutrition.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
