INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'MadMuscles is a mobile app that makes regular workouts more accessible. After a short quiz it picks a structured program based on your goal, age and fitness level. The database contains 200+ exercises for different muscle groups, and programs combine static and dynamic movements. The app also offers a meal plan based on your goal and basal metabolic rate; it can be adjusted to taste preferences and restrictions, with no foods fully off-limits. A habit-building system helps you not only change your physique but also build healthy routines and stay motivated. The developers note that weight-loss results are not guaranteed.', 'manual' FROM DUAL WHERE @new = 1;
