-- MapMyRun — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'mapmyrun.com' OR LOWER(`name`) = LOWER('MapMyRun'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'MapMyRun', NULL, 'https://www.mapmyrun.com', NULL, NULL, 'MapMyRun — GPS-застосунок для бігу з персональними планами на 5 і 10 км, живим відстеженням для безпеки, голосовими підказками, челенджами з нагородами та базою маршрутів; преміум-функції — у підписці MVP.', 'MapMyRun is a running GPS app with personalized 5K and 10K plans, live tracking for safety, voice feedback, challenges with rewards and a route database; premium features come with the MVP subscription.', 'MapMyRun перетворює телефон або смарт-годинник на бігового тренера. Застосунок відстежує пробіжки за GPS, озвучує голосові підказки та дозволяє записувати тренування в журнал. Можна підписатися на тренувальні плани для 5 або 10 км і доповнити біг рекомендованими тренуваннями в залі, щоб залишатися здоровим. Функція живого відстеження підвищує безпеку: близькі бачать, де ви бігаєте. Щомісячні челенджі, зокрема від партнерських брендів, дають нагороди й допомагають ставити нові особисті рекорди. Велика база маршрутів допомагає знайти, де побігати. Розширені можливості відкриває преміум-підписка MVP.', 'MapMyRun turns your phone or smartwatch into a running coach. The app tracks runs via GPS, gives voice feedback and lets you log workouts. You can sign up for 5K or 10K training plans and add recommended gym workouts to stay healthy. Live tracking improves safety by letting loved ones see where you run. Monthly challenges, including ones from partner brands, unlock rewards and help you hit new personal records. A large route database helps you find places to run. The MVP premium subscription unlocks advanced features.', 'GPS-відстеження пробіжок
Плани на 5 і 10 км
Живе відстеження для безпеки
Голосові підказки
Челенджі з нагородами
База маршрутів', 'GPS run tracking
5K and 10K plans
Live tracking for safety
Voice feedback
Challenges with rewards
Route database', 'Бігуни-аматори, які хочуть відстежувати пробіжки, тренуватися за планом і знаходити нові маршрути.', 'Recreational runners who want to track runs, follow a plan and discover new routes.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
