-- McMillan Running — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'mcmillanrunning.com' OR LOWER(`name`) = LOWER('McMillan Running'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'McMillan Running', NULL, 'https://www.mcmillanrunning.com', NULL, NULL, 'McMillan Running — калькулятор бігових темпів і прогнозу результатів, калькулятори пульсових зон і поправки на спеку, бібліотека планів від 800 м до 100 миль та онлайн-коучинг від тренера Грега Макміллана.', 'McMillan Running offers a running pace and race prediction calculator, heart rate zone and heat adjustment calculators, a plan library from 800m to 100 miles, and online coaching from coach Greg McMillan.', 'McMillan Running — сервіс тренера з бігу Грега Макміллана. Найвідоміший інструмент — калькулятор тренувальних темпів: ви вказуєте мету й нещодавній результат на дистанції від 400 м до 100 миль, а він прогнозує результати й розраховує темпи для різних типів тренувань. Є також таблиця темпів, калькулятори пульсових зон і поправки на спеку. Бібліотека тренувальних планів охоплює дистанції від 800 м до марафону й ультра, а також спеціальні плани під конкретні забіги. Для глибшої підтримки доступні Run Team, індивідуальний онлайн-коучинг, очні тренування, персональні плани, програми силової підготовки та профілактики травм, а також матеріали для тренерів.', 'McMillan Running is the service of running coach Greg McMillan. Its best-known tool is the training pace calculator: you enter a goal and a recent race result from 400m to 100 miles, and it predicts race times and calculates paces for each type of workout. There is also a running pace chart, a heart rate zone calculator and a heat adjustment calculator. The training plan library covers distances from 800m to the marathon and ultras, plus race-specific plans. For deeper support there is Run Team, one-on-one online coaching, in-person coaching, custom plans, strength and injury programs, and resources for coaches.', 'Калькулятор темпів і прогнозу результатів
Калькулятори пульсових зон і поправки на спеку
Бібліотека тренувальних планів
Run Team і онлайн-коучинг
Силова підготовка й профілактика травм
Матеріали для тренерів', 'Pace and race prediction calculator
Heart rate zone and heat adjustment calculators
Training plan library
Run Team and online coaching
Strength and injury prevention
Resources for coaches', 'Бігуни, які готуються до забігів від 800 м до ультра, та тренери з бігу.', 'Runners preparing for races from 800m to ultras, and running coaches.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
