INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'MyWhoosh', NULL, 'https://mywhoosh.com', NULL, NULL, 'MyWhoosh — безплатний застосунок для віртуального велоспорту вдома: реальні маршрути світу, тренувальні програми, конструктор тренувань, гонки й події, режим веслування; працює на iOS, Android, macOS і ПК.', 'MyWhoosh is a free indoor virtual cycling app: real-world routes, training programs, a workout builder, races and events and a rowing mode; it runs on iOS, Android, macOS and PC.', 'MyWhoosh — застосунок для віртуальних велотренувань, у якому можна кататися реальними маршрутами з різних куточків світу, не виходячи з дому. Почати просто: завантажити застосунок на iOS, Android, macOS або ПК, підключити смарт-станок чи смарт-велосипед і вирушити в заїзд. Є тренувальні програми, конструктор власних тренувань, гонки та спеціальні події, зокрема чемпіонат світу UCI з велоспорту в кіберпросторі. Результати й активності зберігаються в профілі. Новий режим веслування додає в екосистему тренування на гребному тренажері з відстеженням показників. Спільнота дозволяє тренуватися й змагатися разом.', 'MyWhoosh is a virtual cycling app that lets you ride real routes from around the world without leaving home. Getting started is simple: install the app on iOS, Android, macOS or PC, pair a smart trainer or smart bike and start riding. There are training programs, a custom workout builder, races and special events, including the UCI Cycling Esports World Championships. Results and activities are stored in your profile. The new rowing mode brings indoor rowing into the ecosystem with performance tracking. The community lets you train and race together.', 'Реальні маршрути з усього світу
Тренувальні програми й конструктор тренувань
