INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'obé', NULL, 'https://obefitness.com', NULL, NULL, 'obé — платформа персоналізованих онлайн-тренувань для жінок: понад 16 000 занять на вимогу, 20+ типів класів (силові, скульпт, йога, пре- та постнатальні) і 70+ програм із метриками, що допомагають розуміти своє тіло.', 'obé is a personalized online workout platform for women: 16,000+ on-demand classes, 20+ class types (strength, sculpt, yoga, pre- and postnatal) and 70+ programs, with metrics that help you understand your body.', 'obé — сервіс домашніх тренувань, створений саме для жінок. Команда звертає увагу, що більшість рекомендацій щодо фізичних вправ досі базується на дослідженнях чоловіків, тож платформу побудовано навколо жіночої фізіології. У бібліотеці понад 16 000 занять на вимогу та понад 20 типів класів — від силових і скульптурувальних до йоги, а також програми для вагітних і після пологів. Понад 70 тренувальних програм ведуть користувачку місяцями до конкретної мети, поступово підвищуючи навантаження. Метрики допомагають відстежувати стан і прогрес. У США підписку можна оплатити коштами HSA/FSA, а для старту є безплатний пробний період.', 'obé is an at-home workout service built specifically for women. The team points out that most exercise guidance is still based on research on men, so the platform is designed around female physiology. The library has 16,000+ on-demand classes and 20+ class types — from strength and sculpt to yoga, plus prenatal and postnatal programs. More than 70 training programs guide users toward a goal over months with progressive load. Metrics help track how you feel and progress. In the US the subscription can be paid with HSA/FSA funds, and there is a free trial to start.', 'Понад 16 000 тренувань на вимогу
20+ типів занять: силові, скульпт, йога, пре- і постнатальні
70+ програм під конкретні цілі
Метрики для розуміння свого тіла
Підхід, побудований навколо жіночої фізіології
Безплатний пробний період', '16,000+ on-demand workouts
20+ class types: strength, sculpt, yoga, pre- and postnatal
70+ goal-based programs
Metrics to understand your body
An approach built around female physiology
Free trial', 'Жінки, які хочуть тренуватися вдома за програмами, що враховують їхню фізіологію та етап життя.', 'Women who want to work out at home with programs that respect their physiology and life stage.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
