-- Omstars — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'omstars.com' OR LOWER(`name`) = LOWER('Omstars'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Omstars', NULL, 'https://omstars.com', NULL, NULL, 'Omstars — живі й записані заняття йогою від Кіно Макгрегор та інших викладачів: аштанга, віньяса, інь, хатха, медитації, курси Yogaversity, програми для викладачів і рішення для корпоративного велнесу; 7 днів безплатно.', 'Omstars offers live and on-demand yoga from Kino MacGregor and other teachers: Ashtanga, vinyasa, yin, hatha, meditations, Yogaversity courses, teacher trainings and workplace wellness; 7 days free.', 'Omstars пропонує години онлайн-відео й уроків від команди майстрів йоги, експертів із добробуту та вчителів медитації, серед яких Кіно Макгрегор, Ахмед Соліман, Марк Роббердс, Діана Бонді та Марі Белль Перес Рівера. Популярні стилі — аштанга, віньяса, інь, хатха та керовані медитації; є теми гнучкості, балансів на руках, прогинів і доступної йоги, а також кулінарія, веганство, духовність та інтерв''ю з викладачами. Розділ Yogaversity містить поглиблені курси, наприклад вивчення «Йога-сутр» Патанджалі, навчання з інь-йоги для викладачів і проміжної серії аштанги. Є живі заняття, аудіо, програми для корпоративного велнесу й 7 днів безплатно.', 'Omstars offers hours of online videos and tutorials from a team of yoga masters, wellness experts and meditation teachers, including Kino MacGregor, Ahmed Soliman, Mark Robberds, Dianne Bondy and Marie Belle Perez Rivera. Popular styles include Ashtanga, vinyasa, yin, hatha and guided meditation, with themes such as flexibility, arm balances, backbends and accessible yoga, plus cooking, veganism, spirituality and teacher interviews. Yogaversity offers in-depth courses, such as studying Patanjali''s Yoga Sutras, yin yoga teacher training and the Ashtanga intermediate series. There are live classes, audio, workplace wellness programs and 7 days free.', 'Аштанга, віньяса, інь, хатха
Живі й записані заняття
Курси Yogaversity
Навчання для викладачів
Медитації й аудіо
Корпоративний велнес', 'Ashtanga, vinyasa, yin, hatha
Live and on-demand classes
Yogaversity courses
Teacher trainings
Meditations and audio
Workplace wellness', 'Практики йоги, викладачі та компанії з велнес-програмами.', 'Yoga practitioners, teachers and companies with wellness programs.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
