-- onX Backcountry — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'onxmaps.com/backcountry/app' OR LOWER(`name`) = LOWER('onX Backcountry'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'onX Backcountry', NULL, 'https://www.onxmaps.com/backcountry/app', NULL, NULL, 'onX Backcountry — GPS-навігація й карти стежок для походів, бекпекінгу, скелелазіння, гірського велосипеда, лиж і сноуборду: інструменти, що допомагають безпечно дістатися й повернутися, членство Elite і пробний період.', 'onX Backcountry offers GPS navigation and trail maps for hiking, backpacking, climbing, mountain biking, skiing and snowboarding: tools to get there and back safely, an Elite membership and a free trial.', 'onX Backcountry — застосунок GPS-навігації для активностей на природі: піших походів, бекпекінгу, кемпінгу, скелелазних маршрутів, гірського велосипеда, лиж і сноуборду. Він допомагає знаходити стежки поруч, планувати маршрути й ухвалювати кращі рішення завдяки детальним картам, а також безпечно дістатися до мети й повернутися назад. Членство Elite відкриває розширені можливості, а для початку доступний безплатний пробний період. Компанія onX також випускає застосунки для полювання, позашляхових поїздок і риболовлі, має сервіс екстреної допомоги onX SOS, рішення для бізнесу, майстер-класи, блог і магазин. На сайті можна порівняти тарифи.', 'onX Backcountry is a GPS navigation app for outdoor activities: hiking, backpacking, camping, climbing routes, mountain biking, skiing and snowboarding. It helps you find trails nearby, plan routes and make better decisions with detailed maps, and get to your destination and back safely. The Elite membership unlocks advanced features, and a free trial is available to start. onX also makes apps for hunting, off-roading and fishing, offers the onX SOS emergency service, business solutions, masterclasses, a blog and a shop. You can compare plans on the site.', 'GPS-навігація на природі
Карти стежок для походів і велосипеда
Скелелазні маршрути
Лижі й сноуборд
Членство Elite
Безплатний пробний період', 'Outdoor GPS navigation
Trail maps for hiking and biking
Climbing routes
Skiing and snowboarding
Elite membership
Free trial', 'Туристи, бекпекери, скелелази, велосипедисти й фрірайдери.', 'Hikers, backpackers, climbers, mountain bikers and backcountry skiers.', 'mobile,web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
