-- Oxygen Advantage — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'oxygenadvantage.com' OR LOWER(`name`) = LOWER('Oxygen Advantage'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Oxygen Advantage', NULL, 'https://oxygenadvantage.com', NULL, NULL, 'Oxygen Advantage — метод дихальних тренувань Патріка Маккеона для кращого дихання, результатів і здоров''я: тест BOLT за 2 хвилини, безплатна оцінка дихання, вступні курси, челенджі та сертифікація інструкторів.', 'Oxygen Advantage is Patrick McKeown''s breathwork method for better breathing, performance and health: a 2-minute BOLT test, a free breathing assessment, introductory courses, challenges and instructor certification.', 'Oxygen Advantage — метод дихальних тренувань, розроблений Патріком Маккеоном і його командою на основі досліджень фізіологічних принципів. Він допомагає покращити дихання, спортивні результати й здоров''я. Почати можна з тесту BOLT, який за дві хвилини оцінює ваше дихання, та з безплатної оцінки, що перевіряє сон, стрес і фізичну форму. Вступні курси стають сходинками до сертифікації інструктора. Для практики є челенджі — наприклад, пробігти 5 км, дихаючи лише носом, або підвищити толерантність до CO₂ затримками дихання. На сайті пояснюється метод і наукове підґрунтя, є блог, подкаст і інформація про команду.', 'Oxygen Advantage is a breathing training method developed by Patrick McKeown and his team based on research into physiological principles. It helps improve breathing, athletic performance and health. You can start with the BOLT test, which assesses your breathing in two minutes, and a free assessment that checks sleep, stress and fitness. Introductory courses are stepping stones to instructor certification. For practice there are challenges — for example, running a 5K breathing only through your nose or improving CO₂ tolerance with breath holds. The site explains the method and science and has a blog, a podcast and team information.', 'Тест BOLT за 2 хвилини
Безплатна оцінка дихання
Вступні курси
Сертифікація інструкторів
Челендж «5 км носом»
Тренування толерантності до CO₂', '2-minute BOLT test
Free breathing assessment
Introductory courses
Instructor certification
Nasal 5K challenge
CO₂ tolerance training', 'Спортсмени, тренери та всі, хто хоче дихати ефективніше.', 'Athletes, coaches and anyone who wants to breathe more efficiently.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
