INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Pacer', NULL, 'https://www.mypacer.com', NULL, NULL, 'Pacer — застосунок для ходьби: крокомір, GPS-карти прогулянок, карти парків поруч, клуби ходьби, челенджі з кроками й медалі, а також калькулятори темпу, калорій і схуднення від ходьби; базова версія безплатна.', 'Pacer is a walking app: a pedometer, GPS walk maps, nearby park maps, walking clubs, step challenges and medals, plus pace, calorie and walking weight-loss calculators; the basic version is free.', 'Pacer допомагає стати активнішим через звичайну ходьбу. Застосунок рахує кроки, записує маршрути за GPS і показує карти місцевих парків і місць для прогулянок поруч. Мотивацію підтримують клуби ходьби, челенджі з кроками та медалі. Для роботодавців є окреме рішення з корпоративними челенджами. На сайті доступні корисні калькулятори: перерахунок різних активностей у кроки для челенджів, розрахунок швидкості й темпу ходьби, переведення кроків у кілометри, планування щоденної ходьби для схуднення та оцінка спалених калорій. Блог дає поради щодо ходьби, фітнесу та здорового способу життя. Завантажити й почати користуватися можна безплатно.', 'Pacer helps you get more active through everyday walking. The app counts steps, records routes via GPS and shows maps of local parks and walking spots nearby. Walking clubs, step challenges and medals keep you motivated. There is a separate solution for employers with workplace challenges. The site offers handy calculators: converting activities into step equivalents for challenges, walking speed and pace, steps to kilometres, planning daily walking for weight loss and estimating calories burned. The blog shares tips on walking, fitness and healthy living. You can download it and start for free.', 'Крокомір і GPS-маршрути
Карти парків поруч
Клуби ходьби й челенджі
Медалі за досягнення
Калькулятори темпу й калорій
Рішення для компаній', 'Pedometer and GPS routes
Nearby park maps
Walking clubs and challenges
Achievement medals
Pace and calorie calculators
Workplace solution', 'Люди, які хочуть більше рухатися через ходьбу, та компанії з велнес-програмами.', 'People who want to move more through walking, and companies with wellness programs.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
