-- PeakVisor — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'peakvisor.com' OR LOWER(`name`) = LOWER('PeakVisor'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'PeakVisor', NULL, 'https://peakvisor.com', NULL, NULL, 'PeakVisor — застосунок для гір і природи з доповненою реальністю: розпізнавання вершин, 3D-карти, пішохідні маршрути, гайди від місцевих, карти гірськолижних курортів у реальному часі, траєкторії сонця й місяця.', 'PeakVisor is an augmented reality app for mountains and nature: peak identification, 3D maps, hiking trails, local guides, real-time ski resort maps and sun and moon trajectories.', 'PeakVisor допомагає орієнтуватися в горах і на природі. Головна функція — розпізнавання вершин у доповненій реальності: наведіть камеру на гори, і застосунок підпише їхні назви та висоти. Детальні 3D-карти дозволяють планувати маршрути й досліджувати рельєф, а пішохідні карти й гайди від місцевих жителів допомагають обрати похід. Для лижників є карти гірськолижних курортів із даними в реальному часі. Також можна переглядати траєкторії сонця й місяця, що корисно для походів і фотографії, та імпортувати власні фото, щоб розпізнати вершини на них. Застосунок доступний багатьма мовами, а PeakVisor Pro можна придбати назавжди, зокрема в подарунок.', 'PeakVisor helps you navigate mountains and natural areas. Its signature feature is augmented reality peak identification: point the camera at mountains and the app labels their names and heights. Detailed 3D maps let you plan routes and explore terrain, and hiking maps and guides by locals help you choose a hike. Skiers get ski resort maps with real-time data. You can also view sun and moon trajectories, useful for hiking and photography, and import your own photos to identify peaks in them. The app is available in many languages, and PeakVisor Pro can be bought for life, including as a gift.', 'Розпізнавання вершин у AR
3D-карти
Пішохідні маршрути й гайди
Карти курортів у реальному часі
Траєкторії сонця й місяця
Розпізнавання вершин на фото', 'AR peak identification
3D maps
Hiking trails and guides
Real-time resort maps
Sun and moon trajectories
Peak identification in photos', 'Туристи, альпіністи, лижники й фотографи в горах.', 'Hikers, mountaineers, skiers and mountain photographers.', 'mobile,web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
