-- Playtomic — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'playtomic.com' OR LOWER(`name`) = LOWER('Playtomic'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Playtomic', NULL, 'https://playtomic.com', NULL, NULL, 'Playtomic — застосунок для гравців у падел, теніс і пікбол: бронювання кортів, пошук партнерів і матчів поруч; для клубів — Playtomic Manager із розкладом, оплатами, турнірами, лігами та модулем для тренерів.', 'Playtomic is an app for padel, tennis and pickleball players: book courts and find partners and matches nearby; clubs get Playtomic Manager with scheduling, payments, tournaments, leagues and a coach module.', 'Playtomic об''єднує гравців, клуби й тренерів у ракеткових видах спорту. Гравці можуть знаходити корти й клуби поруч або в подорожі, бронювати падел-, тенісні та пікбольні корти, приєднуватися до матчів і знаходити партнерів свого рівня. Для клубів є Playtomic Manager: тарифи Standard, Professional, Champion і Master включають розклад і блокування кортів, чати, базу клієнтів, оплати, публічні заняття, звіти й турніри, а на вищих рівнях — POS-систему, гаманець, членства, ліги, курси, рахунки, API-інтеграції та маркетингові кампанії. Окремі модулі Playtomic Coach і Academy допомагають тренерам вести заняття та навчання.', 'Playtomic brings together players, clubs and coaches in racket sports. Players can find courts and clubs nearby or while traveling, book padel, tennis and pickleball courts, join matches and find partners at their level. Clubs get Playtomic Manager: the Standard, Professional, Champion and Master plans include court scheduling and blocking, chats, a customer base, payments, public classes, reports and tournaments, while higher tiers add a POS system, wallet, memberships, leagues, courses, invoices, API integrations and marketing campaigns. Separate Playtomic Coach and Academy modules help coaches run lessons and training.', 'Бронювання кортів для падела, тенісу й пікболу
Пошук матчів і партнерів
Playtomic Manager для клубів
Турніри, ліги й членства
Модуль для тренерів', 'Court booking for padel, tennis and pickleball
Find matches and partners
Playtomic Manager for clubs
Tournaments, leagues and memberships
Coach module', 'Гравці в падел, теніс і пікбол, а також клуби та тренери.', 'Padel, tennis and pickleball players, as well as clubs and coaches.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
