SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'precisionhydration.com' OR LOWER(`name`) = LOWER('Precision Fuel & Hydration'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Precision Fuel & Hydration', NULL, 'https://www.precisionhydration.com', NULL, NULL, 'Precision Fuel & Hydration допомагає атлетам персоналізувати гідратацію та підживлення: безплатний онлайн-тест поту, калькулятор вуглеводів і план на старт, плюс лінійка електролітів, гелів і батончиків різної концентрації.', 'Precision Fuel & Hydration helps athletes personalize hydration and fueling: a free online sweat test, carb calculator and race plan, plus multi-strength electrolytes, gels and chews.', 'Precision Fuel & Hydration спеціалізується на тому, щоб спортсмени на витривалість знали свої цифри — скільки рідини, натрію й вуглеводів їм потрібно. На сайті можна безплатно скласти персональний план харчування й гідратації на старт за допомогою планувальника, онлайн-тесту поту та калькулятора вуглеводів, а також записатися на безплатний відеодзвінок із консультантом. У компанії є лабораторія та мережа центрів, де проводять тести поту, зокрема для професійних команд. Щоб легко влучати в цифри, бренд продає електроліти різної концентрації, напої з вуглеводами й електролітами, гелі та жувальні цукерки PF 30, а також підписку з регулярними доставками.', 'Precision Fuel & Hydration helps endurance athletes know their numbers — how much fluid, sodium and carbohydrate they need. On the site you can build a free personalized race fuel and hydration plan with the planner, an online sweat test and a carb calculator, and book a free video call with an advisor. The company has a performance lab and a network of sweat test centers, including for pro teams. To make hitting the numbers easy, the brand sells multi-strength electrolytes, carb and electrolyte drink mixes, PF 30 gels and chews, plus a subscription with regular deliveries.', 'Безплатний план харчування й гідратації
Онлайн-тест поту
Калькулятор вуглеводів
Електроліти різної концентрації
Гелі й жувальні цукерки PF 30
Консультації та тести поту в лабораторії', 'Free fuel and hydration plan
Online sweat test
Carb calculator
Multi-strength electrolytes
PF 30 gels and chews
Advice and lab sweat testing', 'Бігуни, тріатлоністи, велосипедисти та інші спортсмени на витривалість.', 'Runners, triathletes, cyclists and other endurance athletes.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
