SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'punchlab.net' OR LOWER(`name`) = LOWER('PunchLab'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'PunchLab', NULL, 'https://punchlab.net', NULL, NULL, 'PunchLab — інтерактивні тренування з боксу вдома: 300+ занять із відстеженням ударів у реальному часі через телефон на мішку або Bluetooth-трекери на зап''ястях, навіть для бою з тінню без мішка. Для новачків і досвідчених.', 'PunchLab offers interactive boxing workouts at home: 300+ guided sessions with real-time punch tracking via a phone strapped to the bag or Bluetooth wrist trackers, even for shadowboxing without a bag.', 'PunchLab перетворює будь-яку кімнату на боксерський зал. Застосунок пропонує понад 300 занять, які допомагають вивчити техніку, наростити силу удару, спалити калорії та тримати мотивацію. Головна особливість — відстеження ударів у реальному часі. Можна закріпити телефон на мішку за допомогою фірмового ремінця PunchLab: застосунок використовує датчики руху смартфона, щоб фіксувати удари й показувати статистику тренування. Для бою з тінню без мішка є Bluetooth-трекери на зап''ястя, що з''єднуються з телефоном і вимірюють кожен удар. Аксесуари продаються на Amazon, а заняття підходять і новачкам, і тим, хто хоче вдосконалити техніку.', 'PunchLab turns any room into a boxing gym. The app offers 300+ guided workouts that help you learn technique, build punching power, burn calories and stay motivated. Its key feature is real-time punch tracking. You can attach your phone to the bag with the PunchLab Strap: the app uses the phone''s motion sensors to capture punches and show workout insights. For shadowboxing without a bag there are Bluetooth wrist trackers that connect to the phone and measure every punch. Accessories are sold on Amazon, and workouts suit both beginners and those refining their technique.', '300+ інтерактивних тренувань з боксу
Відстеження ударів у реальному часі
Ремінець для телефона на мішку
Bluetooth-трекери для бою з тінню
Статистика сили й техніки', '300+ interactive boxing workouts
Real-time punch tracking
Phone strap for the bag
Bluetooth trackers for shadowboxing
Power and technique stats', 'Ті, хто хоче займатися боксом удома — з мішком або без нього.', 'People who want to box at home, with or without a punching bag.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
