-- PVOLVE — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'pvolve.com' OR LOWER(`name`) = LOWER('PVOLVE'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'PVOLVE', NULL, 'https://www.pvolve.com', NULL, NULL, 'PVOLVE — метод функціональних силових тренувань для довготривалої сили, мобільності й стабільності: стрімінг занять, спеціальне обладнання в наборах для дому та студії з тренерами; квіз допоможе обрати старт.', 'PVOLVE is a functional strength training method for long-term strength, mobility and stability: streaming classes, specialized equipment bundles for home and in-studio sessions with trainers; a quiz helps you start.', 'PVOLVE пропонує фірмовий метод силових тренувань, спрямований на те, щоб тіло залишалося сильним і функціональним довгі роки. Тренування поєднують силу, мобільність і стабільність і виконуються зі спеціальним обладнанням бренду. Займатися можна вдома — через стрімінг занять на вимогу разом із наборами обладнання, які продаються зі знижкою в комплекті, — або в студіях PVOLVE з тренерами та спільнотою. Якщо незрозуміло, з чого почати, двохвилинний квіз підбере відповідний варіант і набір. На сайті також є розділи про те, чому метод працює, клінічні результати, історії учасників, одяг, аксесуари й добавка Sculpt 9.', 'PVOLVE offers a signature strength training method aimed at keeping the body strong and capable for the long term. Workouts combine strength, mobility and stability and use the brand''s specialized equipment. You can train at home with on-demand streaming plus equipment bundles sold at a discount, or in PVOLVE studios with expert trainers and the community. If you are not sure where to start, a two-minute quiz recommends the right option and bundle. The site also explains why the method works, shares clinical results and member stories, and sells apparel, accessories and the Sculpt 9 supplement.', 'Фірмовий метод функціональних силових тренувань
Стрімінг занять на вимогу
Набори спеціального обладнання
Студії з тренерами
Квіз для вибору старту', 'Signature functional strength method
On-demand streaming classes
Specialized equipment bundles
Studios with trainers
Quiz to choose your start', 'Люди, які хочуть розвивати силу, мобільність і стабільність удома чи в студії.', 'People who want to build strength, mobility and stability at home or in a studio.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
