INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Relive', NULL, 'https://www.relive.com', NULL, NULL, 'Relive — застосунок, що перетворює ваші пробіжки, велопоїздки й походи на красиві історії з анімованими 3D-відео: відстежуйте активності, діліться ними та стежте за пригодами друзів, підключивши свій трекер.', 'Relive turns your runs, rides and hikes into beautiful stories with animated 3D videos: track activities, share them and follow friends'' adventures, connecting the tracker you already use.', 'Relive допомагає не лише записувати активності, а й красиво ними ділитися. Застосунок відстежує пробіжки, велопоїздки, походи та інші активності на природі й показує, як ви впоралися. Головна фішка — історії з анімованими 3D-відео маршруту, які можна відправити друзям чи в соцмережі. Можна підписуватися на друзів та інших людей і стежити за їхніми пригодами, а стрічка обходиться без настирливої реклами. Relive підключається до багатьох інших трекерів і застосунків, тож не важливо, чим ви записуєте тренування. Розширені можливості доступні в підписці Relive Plus. Застосунок підходить і для щоденних прогулянок, і для великих подорожей.', 'Relive helps you not only record activities but also share them beautifully. The app tracks runs, rides, hikes and other outdoor activities and shows how you did. Its signature feature is stories with animated 3D videos of your route that you can send to friends or post on social media. You can follow friends and other people to see their adventures, and the feed has no annoying ads. Relive connects with many other trackers and apps, so it doesn''t matter what you record with. Extra features are available with the Relive Plus subscription. The app suits both everyday outings and big trips.', 'Відстеження активностей на природі
Анімовані 3D-відео маршрутів
Історії для соцмереж
Підписки на друзів
Підключення інших трекерів
Підписка Relive Plus', 'Outdoor activity tracking
Animated 3D route videos
Stories for social media
Follow friends
Connect other trackers
Relive Plus subscription', 'Бігуни, велосипедисти й туристи, які люблять ділитися своїми пригодами.', 'Runners, cyclists and hikers who like sharing their adventures.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
