-- Ride with GPS — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'ridewithgps.com' OR LOWER(`name`) = LOWER('Ride with GPS'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Ride with GPS', NULL, 'https://ridewithgps.com', NULL, NULL, 'Ride with GPS — платформа для велосипедистів: пошук маршрутів від місцевих авторів, точний планувальник і редактор маршрутів, надійна навігація для iPhone та Android, синхронізація з Garmin і Wahoo. Є безплатний тариф.', 'Ride with GPS is a platform for cyclists: locally curated route discovery, a precise route planner and editor, reliable navigation for iPhone and Android, and sync with Garmin and Wahoo.', 'Ride with GPS — застосунок і вебплатформа для планування маршрутів і навігації, створені саме для велосипедистів. Можна знаходити якісні маршрути від місцевих авторів по всьому світу з фільтрами, фото й свіжими відгуками. Флагманський планувальник дозволяє створювати, змінювати й ділитися маршрутами з точними інструментами картографування й редагування. Мобільна навігація для iPhone та Android працює надійно, а маршрути синхронізуються з пристроями Garmin, Wahoo та іншими велокомп''ютерами. Безплатний тариф Starter дає пошук маршрутів, запис поїздок і планування на сайті. Premium додає повні інструменти планування, теплові карти, власні підказки, аналіз поїздок, друк карт і приватні сегменти; є 7 днів безплатно.', 'Ride with GPS is an app and web platform for route planning and navigation built just for cyclists. You can discover high-quality, locally curated routes worldwide with filters, photos and recent reviews. The flagship Route Planner lets you create, modify and share routes with precise mapping and editing tools. Mobile navigation for iPhone and Android is ultra-reliable, and routes sync with Garmin, Wahoo and other cycling computers. The free Starter tier covers route discovery, ride recording and website planning. Premium adds full planning tools, heatmaps, custom cues, ride analysis, map printing and private segments, with a 7-day free trial.', 'Пошук маршрутів від місцевих авторів
Планувальник і редактор маршрутів
Навігація для iPhone та Android
Синхронізація з Garmin і Wahoo
Теплові карти й аналіз поїздок у Premium', 'Locally curated route discovery
Route planner and editor
Navigation for iPhone and Android
Garmin and Wahoo sync
Heatmaps and ride analysis in Premium', 'Велосипедисти всіх рівнів, які планують поїздки й подорожі, а також велоклуби.', 'Cyclists of all levels planning rides and tours, and cycling clubs.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
