-- ROUVY — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'rouvy.com' OR LOWER(`name`) = LOWER('ROUVY'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'ROUVY', NULL, 'https://rouvy.com', NULL, NULL, 'ROUVY — застосунок для велотренувань удома на реальних маршрутах і справжніх ухилах зі смарт-станком: тренування, плани, челенджі, події, власні маршрути через Route Creator і аналіз даних у Riders Portal.', 'ROUVY is an indoor cycling app with real-world routes and real gradients on a smart trainer: workouts, plans, challenges, events, your own routes via Route Creator and data analysis in the Riders Portal.', 'ROUVY — застосунок для велосипедистів, який допомагає тримати форму цілий рік. Зі смарт-станком ви проїжджаєте реальні дороги з реальними ухилами: можна, наприклад, проїхати Мальорку перед відпусткою. Є тренування й плани для зростання FTP, підготовка до тріатлону, челенджі, події та спільні заїзди. У Riders Portal зручно шукати маршрути, планувати цілі й аналізувати дані, а застосунок на телефоні показує і домашні, і вуличні заїзди. Route Creator дозволяє зняти улюблений маршрут на відео, перетворити його на віртуальний і поділитися з іншими. Усі тарифи починаються з 7-денного безплатного періоду, підписку можна поставити на паузу до 180 днів.', 'ROUVY is a cycling app that keeps you riding all year. With a smart trainer you ride real roads with real gradients — for example, riding Mallorca before a cycling holiday. There are workouts and plans to raise your FTP, triathlon preparation, challenges, events and group rides. The Riders Portal makes it easy to find routes, plan goals and analyze data, and the phone app shows both indoor and outdoor rides. Route Creator lets you film your favorite ride, turn it into a virtual route and share it. All plans start with a 7-day free trial, and subscriptions can be paused for up to 180 days.', 'Реальні маршрути з реальними ухилами
Тренування й плани для FTP і тріатлону
Події, челенджі й спільні заїзди
Route Creator для власних маршрутів
Аналіз даних у Riders Portal
7 днів безплатно', 'Real routes with real gradients
Workouts and plans for FTP and triathlon
Events, challenges and group rides
Route Creator for your own routes
Data analysis in the Riders Portal
7-day free trial', 'Велосипедисти й тріатлоністи, які тренуються вдома на смарт-станку.', 'Cyclists and triathletes who train indoors on a smart trainer.', 'web,mobile,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
