-- RP Hypertrophy — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'rpstrength.com/pages/hypertrophy-app' OR LOWER(`name`) = LOWER('RP Hypertrophy'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'RP Hypertrophy', NULL, 'https://rpstrength.com/pages/hypertrophy-app', NULL, NULL, 'RP Hypertrophy — застосунок для набору м''язової маси від Renaissance Periodization і д-ра Майка Ісраетела: 100+ готових планів, автоматична прогресія ваги й повторень щотижня, 250+ відео техніки. Для новачків і досвідчених.', 'RP Hypertrophy is a muscle-building app from Renaissance Periodization and Dr. Mike Israetel: 100+ premade plans, weekly automatic weight and rep progression and 250+ technique videos.', 'RP Hypertrophy App — застосунок від Renaissance Periodization, що працює як тренер у кишені. Він підходить і новачкам, і досвідченим відвідувачам залу та дає персональні рекомендації щодо тренувань, які розробила команда д-ра Майка Ісраетела. У застосунку понад 100 готових тренувальних планів, зокрема програми з акцентом на окремі групи м''язів. Прогресію заплановано за вас: щотижня ви знаєте, яку вагу та скільки повторень виконувати для оптимального росту. Понад 250 відео з технікою допомагають виконувати кожен підхід ефективно, а бібліотека вправ постійно поповнюється. Окремо RP пропонує застосунок Diet Coach, індивідуальний коучинг, шаблони й безплатні матеріали.', 'The RP Hypertrophy App from Renaissance Periodization works like a coach in your pocket. It suits beginners and veteran gym-goers alike and gives personalized training recommendations developed by Dr. Mike Israetel''s team. The app has 100+ premade training plans, including body-part specialization programs. Progression is planned for you: every week you know exactly what weight and reps to hit for the best growth. 250+ technique videos help you get the most out of each set, and the exercise library keeps expanding. RP also offers the Diet Coach app, one-on-one coaching, templates and free content.', '100+ готових планів на масу
Програми з акцентом на групи м''язів
Автоматична щотижнева прогресія
250+ відео техніки
Бібліотека вправ, що поповнюється', '100+ premade hypertrophy plans
Body-part specialization programs
Automatic weekly progression
250+ technique videos
