INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'The RP Hypertrophy App from Renaissance Periodization works like a coach in your pocket. It suits beginners and veteran gym-goers alike and gives personalized training recommendations developed by Dr. Mike Israetel''s team. The app has 100+ premade training plans, including body-part specialization programs. Progression is planned for you: every week you know exactly what weight and reps to hit for the best growth. 250+ technique videos help you get the most out of each set, and the exercise library keeps expanding. RP also offers the Diet Coach app, one-on-one coaching, templates and free content.', 'manual' FROM DUAL WHERE @new = 1;
