SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'runcoach.com' OR LOWER(`name`) = LOWER('Runcoach'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Runcoach', NULL, 'https://runcoach.com', NULL, NULL, 'Runcoach — онлайн-підготовка до марафону з живим тренером: застосунок аналізує тренування, а персональний тренер переглядає дані, коригує план у реальному часі й відповідає на запитання; 14 днів безплатно.', 'Runcoach is online marathon training with a human coach: the app analyzes your training while your personal coach reviews the data, adjusts the plan in real time and answers questions; 14 days free.', 'Runcoach — застосунок для бігунів від новачків до досвідчених, у якому тренування аналізує справжній тренер. Після підбору ви отримуєте свого тренера, який переглядає ваші дані, коригує план у реальному часі, щоб ви трималися курсу, і допомагає з стратегією, зокрема коли ви готуєтеся до кількох забігів, не втрачаючи з поля зору головну мету. Тренер завжди на зв''язку в застосунку, відповідає на запитання й дає зворотний зв''язок. За даними компанії, клієнти Premium покращують фінішний час у середньому на 7%. Є 14-денний безплатний період, а підписку можна оформити помісячно, на півроку чи на рік без контрактів.', 'Runcoach is an app for beginner to advanced runners where a real coach analyzes your training. After matching you get your own coach, who reviews your data, adjusts your plan in real time to keep you on track and helps with strategy, including when you train for several races while staying focused on your big goal. The coach is always reachable in the app to answer questions and give feedback. According to the company, Premium customers improve finish times by 7% on average. There is a 14-day free trial, and memberships are monthly, semi-annual or annual with no contracts.', 'Персональний тренер 1:1 у застосунку
Аналіз тренувальних даних
Коригування плану в реальному часі
Стратегія для кількох забігів
Без контрактів
14 днів безплатно', '1:1 coach in the app
Training data analysis
Real-time plan adjustments
Strategy for multiple races
No contracts
14 days free', 'Бігуни, які готуються до марафону чи інших забігів і хочуть підтримку живого тренера.', 'Runners preparing for a marathon or other races who want support from a human coach.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
