-- SensAI — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sensai.fit' OR LOWER(`name`) = LOWER('SensAI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SensAI', NULL, 'https://www.sensai.fit', NULL, NULL, 'SensAI — AI-персональний тренер: плани, що адаптуються до відновлення, цілей і графіка за даними Apple Watch, Garmin чи Oura, розмовний коуч із пам''яттю про травми та трекер підходів із пульсовими зонами.', 'SensAI is an AI personal trainer: plans that adapt to recovery, goals and schedule using Apple Watch, Garmin or Oura data, a conversational coach that remembers injuries and a set tracker with heart rate zones.', 'SensAI — застосунок, що працює як персональний тренер на основі AI і підключається до носимих пристроїв Apple Watch, Garmin та Oura. Плани тренувань адаптуються до вашого відновлення, цілей і розкладу. Під час заняття трекер веде підхід за підходом із таймерами відпочинку, візуалізацією груп м''язів і пульсовими зонами в реальному часі, а AI-тренер може змінити тренування прямо по ходу. Якщо тренажер зайнятий, застосунок запропонує альтернативу. Розмовний коуч пам''ятає історію, травми й обмеження, дає персональні поради, приймає фото для оцінки техніки, аналізу страви чи розпізнавання тренажера. Працює офлайн, завантажується безплатно.', 'SensAI is an AI-powered personal trainer app that connects to Apple Watch, Garmin and Oura wearables. Workout plans adapt to your recovery, goals and schedule. During a session the tracker guides you set by set with rest timers, muscle group visuals and real-time heart rate zones, and the AI coach can adjust the workout mid-session. If equipment is busy, the app suggests a smart alternative. The conversational coach remembers your history, injuries and constraints, gives personal advice and accepts photos for form feedback, meal analysis or gym equipment identification. It works offline and is free to download.', 'Плани з урахуванням відновлення
Підключення Apple Watch, Garmin, Oura
Трекер підходів із пульсовими зонами
Заміна вправ, коли тренажер зайнятий
Розмовний AI-коуч із пам''яттю
Оцінка техніки та страв за фото', 'Recovery-aware plans
Apple Watch, Garmin and Oura connection
Set tracker with heart rate zones
Exercise swaps when equipment is busy
Conversational AI coach with memory
Form and meal feedback from photos', 'Відвідувачі залу з носимими пристроями, які хочуть персональний план без живого тренера.', 'Gym-goers with wearables who want a personal plan without a human trainer.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
