SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'getslopes.com' OR LOWER(`name`) = LOWER('Slopes'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Slopes', NULL, 'https://getslopes.com', NULL, NULL, 'Slopes — застосунок для лижників і сноубордистів на iPhone, Android та Apple Watch: детальна статистика дня й сезону, офіційні та інтерактивні карти трас для 2000+ курортів, пошук друзів і звіти про умови.', 'Slopes is an app for skiers and snowboarders on iPhone, Android and Apple Watch: detailed day and season stats, official and interactive trail maps for 2,000+ resorts, friend finding and condition reports.', 'Slopes створила невелика команда, закохана в лижі та сноуборд. Застосунок записує ваші дні на схилі та дає детальну статистику: перепад висоти, максимальну й середню швидкість, дистанцію, час на підйомнику проти часу на спуску, калорії, висоту й пульс, а також підсумки за сезон і за весь час. Офіційні карти трас тисяч курортів завжди під рукою, а на понад 2000 підтримуваних курортах інтерактивні цифрові карти показують, де ви є і де вже були. Можна знайти друзів на горі та заздалегідь дізнатися про умови завдяки звітам. Застосунок працює на iPhone, Android та Apple Watch; поїздками можна ділитися й переживати їх знову.', 'Slopes is built by a small team with a big passion for skiing and snowboarding. The app records your days on the mountain and provides detailed stats: vertical, top and average speed, distance, lift versus run time, calories, elevation and heart rate, plus season and lifetime totals. Official trail maps for thousands of resorts are always at hand, and at 2,000+ supported resorts interactive digital maps show where you are and where you have been. You can locate friends on the mountain and check condition reports ahead of time. The app runs on iPhone, Android and Apple Watch, and you can relive and share your days.', 'Детальна статистика спусків
Карти трас тисяч курортів
Інтерактивні карти на 2000+ курортах
Пошук друзів на горі
Звіти про умови
Apple Watch', 'Detailed run statistics
Trail maps for thousands of resorts
Interactive maps at 2,000+ resorts
Find friends on the mountain
Condition reports
Apple Watch', 'Лижники й сноубордисти, які хочуть статистику та зручні карти курортів.', 'Skiers and snowboarders who want stats and convenient resort maps.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
