INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Slopes is built by a small team with a big passion for skiing and snowboarding. The app records your days on the mountain and provides detailed stats: vertical, top and average speed, distance, lift versus run time, calories, elevation and heart rate, plus season and lifetime totals. Official trail maps for thousands of resorts are always at hand, and at 2,000+ supported resorts interactive digital maps show where you are and where you have been. You can locate friends on the mountain and check condition reports ahead of time. The app runs on iPhone, Android and Apple Watch, and you can relive and share your days.', 'manual' FROM DUAL WHERE @new = 1;
