-- Smashrun — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'smashrun.com' OR LOWER(`name`) = LOWER('Smashrun'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Smashrun', NULL, 'https://smashrun.com', NULL, NULL, 'Smashrun — безплатний сервіс аналітики для бігунів: візуалізує ваші пробіжки, зберігає й будує графіки за роки історії, нараховує значки й медалі та порівнює прогрес із друзями; працює з популярними застосунками й годинниками.', 'Smashrun is a free analytics service for runners: it visualizes your runs, stores and graphs years of history, awards badges and medals and compares progress with friends; it works with popular running apps and watches.', 'Smashrun допомагає зрозуміти свій біг через візуалізацію даних. Сервіс не замінює ваш улюблений біговий застосунок чи годинник, а працює разом із ними: підтягує пробіжки й перетворює їх на зрозумілу аналітику. Можна зберігати й переглядати історію за багато років, будувати графіки, бачити, як змінюються темп, обсяги й регулярність. Значки й медалі додають мотивації вийти на пробіжку навіть тоді, коли сил ніби немає, а порівняння з друзями підігріває здоровий дух змагання. Базові можливості безплатні, а розширена аналітика доступна в Pro-версії. Користувачі відзначають, що бачити свій прогрес — сильний стимул бігати регулярно.', 'Smashrun helps you understand your running by visualizing your data. It does not replace your favorite running app or watch but works alongside it: it pulls in your runs and turns them into clear analytics. You can store and browse years of history, build graphs and see how pace, volume and consistency change. Badges and medals add motivation to get out even on days you don''t feel up to it, and comparing yourself with friends adds friendly competition. Core features are free, and deeper analytics are available in the Pro version. Users note that seeing their progress is the best incentive to run regularly.', 'Візуалізація даних про пробіжки
Історія й графіки за роки
Значки й медалі
Порівняння з друзями
Інтеграція з застосунками й годинниками
Pro-функції для глибшої аналітики', 'Run data visualization
Years of history and graphs
Badges and medals
Comparison with friends
Works with apps and watches
Pro features for deeper analytics', 'Бігуни, які люблять цифри й хочуть бачити свій прогрес за тривалий час.', 'Runners who love numbers and want to see their progress over the long term.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
