SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'stepsetgo.com' OR LOWER(`name`) = LOWER('StepSetGo'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'StepSetGo', NULL, 'https://stepsetgo.com', NULL, NULL, 'StepSetGo — індійський застосунок «Крокуй, заробляй, обмінюй»: перетворює щоденні кроки на винагороди, мотивує рухатися регулярно й робить фітнес веселим і вигідним; є програми для брендів і компаній.', 'StepSetGo is an Indian Step-Earn-Redeem app that turns your daily steps into rewards, motivates you to move regularly and makes fitness fun and rewarding; there are programs for brands and companies.', 'StepSetGo вирішує знайому проблему: людина обіцяє собі почати займатися з нового року, але вже в лютому мотивація зникає, бо шлях до результату здається довгим і нудним. Застосунок робить фітнес веселим і вигідним — достатньо просто ходити. Ваші кроки перетворюються на внутрішню валюту, яку можна обміняти на винагороди, тож кожен крок має значення. StepSetGo мотивує, залучає, підштовхує рухатися й винагороджує за активність, допомагаючи не кидати через кілька тижнів. Окремі програми розраховані на бренди, які хочуть взаємодіяти з активною аудиторією, і на компанії, що впроваджують корпоративні велнес-ініціативи.', 'StepSetGo tackles a familiar problem: people promise themselves to get fit in the new year, but by February their motivation has faded because the road to results feels long and boring. The app makes fitness fun and rewarding — all you have to do is walk. Your steps turn into an in-app currency you can redeem for rewards, so every step counts. StepSetGo motivates, engages, pushes you to move and rewards activity, helping you stick with it beyond the first few weeks. Separate programs serve brands that want to engage an active audience and companies running corporate wellness initiatives.', 'Нарахування винагород за кроки
Обмін на товари й послуги
Мотивація рухатися щодня
Програми для брендів
Корпоративні велнес-програми', 'Rewards for steps
Redeem for products and services
Daily motivation to move
Programs for brands
Corporate wellness programs', 'Люди, яким бракує мотивації рухатися, а також бренди й компанії.', 'People who lack motivation to move, as well as brands and companies.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
