SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'strengthlog.com' OR LOWER(`name`) = LOWER('StrengthLog'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'StrengthLog', NULL, 'https://www.strengthlog.com', NULL, NULL, 'StrengthLog — безплатний трекер тренувань і журнал залу для iOS та Android: записуйте вправи й підходи, ставте цілі й дивіться прогрес; на сайті — програми, нормативи сили та довідник вправ за групами м''язів.', 'StrengthLog is a free workout tracker and gym log for iOS and Android: log exercises and sets, set goals and see progress; the site adds programs, strength standards and an exercise directory by muscle group.', 'StrengthLog — простий застосунок-трекер для силових тренувань, доступний безплатно на iOS та Android. Він дозволяє записувати вправи, підходи й ваги, ставити цілі та бачити, як змінюються результати з часом. Окрім застосунку, проєкт має великий освітній розділ: програми для присідань, жиму лежачи й станової тяги, нормативи сили для оцінки свого рівня, порівняння варіантів вправ і альтернатив, поради щодо техніки. Довідник вправ упорядковано за групами м''язів — прес, спина, біцепс, груди, сідниці, ноги та інші — з добірками ефективних вправ для кожної. Це зручна точка входу для тих, хто хоче тренуватися системно.', 'StrengthLog is a simple strength training tracker available for free on iOS and Android. It lets you log exercises, sets and weights, set goals and see how your results change over time. Beyond the app, the project has a large learning section: squat, bench press and deadlift programs, strength standards to assess your level, comparisons of exercise variations and alternatives, and technique tips. The exercise directory is organized by muscle group — abs, back, biceps, chest, glutes, legs and more — 