INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'StrengthLog is a simple strength training tracker available for free on iOS and Android. It lets you log exercises, sets and weights, set goals and see how your results change over time. Beyond the app, the project has a large learning section: squat, bench press and deadlift programs, strength standards to assess your level, comparisons of exercise variations and alternatives, and technique tips. The exercise directory is organized by muscle group — abs, back, biceps, chest, glutes, legs and more — with picks of effective exercises for each. It is a convenient entry point for anyone who wants to train systematically.', 'manual' FROM DUAL WHERE @new = 1;
