-- STRETCHIT — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'stretchitapp.com' OR LOWER(`name`) = LOWER('STRETCHIT'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'STRETCHIT', NULL, 'https://www.stretchitapp.com', NULL, NULL, 'STRETCHIT — застосунок розтяжки й мобільності з відеокласами від експертів: шпагати, прогини, мобільність усього тіла, заняття від новачка до складного рівня, персональний розклад і змагання; 7 днів безплатно.', 'STRETCHIT is a stretching and mobility app with expert-led video classes: splits, backbends and full-body mobility, sessions from beginner to challenging, personalized scheduling and competitions; 7 days free.', 'STRETCHIT допомагає зробити розтяжку звичкою. Відеокласи від експертів охоплюють рівні від абсолютного новачка до дуже складного, а нові тренування виходять щотижня. Застосунок допоможе освоїти шпагат і глибокі прогини або просто почуватися й спати краще. Персональні рекомендації та розклад тренувань допомагають регулярно займатися й розкривати свій потенціал руху. Можна приєднуватися до глобальних змагань або створювати власні з друзями чи колегами та стежити за прогресом у таблиці лідерів. STRETCHIT доступний на iOS, Android і у вебі, пропонує безплатний клас без картки та 7-денний пробний період; підписка — від 15 USD на місяць. Є також рішення для бізнесу.', 'STRETCHIT helps make stretching a habit. Expert-led video classes range from absolute beginner to very challenging, and new workouts are released weekly. The app can help you master the splits and deep backbends or simply feel and sleep better. Personal recommendations and scheduling help you stretch regularly and reach your movement potential. You can join global competitions or create your own with friends or colleagues and track progress on a leaderboard. STRETCHIT is available on iOS, Android and the web, offers a free class with no card and a 7-day trial; subscriptions start at 15 USD per month. There is also a business solution.', 'Відеокласи розтяжки від експертів
Шпагати, прогини, мобільність
Рівні від новачка до складного
Персональний розклад
Змагання з друзями
Нові тренування щотижня', 'Expert-led stretching video classes
Splits, backbends and mobility
Levels from beginner to challenging
Personalized scheduling
Competitions with friends
New workouts weekly', 'Ті, хто хоче покращити гнучкість, сісти на шпагат або зняти скутість тіла.', 'People who want to improve flexibility, achieve the splits or relieve body tightness.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
