-- Strongr Fastr — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'strongrfastr.com' OR LOWER(`name`) = LOWER('Strongr Fastr'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Strongr Fastr', NULL, 'https://www.strongrfastr.com', NULL, NULL, 'Strongr Fastr — AI-тренер, дієтолог і планувальник харчування: 10-хвилинний аналіз тіла, план меню з простих рецептів під ваші калорії й макроси, списки покупок і тренування для дому чи залу, що адаптуються до прогресу.', 'Strongr Fastr is an AI trainer, diet coach and meal planner: a 10-minute body analysis, a menu of simple recipes that hits your calories and macros, grocery lists and home or gym workouts that adapt to progress.', 'Strongr Fastr за кілька кліків складає повний план харчування й тренувань під ваші цілі, розклад, смаки та вподобання. Усе починається з 10-хвилинного AI-аналізу тіла, де ви вказуєте стать і мету: схуднути, підтримувати форму чи набрати м''язи. AI-планувальник складає меню на тиждень із бази простих і реалістичних рецептів, щоб влучати в калорії та макроси, і формує невеликі списки покупок. Якщо регулярно вносити дані, AI підлаштовується під ваші точні потреби. Тренування для дому чи залу підбираються під мету, графік і обладнання та адаптуються до прогресу. Є плани кето, палео, вегетаріанські, веганські, конструктор тренувань і візуалізатор тіла.', 'Strongr Fastr builds a complete meal and training plan in a few clicks, customized to your goals, schedule, tastes and preferences. It starts with a 10-minute AI body analysis where you set your sex and goal: lose fat, maintain or build muscle. The AI meal planner builds a weekly menu from a database of simple, realistic recipes to hit your calories and macros and creates small grocery lists. If you log consistently, the AI optimizes to your exact needs. Home or gym workouts are matched to your goal, schedule and equipment and adapt to your progress. There are keto, paleo, vegetarian and vegan plans, a workout builder and a body visualizer.', 'AI-аналіз тіла за 10 хвилин
Тижневе меню під калорії й макроси
Списки покупок
Тренування, що адаптуються до прогресу
Кето, палео, веган та інші плани
Візуалізатор тіла', '10-minute AI body analysis
Weekly menu for calories and macros
Grocery lists
Workouts that adapt to progress
Keto, paleo, vegan and other plans
Body visualizer', 'Люди, які хочуть поєднати план харчування й тренувань для схуднення чи набору маси.', 'People who want to combine a meal plan and workouts to lose fat or build muscle.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
