-- Stōkt — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'getstokt.com' OR LOWER(`name`) = LOWER('Stōkt'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Stōkt', NULL, 'https://www.getstokt.com', NULL, NULL, 'Stōkt — застосунок для домашніх і клубних стін для лазіння: фото стіни автоматично розпізнає зачепи, після чого можна створювати траси, вести списки, бенчмарки, змагання й відстежувати прогрес. Для залів і дому.', 'Stōkt is an app for home and gym climbing walls: a photo of the wall automatically maps the holds, then you can set climbs, keep lists and benchmarks, run competitions and track progress.', 'Stōkt вирішує головну проблему спрей-волів і домашніх стін — як зручно створювати й зберігати траси. Достатньо сфотографувати стіну: застосунок автоматично розпізнає зачепи, створює вашу стіну, і за кілька хвилин можна ставити траси. Скелелази можуть організовувати проблеми в списки, користуватися бенчмарк-списками, бачити свіжі траси, враховувати змінний кут стіни й проводити змагання. Для комерційних залів є підписки, які дають спільноті зручний спосіб ставити, знаходити й відстежувати траси. Для власників домашніх стін — окремі плани з можливістю оновлення, а для складних стін команда може самостійно підготувати й завантажити стіну.', 'Stōkt solves the main problem of spray walls and home walls — how to set and store climbs conveniently. Just take a photo of the wall: the app automatically maps the holds, creates your wall, and within minutes you can set climbs. Climbers can organize problems into lists, use benchmark lists, see fresh climbs, account for an adjustable wall angle and run competitions. Commercial gyms get subscriptions that give their community a better way to set, discover and track climbs. Home wall owners have separate plans with upgrades, and for complex walls the team can prepare, map and upload the wall for you.', 'Автоматичне розпізнавання зачепів за фото
Створення трас за хвилини
Списки, бенчмарки та змагання
Підтримка змінного кута стіни
Плани для залів і домашніх стін', 'Automatic hold mapping from a photo
Set climbs in minutes
Lists, benchmarks and competitions
Adjustable wall angle support
Plans for gyms and home walls', 'Скелелази з домашніми стінами та скеледроми й зали для лазіння.', 'Climbers with home walls and climbing gyms.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
