INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Stōkt solves the main problem of spray walls and home walls — how to set and store climbs conveniently. Just take a photo of the wall: the app automatically maps the holds, creates your wall, and within minutes you can set climbs. Climbers can organize problems into lists, use benchmark lists, see fresh climbs, account for an adjustable wall angle and run competitions. Commercial gyms get subscriptions that give their community a better way to set, discover and track climbs. Home wall owners have separate plans with upgrades, and for complex walls the team can prepare, map and upload the wall for you.', 'manual' FROM DUAL WHERE @new = 1;
