-- Sweatcoin — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sweatco.in' OR LOWER(`name`) = LOWER('Sweatcoin'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Sweatcoin', NULL, 'https://sweatco.in', NULL, NULL, 'Sweatcoin — застосунок, що конвертує ваші кроки у віртуальну валюту sweatcoins, яку можна витратити на товари й послуги; персональна статистика руху та здоров''я, а дослідження показують, що користувачі ходять на 20% більше.', 'Sweatcoin converts your steps into a virtual currency, sweatcoins, that you can spend on products and services; personal movement and health stats, and research shows users walk 20% more.', 'Sweatcoin перетворює ходьбу на винагороди: кожен крок рахується й конвертується у віртуальну валюту sweatcoins, яку можна витратити на товари, послуги та ексклюзивні пропозиції. Застосунок також показує персональну статистику руху та здоров''я, щоб ви бачили свій прогрес. За дослідженнями, на які посилається компанія, користувачі Sweatcoin ходять на 20% більше навіть через шість місяців, тобто застосунок допомагає сформувати стійку звичку. Серед партнерів — NHS, Apple, Amazon і сотні компаній. Бренди можуть стати партнерами, а інфлюенсери — долучитися до програми. Завантаження безплатне. Застосунок працює у фоновому режимі й не потребує додаткових пристроїв.', 'Sweatcoin turns walking into rewards: every step is counted and converted into a virtual currency, sweatcoins, which you can spend on products, services and exclusive offers. The app also shows personal movement and health stats so you can see your progress. According to research the company cites, Sweatcoin users walk 20% more even six months later, meaning the app helps build a lasting habit. Partners include the NHS, Apple, Amazon and hundreds of businesses. Brands can partner and influencers can join the program. The download is free. The app runs in the background and needs no extra devices.', 'Конвертація кроків у sweatcoins
