INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Sweatcoin turns walking into rewards: every step is counted and converted into a virtual currency, sweatcoins, which you can spend on products, services and exclusive offers. The app also shows personal movement and health stats so you can see your progress. According to research the company cites, Sweatcoin users walk 20% more even six months later, meaning the app helps build a lasting habit. Partners include the NHS, Apple, Amazon and hundreds of businesses. Brands can partner and influencers can join the program. The download is free. The app runs in the background and needs no extra devices.', 'manual' FROM DUAL WHERE @new = 1;
