-- Swim Smooth — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'swimsmooth.com' OR LOWER(`name`) = LOWER('Swim Smooth'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Swim Smooth', NULL, 'https://swimsmooth.com', NULL, NULL, 'Swim Smooth — система навчання кролю, що тренує плавця, а не гребок: місцеві групи з сертифікованими тренерами, відеоаналіз над і під водою, табори, клініки, онлайн-асистент GURU і платформа SwimCoachHQ.', 'Swim Smooth is a freestyle coaching system that coaches the swimmer, not the stroke: local squads with certified coaches, above- and below-water video analysis, camps, clinics, the GURU online assistant and SwimCoachHQ.', 'Swim Smooth — методика навчання вільного стилю з принципом «тренуйте плавця, а не гребок», що з 2004 року застосовується в багатьох країнах. Незалежно від рівня й мотивації можна приєднатися до групи Swim Smooth, познайомитися з місцевим сертифікованим тренером і пливти разом із дружньою спільнотою. Групи пропонують заняття з тренером щотижня у вашому місті. Індивідуальний відеоаналіз над і під водою з сертифікованим тренером допомагає побачити свій гребок і змінити його надовго. Також доступні табори й поїздки, клініки, онлайн-асистент GURU з планами тренувань і окрема платформа SwimCoachHQ для тренерів. На сайті є пошук тренера, опис методу та блог.', 'Swim Smooth is a freestyle coaching method built on the principle of coaching the swimmer, not the stroke, used in many countries since 2004. Whatever your level and motivation, you can join a Swim Smooth squad, meet your local certified coach and swim with a friendly community. Squads offer coached sessions every week in your city. One-to-one video analysis above and below the water with a certified coach helps you see your stroke and change it for good. There are also camps and experiences, clinics, the GURU online assistant with training plans and the SwimCoachHQ platform for coaches. The site has a coach finder, the method and a blog.', 'Методика навчання кролю
Групи з сертифікованими тренерами
Відеоаналіз над і під водою
