SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'swim.com' OR LOWER(`name`) = LOWER('Swim.com'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Swim.com', NULL, 'https://www.swim.com', NULL, NULL, 'Swim.com — платформа тренувань для плавців і офіційна платформа United States Masters Swimming: журнал запливів, відстеження прогресу, тренування, пошук басейнів і клубів, змагання з друзями та підключення пристроїв.', 'Swim.com is a swim workout and training platform and the official platform of United States Masters Swimming: swim logging, progress tracking, workouts, pool and club finder, competing with friends and device connections.', 'Swim.com — платформа для запису тренувань, відстеження прогресу й змагань із друзями, яка є офіційною платформою тренувань United States Masters Swimming. Працює просто: підключіть свій пристрій для відстеження плавання, знайдіть тренування й пливіть, а потім спілкуйтеся, змагайтеся та досягайте цілей. Користувачі відзначають, зокрема, автоматичну паузу під час відпочинку. На сайті є розділи з функціями, пошуком басейнів і клубів, а також блог. Реєстрація безплатна. Платформа підходить і плавцям-аматорам, і учасникам ветеранських змагань, і тріатлоністам, які хочуть вести журнал запливів. Дані з різних пристроїв збираються в одному профілі.', 'Swim.com is a platform for logging workouts, tracking progress and competing with friends, and it is the official workout and training platform of United States Masters Swimming. It works simply: connect your swim tracking device, discover workouts and swim, then connect, compete and conquer your goals. Users highlight features such as automatic pause while resting. The site has sections on features, a pool and club finder and a blog. Sign-up is free. It suits recreational swimmers, Masters competitors and triathletes who want a swim log. Data from different devices come together in one profile.', 'Журнал запливів
Відстеження прогресу
Бібліотека тренувань
