Tracker connections', 'Плавці-аматори, учасники Masters і тріатлоністи.', 'Recreational swimmers, Masters swimmers and triathletes.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
