-- Sworkit — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sworkit.com' OR LOWER(`name`) = LOWER('Sworkit'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Sworkit', NULL, 'https://sworkit.com', NULL, NULL, 'Sworkit Health — цифрова платформа добробуту для компаній, страхових планів і шкіл: фітнес, мобільність, майндфулнес, харчування, челенджі та програма Sworkit Move для профілактики болю в суглобах і м''язах.', 'Sworkit Health is a digital wellbeing platform for employers, health plans and schools: fitness, mobility, mindfulness, nutrition, challenges and the Sworkit Move program for preventing joint and muscle pain.', 'Sworkit починався як застосунок домашніх тренувань, а тепер це платформа Sworkit Health для корпоративного добробуту. Роботодавці, страхові плани й школи дають своїм людям доступ до бібліотеки занять: силові, кардіо, йога, розтяжка, майндфулнес, відновлення й харчування. Організації можуть запускати глобальні або командні челенджі з винагородами, календар заходів і вебінари, підключати інтеграції. Нова програма Sworkit Move — керований курс догляду за суглобами й м''язами, який допомагає запобігати болю та підтримує залученість і після епізоду лікування. Індивідуальні користувачі також можуть підписатися, а в США оплата можлива з HSA/FSA.', 'Sworkit started as a home-workout app and is now Sworkit Health, a corporate wellbeing platform. Employers, health plans and schools give their people access to a library of strength, cardio, yoga, stretching, mindfulness, recovery and nutrition content. Organizations can run global or team challenges with incentives, a wellbeing calendar and webinars, and connect integrations. The new Sworkit Move is a guided musculoskeletal program that helps prevent joint and muscle pain and keeps members engaged beyond the episode of care. Individuals can subscribe too, and in the US payment with HSA/FSA is possible.', 'Бібліотека фітнесу, йоги, розтяжки й майндфулнес
Челенджі та стимули для команд
Програма Sworkit Move для суглобів і м''язів
Доступ до тренерів і вебінари
Інтеграції для роботодавців і страхових планів', 'Library of fitness, yoga, stretching and mindfulness
Team challenges and incentives
Sworkit Move program for joints and muscles
Trainer access and webinars
Integrations for employers and health plans', 'HR-команди, страхові плани та школи, які впроваджують програми здоров''я, а також окремі користувачі.', 'HR teams, health plans and schools running wellbeing programs, as well as individual users.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
