INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Tempo', NULL, 'https://tempo.fit', NULL, NULL, 'Tempo — домашній спортзал з AI: адаптивні плани силових тренувань, підказки в реальному часі завдяки кольоровим розумним вагам, 3D-скани складу тіла та віртуальні персональні тренування з розкладом і нагадуваннями.', 'Tempo is an AI-powered home gym: adaptive strength plans, real-time guidance thanks to color-coded smart weights, 3D body composition scans and scheduled virtual personal training.', 'Tempo — членство в домашньому спортзалі, побудоване навколо силових тренувань. Плани підлаштовуються під ваш організм і біометрію, а кольорові розумні ваги дозволяють системі відстежувати виконання в реальному часі й давати підказки. Tempo фіксує результати й коригує план, щоб прогрес був постійним. Є тренування для вагітних, для відновлення після травми та без ударного навантаження. Справжній результат вимірюється складом тіла: 3D-скани показують зміни жиру, м''язової маси та інших параметрів. Віртуальні персональні тренування можна планувати в розкладі з нагадуваннями й переносити в останній момент. Значки й досягнення підтримують мотивацію, а обладнання для дому додається від 20 USD на місяць.', 'Tempo is a home gym membership built around strength training. Plans adapt to your body and biometrics, while color-coded smart weights let the system track your form in real time and give guidance. Tempo logs your performance and adjusts the plan to keep you progressing. There are workouts for pregnancy, injury recovery and low-impact training. Body composition is treated as the true result: 3D scans show changes in body fat, muscle mass and more. Virtual personal training sessions can be scheduled with reminders and moved at the last minute. Badges and milestones keep you motivated, and home gym equipment starts at 20 USD per month.', 'Адаптивні плани силових тренувань
Розумні ваги з відстеженням у реальному часі
3D-скани складу тіла
Віртуальні персональні тренування за розкладом
Тренування для вагітних і після травм
Значки й досягнення', 'Adaptive strength training plans
Smart weights with real-time tracking
3D body composition scans
Scheduled virtual personal training
Workouts for pregnancy and injury recovery
Badges and milestones', 'Люди, які хочуть займатися силовими вдома з підказками в реальному часі й вимірюваним прогресом.', 'People who want to strength train at home with real-time guidance and measurable progress.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
