SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'thereadystate.com' OR LOWER(`name`) = LOWER('The Ready State'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'The Ready State', NULL, 'https://thereadystate.com', NULL, NULL, 'The Ready State — науково обґрунтовані тренування мобільності, силові програми й інструменти способу життя від д-ра Келлі Старретта: від щоденних 10-хвилинних комплексів до 12-тижневих програм і курсів для профі.', 'The Ready State offers science-backed mobility training, strength programming and lifestyle tools from Dr. Kelly Starrett: from daily 10-minute flows to 12-week programs and courses for pros.', 'The Ready State допомагає «підготувати тіло до майбутнього» — рухатися й почуватися краще. Програми створив д-р Келлі Старретт, фахівець із руху та мобільності й автор бестселерів. Платформа поєднує тренування мобільності, силові програми та інструменти для способу життя на основі понад 25 років досліджень. На вибір — щоденні 10-хвилинні комплекси мобільності, повноцінні 12-тижневі силові програми й поглиблені професійні курси для тих, хто працює з іншими. У бібліотеці понад 1500 відео з інструкціями, займатися можна будь-де й будь-коли. Також є подкаст, щотижнева розсилка, магазин і 7-денний безплатний пробний період.', 'The Ready State helps you future-proof your body — move better and feel better. Programs are created by Dr. Kelly Starrett, a movement and mobility expert and best-selling author. The platform combines mobility training, strength programming and lifestyle tools based on 25+ years of research. You can choose daily 10-minute mobility flows, full 12-week strength programs or in-depth pro courses for those who work with others. The library holds 1,500+ guided videos, and you can train anytime, anywhere. There is also a podcast, a weekly newsletter, a shop and a 7-day free trial.', 'Щоденні 10-хвилинні комплекси мобільності
12-тижневі силові програми
Курси для професіоналів
1500+ відео з інструкціями
Подкаст і розсилка
7 днів безплатно', 'Daily 10-minute mobility flows
12-week strength programs
Courses for professionals
1,500+ guided videos
Podcast and newsletter
7 days free', 'Спортсмени, люди з болем і скутістю, а також тренери й фахівці з руху.', 'Athletes, people with pain and stiffness, and coaches and movement professionals.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
