SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'thetopo.com' OR LOWER(`name`) = LOWER('The Topo'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'The Topo', NULL, 'https://thetopo.com', NULL, NULL, 'The Topo (раніше 27 Crags) — застосунок і сайт із топо для скелелазіння: понад 210 тис. маршрутів і 150 тис. боулдерингових проблем у тисячах преміальних секторів, верифіковані топо й скелелазна спільнота.', 'The Topo (formerly 27 Crags) is a climbing topo app and site: 210,000+ routes and 150,000+ boulder problems in thousands of premium crags, verified topos and a climbing community.', 'The Topo — нова назва застосунку 27 Crags: той самий застосунок, ті самі топо й та сама спільнота. Тепер назва краще відображає суть — тисячі верифікованих топо від скелелазів з усього світу. Сервіс допомагає знаходити скельні маршрути та боулдерингові проблеми для будь-якого рівня: у базі понад 210 тисяч маршрутів і понад 150 тисяч проблем у тисячах преміальних секторів. Можна досліджувати напрямки для спортивного скелелазіння й боулдерингу, переглядати фото, опис підходів і схеми маршрутів, щоб спланувати поїздку на скелі. Спільнота постійно оновлює та доповнює дані. Це зручно для планування поїздок на нові скелі.', 'The Topo is the new name of 27 Crags: same app, same topos, same community. The name now reflects what it really is — thousands of verified topos from climbers worldwide. The service helps you find rock climbing routes and boulder problems for all levels: the database holds 210,000+ routes and 150,000+ problems in thousands of premium crags. You can explore sport climbing and bouldering destinations and view photos, approach descriptions and route diagrams to plan a climbing trip. The community keeps updating and adding data. It is handy for planning trips to new crags.', 'Верифіковані топо
210 тис.+ маршрутів
150 тис.+ боулдерингових проблем
Тисячі преміальних секторів
Напрямки для спорту й боулдерингу', 'Verified topos
210,000+ routes
150,000+ boulder problems
Thousands of premium crags
Sport and bouldering destinations', 'Скелелази й боулдеристи, які планують поїздки на скелі.', 'Climbers and boulderers planning outdoor trips.', 'mobile,web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
