INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'TheGrint', NULL, 'https://thegrint.com', NULL, NULL, 'TheGrint — безплатний застосунок для гольфу: офіційний гандикап USGA, підрахунок очок, понад 18 модулів статистики з порівнянням із цілями, GPS-карти на 40 000+ полях та ігри з друзями. Базова версія безплатна.', 'TheGrint is a free golf app: an official USGA Handicap, scorekeeping, 18+ stats modules compared with targets, GPS maps on 40,000+ courses and golf games with friends.', 'TheGrint — застосунок, яким користуються мільйони гольфістів. Він дозволяє вести рахунок, отримувати GPS-відстані на понад 40 000 полях і грати в гольф-ігри з друзями. Понад 18 детальних модулів статистики показують, як ви граєте в усіх аспектах, порівнюють результати з цілями й еталонами для вашого рівня та демонструють прогрес із часом. У США TheGrint — ліцензований партнер USGA з даних гандикапу: після раунду результат завантажується одним дотиком, і ви керуєте офіційним гандикапом. Також є тур TheGrint, розділ The Range, магазин і супутні продукти Swingman та Goldfinch. Застосунок підходить гравцям будь-якого рівня й допомагає перетворити кожен раунд на дані для покращення гри.', 'TheGrint is used by millions of golfers. It lets you keep score, get GPS distances on 40,000+ courses and play golf games with friends. More than 18 detailed stats modules show your performance across every aspect of the game, compare it with targets and benchmarks for your skill level and show improvement over time. In the US, TheGrint is a licensed USGA handicap data affiliate: one tap at the end of a round uploads your score, and you manage an official handicap. There is also TheGrint Tour, The Range section, a shop and companion products Swingman and Goldfinch. The app suits golfers of any level and turns every round into data for improvement.', 'Офіційний гандикап USGA
Підрахунок очок
18+ модулів статистики
