SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'topcourt.com' OR LOWER(`name`) = LOWER('TopCourt'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'TopCourt', NULL, 'https://www.topcourt.com', NULL, NULL, 'TopCourt — стрімінгова платформа навчання тенісу від видатних гравців і тренерів: 7 типів класів (техніка, вправи, стратегія, фізпідготовка, ментальна сила), підказки TopTips і понад 20 нових коротких уроків щомісяця.', 'TopCourt is a tennis learning streaming platform from legendary players and coaches: 7 class types (technique, drills, strategy, fitness, mental strength), TopTips and 20+ new short lessons every month.', 'TopCourt — перший стрімінговий сервіс навчання, створений провідними гравцями, тренерами й іконами спорту, і офіційна платформа електронного навчання. Тут можна вчитися в тих, хто змінив гру, і розкривати свій потенціал на корті й поза ним будь-коли й будь-де. Класи поділено на сім типів: техніка, вправи, стратегія, фізична підготовка, ментальна сила та інші. Короткі підказки TopTips допомагають отримати моменти прозріння, а щомісяця виходять понад 20 нових уроків тривалістю від 2 до 15 хвилин. Сервіс розрахований на гравців будь-якого рівня — від новачків до досвідчених, — а також підходить тренерам, які шукають нові ідеї для занять.', 'TopCourt is the first streaming learning service powered by top players, coaches and sports icons, and an official e-learning platform. You can learn from those who changed the game and reach your potential on and off the court anytime, anywhere. Classes come in seven types: technique, drills, strategy, fitness, mental strength and more. Short TopTips lead to aha moments, and 20+ new classes of 2 to 15 minutes arrive every month. The service suits players of every level — from beginners to experienced — and coaches looking for new session ideas.', 'Уроки від провідних гравців і тренерів
7 типів класів
Техніка, стратегія, фізпідготовка
Ментальна сила
Підказки TopTips
20+ нових уроків щомісяця', 'Lessons from top players and coaches
7 class types
Technique, strategy, fitness
Mental strength
TopTips
20+ new lessons monthly', 'Тенісисти будь-якого рівня й тренери.', 'Tennis players of any level and coaches.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
