SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'trainasone.com' OR LOWER(`name`) = LOWER('TrainAsONE'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'TrainAsONE', NULL, 'https://www.trainasone.com', NULL, NULL, 'TrainAsONE — AI-бігунський застосунок і адаптивний тренер: план перебудовується після кожної пробіжки з урахуванням вашої фізіології, мінімізує зайві кілометри й перетренованість; Android, Garmin, iOS і веб.', 'TrainAsONE is an AI running app and adaptive coach: the plan rebuilds after every run based on your physiology, minimizes junk miles and overtraining; Android, Garmin, iOS and web.', 'TrainAsONE відмовляється від статичних шаблонів: AI будує персональний адаптивний план саме під вашу фізіологію та цілі. Модель навчена на понад 100 мільйонах кілометрів реальних пробіжок, тож план перебудовується після кожного тренування, мінімізує «порожні» кілометри, запобігає перетренованості, знає, коли краще відпочити, й підлаштовується під ваше життя. Підтримується тренування за потужністю бігу. Застосунок імпортує активності з Garmin, Strava та інших сервісів і працює на Android, iOS, Garmin і у вебі. Безплатний тариф дає 7-денний детальний план і підготовку до однієї мети, а Premium додає фізіологічне моделювання, моніторинг утоми, пульсові тренування та поправки на рельєф і погоду.', 'TrainAsONE ignores static templates: its AI builds a personal adaptive plan specifically for your physiology and goals. The model is trained on over 100 million kilometres of real-world run data, so the plan rebuilds after every run, minimizes junk miles, prevents overtraining, knows when rest is best and adjusts to your life. Running power is supported. The app imports activities from Garmin, Strava and other services and works on Android, iOS, Garmin and the web. The free tier gives a 7-day detailed plan and training for a single goal, while Premium adds physiological modeling, fatigue monitoring, heart-rate workouts and elevation and weather adjustments.', 'План, що перебудовується після кожної пробіжки
Модель на 100 млн км реальних даних
Запобігання перетренованості
Тренування за потужністю бігу
Імпорт із Garmin і Strava
Поправки на погоду й рельєф у Premium', 'Plan that rebuilds after every run
Model trained on 100M km of real data
Overtraining prevention
Running power support
Import from Garmin and Strava
Weather and elevation adjustments in Premium', 'Бігуни, які готуються до забігів і хочуть адаптивний план замість шаблонного.', 'Runners preparing for races who want an adaptive plan instead of a template.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
