SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'trainerday.com' OR LOWER(`name`) = LOWER('TrainerDay'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'TrainerDay', NULL, 'https://trainerday.com', NULL, NULL, 'TrainerDay — структуровані велотренування в приміщенні й на вулиці: понад 40 000 тренувань від витривалості до VO2max, AI-тренер Coach Jack складає план під графік і цілі за правилами європейських тренерів.', 'TrainerDay offers structured cycling training indoors and outdoors: 40,000+ workouts from endurance to VO2max, and the Coach Jack AI builds a plan around your schedule and goals using European coaching rules.', 'TrainerDay — сервіс структурованих велотренувань для тих, хто хоче тренуватися за планом, а не навмання. У бібліотеці понад 40 000 тренувань — від легких заїздів на витривалість до важких інтервалів VO2max, sweet spot і порогових. Тренуватися можна в приміщенні на станку або на вулиці. Coach Jack за кілька хвилин будує тренувальний план: ви відповідаєте на кілька запитань, і він складає план під ваш графік, цілі та форму за правилами провідних європейських велотренерів, а щотижневі години, інтенсивність і фокус легко змінити. Багато можливостей безплатні без картки, а повна підписка коштує від 3,33 USD на місяць при оплаті за рік.', 'TrainerDay is a structured cycling training service for riders who want to follow a plan rather than guess. The library has 40,000+ workouts — from easy endurance rides to hard VO2max, sweet spot and threshold intervals. You can train indoors on a trainer or outdoors. Coach Jack builds a training plan in minutes: answer a few questions and it creates a plan around your schedule, goals and fitness based on the rules of top European cycling coaches, and weekly hours, intensity and focus are easy to tweak. Many features are free with no card, and the full subscription starts at 3.33 USD per month billed annually.', '40 000+ структурованих тренувань
Coach Jack — план за кілька хвилин
Тренування в приміщенні та на вулиці
Налаштування годин та інтенсивності
Календар подій
Багато безплатних функцій', '40,000+ structured workouts
Coach Jack builds a plan in minutes
Indoor and outdoor training
Adjustable hours and intensity
Event calendar
Lots of free features', 'Велосипедисти-аматори, які хочуть тренуватися структуровано за доступну ціну.', 'Recreational cyclists who want affordable structured training.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
