INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'TrainerDay is a structured cycling training service for riders who want to follow a plan rather than guess. The library has 40,000+ workouts — from easy endurance rides to hard VO2max, sweet spot and threshold intervals. You can train indoors on a trainer or outdoors. Coach Jack builds a training plan in minutes: answer a few questions and it creates a plan around your schedule, goals and fitness based on the rules of top European cycling coaches, and weekly hours, intensity and focus are easy to tweak. Many features are free with no card, and the full subscription starts at 3.33 USD per month billed annually.', 'manual' FROM DUAL WHERE @new = 1;
