-- trainwell — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'trainwell.net' OR LOWER(`name`) = LOWER('trainwell'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'trainwell', NULL, 'https://www.trainwell.net', NULL, NULL, 'trainwell (раніше CoPilot) — дистанційний персональний тренінг зі справжнім тренером: квіз підбирає тренера, той складає персональний план, дає зворотний зв''язок і тримає вас у тонусі; 14 днів безплатно.', 'trainwell (formerly CoPilot) is remote personal training with a real trainer: a quiz matches you with a coach who builds a personal plan, gives feedback and keeps you accountable; 14 days free.', 'trainwell, раніше відомий як CoPilot, пропонує персональні тренування з реальною людиною, а не з ботом. Після короткого квізу сервіс за кілька хвилин підбирає тренера, з яким можна поспілкуватися по відео. Тренер складає персональний план, проводить індивідуальний коучинг, дає зворотний зв''язок і тримає вас відповідальним за виконання, щоб тренування стали звичкою. Займатися можна вдома чи в залі, а бібліотека вправ допомагає з технікою. Компанія наголошує, що її підхід — справжня людська підтримка замість AI-ботів, які лише вдають турботу. Перші 14 днів безплатні, а на акціях діють знижки на персональний тренінг.', 'trainwell, formerly known as CoPilot, offers personal training with a real human rather than a bot. After a short quiz it matches you with a trainer within minutes, and you can video chat to get started. The trainer builds a personal plan, provides one-on-one coaching, gives feedback and holds you accountable so training becomes a habit. You can work out at home or in the gym, and the exercise library helps with technique. The company stresses that its approach is real human support instead of AI bots pretending to care. The first 14 days are free, and promotions offer discounts on personal training.', 'Підбір тренера за квізом
Персональний план від живого тренера
Відеозв''язок і зворотний зв''язок
Підтримка й відповідальність
Бібліотека вправ
14 днів безплатно', 'Trainer matching via a quiz
Personal plan from a human trainer
Video chat and feedback
Support and accountability
Exercise library
14 days free', 'Люди, яким важко тренуватися самостійно й потрібна підтримка живого тренера онлайн.', 'People who struggle to train on their own and need online support from a human trainer.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
