INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'trainwell, formerly known as CoPilot, offers personal training with a real human rather than a bot. After a short quiz it matches you with a trainer within minutes, and you can video chat to get started. The trainer builds a personal plan, provides one-on-one coaching, gives feedback and holds you accountable so training becomes a habit. You can work out at home or in the gym, and the exercise library helps with technique. The company stresses that its approach is real human support instead of AI bots pretending to care. The first 14 days are free, and promotions offer discounts on personal training.', 'manual' FROM DUAL WHERE @new = 1;
