-- V.O2 — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'vdoto2.com' OR LOWER(`name`) = LOWER('V.O2'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'V.O2', NULL, 'https://vdoto2.com', NULL, NULL, 'V.O2 — застосунок для бігунів і тренерів на основі методики VDOT: калькулятор рівня й тренувальних темпів за результатом забігу, адаптивний тренер V.O2 Adaptive Trainer (14 днів безплатно) і пошук тренера.', 'V.O2 is an app for runners and coaches based on the VDOT method: a calculator for your level and training paces from a race result, the V.O2 Adaptive Trainer (14 days free) and a coach finder.', 'V.O2 — біговий застосунок, побудований на науці VDOT. VDOT — це показник вашої поточної бігової форми: вводите нещодавній або орієнтовний результат забігу й отримуєте свій бал VDOT та тренувальні темпи. Для кожного темпу пояснено його призначення, а таблиця еквівалентних результатів допомагає ставити цілі й порівнювати виступи на різних дистанціях. Методика спрямована на те, щоб тренуватися правильно й розумно — отримувати максимум користі з меншими зусиллями. Для спортсменів є V.O2 Adaptive Trainer, який підлаштовує тренування (перші 14 днів безплатно), а тренери можуть вести своїх атлетів у застосунку. Також є розділ змагань і пошук тренера.', 'V.O2 is a running app built on the science of VDOT. VDOT is a measure of your current running ability: enter a recent or estimated race result to get your VDOT score and training paces. The purpose of each pace is explained, and equivalent race performances help set goals and compare results across distances. The method aims to help runners train correctly and intelligently, getting maximum benefit with less effort. Athletes can use the V.O2 Adaptive Trainer, which adjusts training (first 14 days free), and coaches can manage their athletes in the app. There are also races and a coach finder.', 'Калькулятор VDOT і тренувальних темпів
Еквівалентні результати на різних дистанціях
Адаптивний тренер V.O2
Інструменти для тренерів
Пошук тренера', 'VDOT and training pace calculator
Equivalent race performances
V.O2 Adaptive Trainer
Tools for coaches
Coach finder', 'Бігуни, які хочуть тренуватися за науковою методикою, і тренери з бігу.', 'Runners who want to train with a science-based method, and running coaches.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
