INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'V.O2 is a running app built on the science of VDOT. VDOT is a measure of your current running ability: enter a recent or estimated race result to get your VDOT score and training paces. The purpose of each pace is explained, and equivalent race performances help set goals and compare results across distances. The method aims to help runners train correctly and intelligently, getting maximum benefit with less effort. Athletes can use the V.O2 Adaptive Trainer, which adjusts training (first 14 days free), and coaches can manage their athletes in the app. There are also races and a coach finder.', 'manual' FROM DUAL WHERE @new = 1;
