-- Vert.run — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'vert.run' OR LOWER(`name`) = LOWER('Vert.run'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Vert.run', NULL, 'https://vert.run', NULL, NULL, 'Vert.run — застосунок тренувань для трейлу й ультрамарафонів із планами від справжніх тренерів, зокрема Франческо Пуппі: від першого 50 км до швидкої сотні миль, планувальник харчування, прогноз часу й підбір кросівок.', 'Vert.run is a trail and ultramarathon training app with plans backed by real coaches, including Francesco Puppi: from your first 50K to your fastest 100 miles, plus a nutrition planner, race time predictor and shoe suggester.', 'Vert.run допомагає готуватися до трейлових забігів і ультрамарафонів — від першої 50-кілометрівки до найшвидшої сотні миль — зі справжнім тренером у кишені. Плани створюють і підтримують живі тренери, серед яких Франческо Пуппі, а сервіс підбирає відповідний план і тренера. Окрім тренувань, доступні безплатні інструменти: планувальник харчування на забіг, прогноз часу на дистанції та підбір кросівок. Плани розраховані на бігунів будь-якого рівня й адаптуються під ваші цілі. На сайті є історії успіху, відповіді на запитання та журнал. Плани коштують від 9,90 USD на місяць, а перші 7 днів безплатні.', 'Vert.run helps you prepare for trail races and ultramarathons — from your first 50K to your fastest 100-mile race — with a real coach in your pocket. Plans are built and supported by human coaches, including Francesco Puppi, and the service matches you with the right plan and coach. Besides training there are free tools: a race nutrition planner, a race time predictor and a shoe suggester. Plans suit runners of all levels and adapt to your goals. The site has success stories, FAQs and a journal. Plans start at 9.90 USD per month, and the first 7 days are free.', 'Плани для трейлу й ультрамарафонів
Живі тренери
Підбір плану й тренера
Планувальник харчування на забіг
Прогноз часу й підбір кросівок
7 днів безплатно', 'Trail and ultra plans
Human coaches
Plan and coach matching
Race nutrition planner
Race time predictor and shoe suggester
7 days free', 'Трейлраннери та ультрамарафонці будь-якого рівня.', 'Trail runners and ultramarathoners of any level.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
