INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Wattbike', NULL, 'https://wattbike.com', NULL, NULL, 'Wattbike — розумні велотренажери Atom, Proton і Air-Pro з точністю вимірювання ±1% для дому та спорту, безплатний застосунок Wattbike Hub із тренуваннями й планами та сумісність із Zwift, ROUVY і Strava.', 'Wattbike makes Atom, Proton and Air-Pro smart indoor bikes with ±1% accuracy for home and performance, plus the free Wattbike Hub app with workouts and plans and compatibility with Zwift, ROUVY and Strava.', 'Wattbike виробляє розумні велотренажери для домашнього фітнесу, велотренувань і функціональної підготовки, якими користуються і професійні спортсмени, і звичайні люди. У лінійці — Atom, Proton, Air-Pro та AtomX, а також відновлені моделі й аксесуари; точність вимірювань — ±1%, і щомісячної підписки не потрібно. Підібрати модель допомагають порівняльний гід, консультант і шоурум. Безплатний застосунок Wattbike Hub містить керовані тренування й безплатні тренувальні плани, а Hub+ розширює можливості. Тренажери сумісні з Zwift, ROUVY, Strava та іншими застосунками. Є напрями для продуктивного велоспорту, HIIT, реабілітації та відновлення, а також комерційні рішення.', 'Wattbike builds smart indoor bikes for home fitness, cycling training and conditioning, trusted by elite athletes and everyday riders. The lineup includes Atom, Proton, Air-Pro and AtomX, plus reconditioned models and accessories; measurement accuracy is ±1% and no monthly subscription is required. A comparison guide, advisors and a showroom help you choose. The free Wattbike Hub app has guided workouts and free training plans, and Hub+ adds more. The bikes work with Zwift, ROUVY, Strava and other apps. There are tracks for performance cycling, HIIT, rehab and recovery, as well as commercial solutions.', 'Велотренажери Atom, Proton, Air-Pro
Точність вимірювань ±1%
