SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'wikiloc.com' OR LOWER(`name`) = LOWER('Wikiloc'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Wikiloc', NULL, 'https://www.wikiloc.com', NULL, NULL, 'Wikiloc — спільнота, де діляться понад 83 млн маршрутів для походів, MTB, шосе, бігу, трейлу, скітуру, каяків та інших активностей; планування маршрутів і застосунок для iPhone та Android. Є преміум-підписка.', 'Wikiloc is a community sharing 83M+ trails for hiking, MTB, road cycling, running, trail running, backcountry skiing, kayaking and more, with route planning and an app for iPhone and Android.', 'Wikiloc — місце, де можна знайти маршрути для активного відпочинку по всьому світу. Учасники спільноти поділилися більш ніж 83 мільйонами маршрутів і мільйонами фото. Маршрути охоплюють десятки активностей: гірський і шосейний велосипед, пішохідні походи, біг і трейлраннінг, велотуризм, альпінізм, скітур і бігові лижі, снігоступи, каяки й каное, верхову їзду, вітрильний спорт і навіть позашляхові поїздки. Можна завантажувати власні треки, планувати маршрути на сайті й орієнтуватися за ними в застосунку для iPhone та Android. Преміум-підписка відкриває розширені можливості навігації та планування.', 'Wikiloc is the place to find outdoor trails worldwide. Community members have shared over 83 million trails and millions of photos. Trails cover dozens of activities: mountain and road biking, hiking, running and trail running, bicycle touring, alpine climbing, backcountry and cross-country skiing, snowshoeing, kayaking and canoeing, horseback riding, sailing and even off-road driving. You can upload your own tracks, plan routes on the website and navigate them in the iPhone and Android app. A premium subscription unlocks advanced navigation and planning.', '83 млн+ маршрутів від спільноти
Десятки видів активностей
