SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'yogainternational.com' OR LOWER(`name`) = LOWER('Yoga International'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Yoga International', NULL, 'https://yogainternational.com', NULL, NULL, 'Yoga International — членство для практики йоги, медитації й дихальних вправ, вивчення аюрведи та філософії йоги, а також для отримання сертифікатів викладача: класи, курси, челенджі, фільми; 7 днів безплатно.', 'Yoga International is a membership for practicing yoga, meditation and breathwork, studying Ayurveda and yoga philosophy and earning yoga teaching certificates: classes, courses, challenges and films; 7 days free.', 'Yoga International позиціонує себе як єдине членство з йоги, яке вам потрібне. Платформа дозволяє практикувати йогу, медитацію та дихальні вправи, вивчати аюрведу й філософію йоги та отримувати сертифікати викладача. Бібліотека включає онлайн-практики для різних тіл і рівнів, керовані медитації, дихальні практики, документальні фільми, статті, курси й челенджі від багатьох викладачів. Можна створити власний щоденний ритуал. Окремо доступні преміальні навчальні програми, а частина контенту представлена іспанською мовою. Членство можна спробувати безплатно протягом 7 днів, після чого обрати тарифний план.', 'Yoga International presents itself as the only yoga membership you''ll ever need. The platform lets you practice yoga, meditation and breathwork, learn Ayurveda and yoga philosophy and earn yoga teaching certificates. The library includes online practices for every body and level, guided meditations, breathwork, documentaries, articles, courses and challenges from many teachers. You can create your own daily ritual. Premium trainings are available separately, and some content is in Spanish. The membership can be tried free for 7 days before choosing a plan.', 'Йога, медитація й дихальні практики
Аюрведа й філософія йоги
Сертифікати викладача
Курси й челенджі
Фільми й статті
7 днів безплатно', 'Yoga, meditation and breathwork
Ayurveda and yoga philosophy
Teaching certificates
Courses and challenges
Films and articles
7 days free', 'Практики йоги будь-якого рівня й майбутні викладачі.', 'Yoga practitioners of any level and aspiring teachers.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
