SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'yogastudioapp.com' OR LOWER(`name`) = LOWER('Yoga Studio'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Yoga Studio', NULL, 'https://yogastudioapp.com', NULL, NULL, 'Yoga Studio: Mind & Body — застосунок йоги з HD-відеозаняттями та зрозумілими коментарями викладачів для початківців і досвідчених, із бібліотекою поз і можливістю складати власні послідовності; 7 днів безплатно.', 'Yoga Studio: Mind & Body is a yoga app with HD video classes and clear teacher commentary for beginners and veterans, plus a pose library for building your own sequences; 7 days free.', 'Yoga Studio: Mind & Body прагне зробити йогу доступною кожному. Розробники поєднали технології, досвід викладачів і якісний контент, щоб застосунок підходив і тим, хто тільки починає займатися, і тим, хто хоче вивести практику на новий рівень. Усі заняття мають відео у високій якості та чіткі коментарі викладачів, які легко виконувати. Бібліотека поз дозволяє складати власні послідовності, а заняття можна проходити у своєму темпі. Видання на кшталт Wall Street Journal і Guardian відзначали зручну організацію застосунку та користь як для новачків, так і для досвідчених практиків. Перші 7 днів безплатні.', 'Yoga Studio: Mind & Body aims to make yoga accessible to all. The developers combined technology, teacher experience and quality content so the app suits both people just starting out and those taking their practice to a new level. Every class comes with full HD video and clear, easy-to-follow teacher commentary. A pose library lets you build your own routines, and you can practice at your own pace. Outlets such as the Wall Street Journal and the Guardian have praised its clear organization and usefulness for beginners and veterans alike. The first 7 days are free.', 'HD-відеозаняття з йоги
Зрозумілі коментарі викладачів
Бібліотека поз
Власні послідовності
Для новачків і досвідчених
7 днів безплатно', 'HD yoga video classes
Clear teacher commentary
Pose library
Custom routines
For beginners and veterans
7 days free', 'Люди, які хочуть займатися йогою вдома у своєму темпі.', 'People who want to practice yoga at home at their own pace.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
