INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Yogaia', NULL, 'https://yogaia.com', NULL, NULL, 'Yogaia — онлайн-тренування, йога, пілатес і майндфулнес наживо та на вимогу: понад 3000 занять, 50+ нових живих і записаних класів щотижня, персональний шлях; 14 днів безплатно без картки, потім від 24,73 USD за 3 місяці.', 'Yogaia offers online workouts, yoga, Pilates and mindfulness live and on demand: 3,000+ classes, 50+ new live and recorded classes weekly and a personal path; 14 days free with no card, then from 24.73 USD for 3 months.', 'Yogaia допомагає зробити щоденний добробут звичкою. Платформа пропонує онлайн-йогу, йога-нідру, пілатес, медитацію та тренування наживо й на вимогу, тож займатися можна будь-де й будь-коли — на ноутбуці чи в застосунку. Бібліотека містить понад 3000 занять, а щотижня з''являється понад 50 нових живих і записаних класів. Після реєстрації сервіс пропонує персональний шлях під ваші цілі. Спробувати можна безплатно без картки, а триал на 14 днів можна скасувати без оплати; про продовження підписки повідомляють за 7 днів. Квартальна підписка за акцією коштує 24,73 USD за перші три місяці, далі 44,97 USD кожні три місяці.', 'Yogaia helps make everyday wellbeing a habit. The platform offers online yoga, yoga nidra, Pilates, meditation and workouts live and on demand, so you can practice anywhere, anytime — on a laptop or in the app. The library has 3,000+ classes, with 50+ new live and on-demand classes every week. After sign-up the service suggests a personalized path for your goals. You can try it free with no card, and the 14-day trial can be canceled at no charge; you are notified 7 days before renewal. The quarterly plan costs 24.73 USD for the first three months on promotion, then 44.97 USD every three months.', 'Йога, пілатес і медитація
Живі й записані заняття
3000+ занять
50+ нових класів щотижня
Персональний шлях
14 днів безплатно', 'Yoga, Pilates and meditation
Live and on-demand classes
3,000+ classes
50+ new classes weekly
Personalized path
14 days free', 'Люди, які хочуть регулярно займатися йогою та вправами вдома.', 'People who want to practice yoga and exercise at home regularly.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'yogaia.com' OR LOWER(`name`) = LOWER('Yogaia')) ORDER BY `id` LIMIT 1);
