INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'short_description', 'en', 'Yogaia offers online workouts, yoga, Pilates and mindfulness live and on demand: 3,000+ classes, 50+ new live and recorded classes weekly and a personal path; 14 days free with no card, then from 24.73 USD for 3 months.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Yogaia helps make everyday wellbeing a habit. The platform offers online yoga, yoga nidra, Pilates, meditation and workouts live and on demand, so you can practice anywhere, anytime — on a laptop or in the app. The library has 3,000+ classes, with 50+ new live and on-demand classes every week. After sign-up the service suggests a personalized path for your goals. You can try it free with no card, and the 14-day trial can be canceled at no charge; you are notified 7 days before renewal. The quarterly plan costs 24.73 USD for the first three months on promotion, then 44.97 USD every three months.', 'manual' FROM DUAL WHERE @new = 1;
