INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `plan_name_en`, `price`, `period`, `description`, `description_en`) SELECT @pid, '3 місяці', '3 months', 44.97, 'one_time', 'Оплата раз на 3 місяці; перший період за акцією 24,73 USD', 'Billed every 3 months; first period 24.73 USD on promotion' FROM DUAL WHERE @new = 1;
