INSERT IGNORE INTO `pricing_plan_translations` (`plan_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @plan, 'plan_name', 'en', '3 months', 'manual' FROM DUAL WHERE @plan IS NOT NULL;
