-- Zombies, Run! — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'zombiesrungame.com' OR LOWER(`name`) = LOWER('Zombies, Run!'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Zombies, Run!', NULL, 'https://zombiesrungame.com', NULL, NULL, 'Zombies, Run! — фітнес-гра для ходьби, бігу й пробіжок будь-де у світі: понад 500 аудіомісій, погоні ворогів, збір ресурсів, 8-тижнева програма 5K для новачків і пригоди в жанрах фантастики, фентезі та жахів.', 'Zombies, Run! is a fitness game for walking, jogging and running anywhere: 500+ audio missions, enemy chases, supply collection, an 8-week 5K program for beginners and sci-fi, fantasy and horror adventures.', 'Zombies, Run! перетворює тренування на пригоду. Ви ходите, біжите підтюпцем або бігаєте де завгодно, а в навушниках чуєте історію разом із музикою. Якщо за вами женуться вороги, доведеться прискоритися, а під час руху ви автоматично збираєте припаси, які можна обміняти на трофеї чи будівлі для бази. Головна серія містить понад 500 епічних місій про порятунок світу й допомагає розвивати витривалість. Для новачків є 8-тижнева програма підготовки до 5 км від експертів, а серія Venture пропонує науково-фантастичні, фентезійні та жахливі пригоди. Погоні можна вмикати за бажанням, нові тренування з''являються щотижня. Гру нещодавно викупила її співавторка Наомі Олдерман.', 'Zombies, Run! turns your workout into an adventure. You walk, jog or run anywhere in the world and hear the story along with your music through headphones. If enemies chase you, you have to speed up, and as you move you automatically collect supplies to trade for trophies or buildings for your base. The main series has 500+ epic missions to save the world and helps build endurance. Beginners get an expert-designed 8-week 5K training program, and the Venture series offers sci-fi, fantasy and horror adventures. Chases are optional, and new workouts arrive weekly. The game was recently acquired by its co-creator Naomi Alderman.', '500+ аудіомісій
Погоні з прискоренням
Збір ресурсів і розбудова бази
Програма 5K для новачків
Серія пригод Venture
Нові тренування щотижня', '500+ audio missions
Chases that make you speed up
Supply collection and base building
5K program for beginners
Venture adventure series
New workouts weekly', 'Ті, кому нудно просто бігати чи ходити, а також новачки, що хочуть пробігти 5 км.', 'People who find plain running or walking boring, and beginners aiming for a 5K.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
