INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Zombies, Run! turns your workout into an adventure. You walk, jog or run anywhere in the world and hear the story along with your music through headphones. If enemies chase you, you have to speed up, and as you move you automatically collect supplies to trade for trophies or buildings for your base. The main series has 500+ epic missions to save the world and helps build endurance. Beginners get an expert-designed 8-week 5K training program, and the Venture series offers sci-fi, fantasy and horror adventures. Chases are optional, and new workouts arrive weekly. The game was recently acquired by its co-creator Naomi Alderman.', 'manual' FROM DUAL WHERE @new = 1;
